// Late-bound APNs handles. Constructed inside `app.whenReady()` (because
// the token store needs `app.getPath('userData')`). Kept at module scope
// so the ApprovalService can read them via the `getApnsPusher` /
// `getApnsTokenStore` deps it's constructed with.
let bridgeApnsTokenStoreRef: BridgeApnsTokenStore | null = null
let bridgeApnsPusherRef: BridgeApnsPusher | null = null
/**
 * Tier-2 completion trigger — set after the remote bridge runtime exists
 * (its `let` lives inside app.whenReady, so the notify site below can never
 * reference it lexically; the ref is the same late-bind pattern as the
 * fanout). Null means "no Tier-2 path", and the XOR in
 * maybeNotifyRemoteTaskCompletion then simply does nothing for a noop
 * pusher — today's behavior.
 */
let tier2CompletionTriggerRef: ((taskCard: RemoteTaskCard) => void) | null = null

/** Live Activity push tokens + the fanout that keeps a lock-screen card fresh
 *  once the phone can no longer update it itself. Module-level for the same
 *  reason `bridgeApnsPusherRef` is: the store is written from the bridge action
 *  executor and read from the projection loop, which are different scopes.
 *  In-memory only — a token outlives neither the app nor its activity. */
const liveActivityTokenStore = new LiveActivityTokenStore()
const liveActivityPushFanout = new LiveActivityPushFanout({
  store: liveActivityTokenStore,
  // A thunk, not a value: the pusher is rebuilt whenever the user changes their
  // APNs credentials, and a captured reference would go on using the old key.
  sender: () => {
    const pusher = bridgeApnsPusherRef
    return pusher &&
      typeof (pusher as Partial<Http2ApnsPusher>).pushLiveActivityToToken === 'function'
      ? (pusher as Http2ApnsPusher)
      : null
  },
  // Read fresh per push: flipping the master switch or recolouring diffs must
  // take effect immediately, not at the next restart.
  appearance: () => {
    const settings = AppStore.getSettings()
    const diff = normalizeDiffStatColors(settings.diffStatColors)
    return {
      enabled: settings.iosActivityEnabled !== false,
      archetype: settings.iosActivityArchetype ?? DEFAULT_ACTIVITY_ARCHETYPE,
      successHex: Number.parseInt(diff.additions.slice(1), 16),
      failureHex: Number.parseInt(diff.deletions.slice(1), 16)
    }
  },
  log: (line) => {
    console.log(line)
  }
})
const workspaceLiveActivityCoordinator = new WorkspaceLiveActivityCoordinator({
  fanout: liveActivityPushFanout
})
let remoteAttentionApnsFanoutRef: RemoteAttentionApnsFanout | null = null
/** The Mac's 32-byte identity seed (set when the bridge identity loads). Used to
 * seal per-device ENCRYPTED rich push content + to publish the Mac's agreement
 * public key at device registration. Null until the bridge identity loads. */
let macIdentitySeedRef: Buffer | null = null

// Phase B3: late-bound ApprovalService. Owns the five pending-approval
// registries + the scheduled-timeout integration + the APNs wake-push
// fan-out. Stays null until whenReady constructs it; the module-level
// `scheduleApprovalTimeout` / `notifyPairedDevicesOfApproval` /
// `workspaceIdForApprovalPush` helpers are thin proxies that no-op
// until the service is ready.
let approvalService: ApprovalService | null = null
const historyClearAdmissionGate = new HistoryClearAdmissionGate()
const providerRunPersistenceAuthorities = new Map<string, HistoryClearRunPersistenceAuthority>()
// Exact adapter promises are the transport-join authority for destructive
// history deletion. RunManager terminal state alone is insufficient because a
// provider abort/kill can settle before the adapter's close/cleanup callback.
const providerAdapterRunsInFlight = new Map<string, Promise<void>>()
const providerTransportOperations = new ProviderOperationRegistry()
const providerProcessTerminationBackstop = new ProviderProcessTerminationBackstop(4_000)
const hostCommandOperations = new HostCommandOperationRegistry()
const workspaceLockTerminalReconcilerRef = new WorkspaceLockTerminalReconciler({
  lifecycle: workspaceLockRunLifecycle,
  hostCommands: hostCommandOperations,
  getRuntime: () => workspaceLockRuntimeRef,
  getBlockedReason: () => workspaceLockMutationAdmissionPoisonReason,
  clearBlockedReason: clearWorkspaceLockMutationAdmissionPoison,
  logError: (message, error) => console.error(`[workspace-lock] ${message}`, error)
})

async function cancelHostCommandsForRun(appRunId: unknown, reason: string): Promise<void> {
  if (typeof appRunId !== 'string' || !appRunId.trim()) return
  try {
    const cancellation = hostCommandOperations.beginRunCancellation(appRunId.trim(), reason)
    await cancellation.completion
    if (
      cancellation.operationIds.length > 0 &&
      !(await cancellation.processTreeStopped)
    ) {
      await new Promise<void>(() => undefined)
    }
  } catch (error) {
    console.error(`[host-command] Could not cancel commands for run ${appRunId.trim()}:`, error)
    await new Promise<void>(() => undefined)
  }
}

function cancelAbandonedBrokerHostCommands(
  request: Readonly<Record<string, unknown>>,
  _reason: 'client-disconnected'
): void {
  void cancelHostCommandsForRun(request.appRunId, 'mcp-broker-client-disconnected')
}

function cancelTimedOutKimiHostCommands(input: KimiMcpDispatchTimeout): Promise<void> {
  return cancelHostCommandsForRun(input.appRunId, 'kimi-mcp-dispatch-timeout')
}
interface ProviderDispatchReservation {
  authority: HistoryClearDispatchAuthority
  gateReservation: HistoryClearDispatchReservation
}
let deleteChatWithLifecycleRef: ((chatId: string) => Promise<string[]>) | null = null

function providerDispatchAuthorityForPayload(
  payload: AgentRunPayload
): HistoryClearDispatchAuthority {
  const appChatId = requireNonEmptyString(payload.appChatId, 'Dispatch chat id')
  const authority = currentProviderRunPersistenceAuthority(
    appChatId,
    payload.scope === 'global' ? undefined : payload.workspace
  )
  if (!authority) throw new Error('Dispatch chat has no durable persistence authority.')
  return authority
}

function reserveProviderDispatchForPayload(payload: AgentRunPayload): ProviderDispatchReservation {
  const authority = providerDispatchAuthorityForPayload(payload)
  return Object.freeze({
    authority,
    gateReservation: historyClearAdmissionGate.reserveDispatch(authority)
  })
}

function releaseProviderDispatchReservation(reservation: object): void {
  const providerReservation = reservation as ProviderDispatchReservation
  historyClearAdmissionGate.releaseDispatch(providerReservation.gateReservation)
}

function validateProviderDispatchReservation(
  payload: AgentRunPayload,
  reservation: ProviderDispatchReservation | undefined
): HistoryClearDispatchAuthority {
  const currentAuthority = providerDispatchAuthorityForPayload(payload)
  if (
    !reservation ||
    !sameProviderDispatchIncarnation(reservation.authority, currentAuthority) ||
    !historyClearAdmissionGate.authorizeDispatch(reservation.gateReservation, currentAuthority)
  ) {
    throw new Error('Dispatch chat authority changed while provider preflight was pending.')
  }
  return currentAuthority
}

function promoteProviderRunPersistenceAuthority(
  payload: AgentRunPayload,
  reservation: ProviderDispatchReservation
): void {
  const appRunId = requireNonEmptyString(payload.appRunId, 'Provider dispatch run id')
  const currentAuthority = validateProviderDispatchReservation(payload, reservation)
  const persistenceAuthority = historyClearAdmissionGate.promoteDispatch(
    reservation.gateReservation,
    currentAuthority
  )
  if (!persistenceAuthority) {
    throw new Error('Dispatch chat authority changed before output admission.')
  }
  releaseProviderRunPersistenceAuthority(appRunId)
  providerRunPersistenceAuthorities.set(appRunId, persistenceAuthority)
}

function currentProviderRunPersistenceAuthority(
  appChatId: string,
  workspacePath?: string
): HistoryClearDispatchAuthority | null {
  const normalizedChatId = appChatId.trim()
  if (!normalizedChatId) return null
  const chat = AppStore.getChat(normalizedChatId)
  if (!chat) return null
  if (durableHistoryDeletionBlocks(normalizedChatId, chat.workspaceId)) return null
  const persistenceRevision = chat.persistenceRevision
  if (!Number.isSafeInteger(persistenceRevision) || (persistenceRevision ?? -1) < 0) return null
  return {
    appChatId: normalizedChatId,
    workspaceId: chat.workspaceId || workspaceIdForApprovalPush(workspacePath),
    persistenceRevision: persistenceRevision as number
  }
}

function sameProviderDispatchIncarnation(
  left: HistoryClearDispatchAuthority,
  right: HistoryClearDispatchAuthority
): boolean {
  return left.appChatId === right.appChatId && left.workspaceId === right.workspaceId
}

function providerRunPersistenceAuthorized(
  provider: ProviderId,
  route: AgentRunRoute | null | undefined,
  options: { allowTerminal?: boolean } = {}
): boolean {
  const appRunId = route?.appRunId?.trim()
  const appChatId = route?.appChatId?.trim()
  if (!appRunId || !appChatId) return false
  const expected = providerRunPersistenceAuthorities.get(appRunId)
  const session = runManager.get(appRunId)
  if (
    !expected ||
    !session ||
    (!isActiveRunSessionStatus(session.status) &&
      !(options.allowTerminal && isTerminalRunSessionStatus(session.status))) ||
    session.provider !== provider ||
    session.appChatId !== appChatId
  )
    return false
  const current = currentProviderRunPersistenceAuthority(appChatId, session.workspacePath)
  return Boolean(current && historyClearAdmissionGate.authorizeRunPersistence(expected, current))
}

function providerTransportLaunchAuthorized(
  provider: ProviderId,
  payload: AgentRunPayload,
  route: AgentRunRoute
): boolean {
  return providerTransportLaunchStillAuthorized({
    historyBlocked: historyClearAdmissionBlocked(
      route.appRunId,
      payload.workspace,
      route.appChatId
    ),
    persistenceAuthorized: providerRunPersistenceAuthorized(provider, route),
    runAdmitted: runManager.canAdmitTransport(route.appRunId, true),
    setupSignal: payload.providerSetupAbortSignal
  })
}

function settleDeniedProviderTransportLaunch(route: AgentRunRoute): void {
  if (!route.appRunId) return
  settleProviderRunWithoutTransport(runManager, route.appRunId)
}

/** Diagnostic mirror of `providerRunPersistenceAuthorized` — names the limb
 * that denies, for terminal-flush discard warnings. Never used to authorize. */
function explainProviderRunPersistenceDenial(
  provider: ProviderId,
  route: { appRunId?: string; appChatId?: string }
): string {
  const appRunId = route.appRunId?.trim()
  const appChatId = route.appChatId?.trim()
  if (!appRunId || !appChatId) return 'route-incomplete'
  const expected = providerRunPersistenceAuthorities.get(appRunId)
  if (!expected) return 'authority-released'
  const session = runManager.get(appRunId)
  if (!session) return 'session-missing'
  if (session.provider !== provider) return `provider-mismatch(${session.provider})`
  if (session.appChatId !== appChatId) return `chat-mismatch(${session.appChatId})`
  if (!isActiveRunSessionStatus(session.status) && !isTerminalRunSessionStatus(session.status)) {
    return `status(${session.status})`
  }
  const current = currentProviderRunPersistenceAuthority(appChatId, session.workspacePath)
  if (!current) return 'no-current-authority'
  return historyClearAdmissionGate.authorizeRunPersistence(expected, current)
    ? 'authorized-on-recheck'
    : 'incarnation-mismatch'
}

function releaseProviderRunPersistenceAuthority(appRunId: string | undefined): void {
  if (process.env.TASKWRAITH_DEBUG_AUTHORITY === '1' && appRunId) {
    const caller = (new Error().stack || '').split('\n').slice(2, 5).join(' <= ')
    console.warn(`[authority] release run=${appRunId} ${caller}`)
  }
  const normalizedRunId = appRunId?.trim()
  if (!normalizedRunId) return
  const authority = providerRunPersistenceAuthorities.get(normalizedRunId)
  if (authority) historyClearAdmissionGate.releaseRunPersistence(authority)
  providerRunPersistenceAuthorities.delete(normalizedRunId)
}

/**
 * Terminal cleanup for a MAIN-OWNED transcript finalizer (bridge /
 * execution-graph / background sub-thread flushers): both persistence holds
 * together. The RunManager onChange terminal cleanup DEFERS these releases
 * while a finalizer still owns the run — its terminal flush runs a tick after
 * finish() (run-diff capture defers it), and releasing the authority under it
 * made the flush unauthorized, silently discarding the seal and the final
 * assistant text. Every terminal path of the flush machinery must therefore
 * release both holds itself, through this helper.
 */
function releaseMainOwnedRunPersistenceHolds(runId: string): void {
  releaseProviderSessionPersistenceDecision(runId)
  releaseProviderRunPersistenceAuthority(runId)
}

function globalHistoryClearInProgress(): boolean {
  return historyClearAdmissionGate.isGlobalBlocked()
}

// Phase F3: late-bound RunCoordinator ref. The coordinator is
// constructed in whenReady (it needs the in-scope `providerAdapters`
// + the inline helper functions for normalize / preflight / etc.),
// but exposed at module scope so the agent-driven sub-thread
// delegation path (MCP tool `delegate_to_subthread`, executed from
// the top-level `executeGeminiMcpTool`) can fire-and-forget a run on
// the newly-created sub-thread without going through the renderer.
// Stays null until whenReady; the consumer null-checks.
let runCoordinatorRef: RunCoordinator | null = null
let projectReferenceContextAuditServiceRef: ProjectReferenceContextAuditService | null = null
const subThreadMailboxDeliveriesInFlight = new Set<string>()
const subThreadJoinWakeTimers = new Map<string, ReturnType<typeof setTimeout>>()
const subThreadWorkerDrainsInFlight = new Set<string>()
// Provider auto-failover (quota-wall kill-switch) — module-scope state.
// `dispatchRunWithProviderPauseRef` is assigned inside whenReady so the
// failover orchestrator (module scope) can re-dispatch through the same
// pause/reroute seam the renderer + bridge use.
let dispatchRunWithProviderPauseRef:
  | ((
      payload: AgentRunPayload,
      event: { sender: Electron.WebContents }
    ) => Promise<{ dispatched: boolean; appRunId: string }>)
  | null = null
// Scheduled occurrences bypass parent-turn mailbox enrichment. MAIN already
// owns their exact durable prompt + run identity; treating one as an ordinary
// user turn could both splice unrelated child mail into the occurrence and
// clone away the process-local child authorization before the dispatch facade.
let dispatchMainOwnedScheduledOccurrenceRef:
  | ((
      payload: AgentRunPayload,
      event: { sender: Electron.WebContents }
    ) => Promise<{ dispatched: boolean; appRunId: string }>)
  | null = null
const quotaWallSignalByRun = new Map<string, { provider: ProviderId; resetHintAt?: string }>()
const failoverSnapshotByRun = new Map<string, FailoverRunSnapshot>()
const scheduledOccurrenceOwners = new ScheduledOccurrenceOwnerRegistry()
const scheduledOccurrenceTransaction = new ScheduledOccurrenceTransaction({
  store: {
    claimDueScheduledTaskForRun: (taskId, options) =>
      AppStore.claimDueScheduledTaskForRun(taskId, options),
    heartbeatScheduledTaskForRun: (taskId, options) =>
      AppStore.heartbeatScheduledTaskForRun(taskId, options),
    settleScheduledTaskForRun: (taskId, options) =>
      AppStore.settleScheduledTaskForRun(taskId, options)
  },
  owners: scheduledOccurrenceOwners,
  recordRootRunIdTombstone: (input) => AppStore.recordScheduledRunIdTombstone(input),
  resolveRootOwner: (task) => {
    const currentLoop = task.workflowId
      ? AppStore.getWorkflowDefinition(task.workflowId)?.loop
      : undefined
    if (task.kind === 'ensemble') {
      if (currentLoop) {
        throw new Error('Ensemble scheduled occurrences cannot own workflow loops.')
      }
      return 'ensemble-root'
    }
    return currentLoop ? 'loop-root' : 'solo'
  },
  createRunId: (task, rootOwner) =>
    rootOwner === 'ensemble-root'
      ? `ensemble-scheduled-${randomUUID()}`
      : rootOwner === 'loop-root'
        ? `loop-${task.provider}-${randomUUID()}`
        : `${task.provider}-scheduled-${randomUUID()}`,
  now: () => Date.now()
})

// Stage 0b-dispatch — composerServiceRef lets the scheduler compose a run from
// MAIN (the ComposerService is constructed later, in whenReady); headlessRunSender
// stands in for event.sender when there is NO window to stream to. The run-loop
// streams deltas through `.send` (guarded by `.isDestroyed()`) and reads `.id`;
// with no window nothing listens, but disk persistence (appendRunEvent, the
// terminal scheduled-task mark) is sender-INDEPENDENT, so the run still completes
// and is recorded. Every other access resolves to a no-op fn (defensive — the
// dispatch path touches only id/isDestroyed/send).
let composerServiceRef: ComposerService | null = null
/** Late-bound Stop hook firer from whenReady (Wave A host hooks). */
let fireStopHooksForWorkspaceRef:
  | ((
      workspacePath: string,
      status?: string,
      route?: { appRunId?: string; appChatId?: string; provider?: ProviderId }
    ) => void)
  | null = null
const headlessRunSender = new Proxy(
  {},
  {
    get: (_target, prop) => {
      if (prop === 'isDestroyed') return () => false
      if (prop === 'id') return -1
      return () => undefined
    }
  }
) as unknown as Electron.WebContents

// Per-occurrence mid-run BUDGET KILL (WorkflowLimits enforcement). SOLO scheduled
// runs only — ensemble is OUT (no per-participant scheduledTaskId; shared round
// accounting; never failed over). abort = cancelProviderRun (RC1: NOT
// runManager.cancel, which skips Codex's turn/interrupt RPC). The task is marked
// failed at the kill DECISION (triggerKill), not on exit — the default Claude SDK
// abort never reaches sendAgentCompatExit, and the mark must beat the renderer's
// run-end mark. Timers .unref() so an armed kill never holds the loop open at quit.
// Stage 1 slice 3 — resolve a scheduled task's workflow execution id (the run
// ledger's per-execution file key) + its workflowId. undefined for an ad-hoc
// (non-workflow) scheduled task → the caller skips the ledger append (the run
// ledger is workflow-scoped). Same lookup the budget registration uses.
function resolveWorkflowExecutionForTask(
  scheduledTaskId: string | undefined
): { workflowExecutionId: string; workflowId: string } | undefined {
  if (!scheduledTaskId) return undefined
  const task = AppStore.getScheduledTasks().find((t) => t.id === scheduledTaskId)
  if (!task?.workflowExecutionId || !task.workflowId) return undefined
  return { workflowExecutionId: task.workflowExecutionId, workflowId: task.workflowId }
}

// Slice 3 (a) — record a budget breach into the durable run ledger. Best-effort
// (a ledger write must never break the kill / terminal path).
function recordWorkflowBudgetBreach(
  scheduledTaskId: string,
  runId: string,
  breach: { kind: 'tokens' | 'cost' | 'wallclock'; limit: number; observed: number }
): void {
  const resolved = resolveWorkflowExecutionForTask(scheduledTaskId)
  if (!resolved) return
  try {
    AppStore.appendWorkflowRunEvent({
      ...resolved,
      kind: 'budget_breach',
      scheduledTaskId,
      runId,
      breach: { kind: breach.kind, limit: breach.limit, observed: breach.observed }
    })
  } catch (e) {
    console.error('Failed to record workflow budget_breach ledger event', e)
  }
}

// Slice 3 (b) — harvest a finished scheduled run's tokens/cost/duration into the
// run ledger as a forensic 'harvested' annotation (does NOT change lifecycle
// status — it rides alongside the terminal lifecycle event the sync path already
// wrote). `route` is the run state carried into sendAgentCompatExit (tokenUsage +
// startedAt). Best-effort; skipped for a non-workflow task or when there's nothing
// to record (no token signal AND no start time — e.g. a Grok mid-run exit).
function recordWorkflowRunHarvest(scheduledTaskId: string, runId: string, route: unknown): void {
  const task = AppStore.getScheduledTasks().find((t) => t.id === scheduledTaskId)
  if (!task?.workflowExecutionId || !task.workflowId) return
  const usage = (
    route as { tokenUsage?: { total_tokens?: number; total_cost_usd?: number } } | null
  )?.tokenUsage
  const tokens = typeof usage?.total_tokens === 'number' ? usage.total_tokens : undefined
  const costUsd = typeof usage?.total_cost_usd === 'number' ? usage.total_cost_usd : undefined
  // durationMs: prefer the provider stream's startedAt (most precise), else the
  // task's into-running stamp (runningSince → firedAt). The fallback makes duration
  // UNIVERSAL — recorded even for providers / exit paths that pass a BARE route with
  // no stream startedAt (Ollama; every early-error / preflight / setup exit). tokens
  // and costUsd stay best-effort: absent for Ollama (usage rides the result line,
  // not the route) and for early errors (no usage produced yet) — by design.
  const routeStartedAt = (route as { startedAt?: number } | null)?.startedAt
  const startedAtMs =
    typeof routeStartedAt === 'number'
      ? routeStartedAt
      : task.runningSince
        ? Date.parse(task.runningSince)
        : task.firedAt
          ? Date.parse(task.firedAt)
          : Number.NaN
  const durationMs = Number.isFinite(startedAtMs)
    ? Math.max(0, Date.now() - startedAtMs)
    : undefined
  if (tokens === undefined && costUsd === undefined && durationMs === undefined) return
  try {
    AppStore.appendWorkflowRunEvent({
      workflowExecutionId: task.workflowExecutionId,
      workflowId: task.workflowId,
      kind: 'harvested',
      scheduledTaskId,
      runId,
      ...(tokens !== undefined ? { tokens } : {}),
      ...(costUsd !== undefined ? { costUsd } : {}),
      ...(durationMs !== undefined ? { durationMs } : {})
    })
  } catch (e) {
    console.error('Failed to record workflow run harvest ledger event', e)
  }
}

const workflowBudgetRegistry = new WorkflowBudgetRegistry({
  abort: (provider, runId) => {
    void cancelProviderRun(provider, runId)
  },
  markTaskFailed: ({ runId, scheduledTaskId, lastError }) => {
    const owner = scheduledOccurrenceOwners.lookupByOwnerRunId(runId)
    if (!owner || owner.taskId !== scheduledTaskId || owner.rootOwner !== 'solo') return
    const settled = settleScheduledOccurrence(owner, 'failed', {
      completedAt: new Date().toISOString(),
      lastError
    })
    if (!settled) {
      console.error(
        `[workflow-budget] exact scheduled occurrence settlement failed for run ${runId}`
      )
    }
  },
  now: () => Date.now(),
  setTimer: (fn, ms) => {
    const handle = setTimeout(fn, ms)
    handle.unref?.()
    return handle
  },
  clearTimer: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
  onEvent: (event) => {
    if (event.kind === 'killed') {
      console.warn(
        `[workflow-budget] killing run ${event.runId} (${event.provider}, task ${event.scheduledTaskId}): ${event.breach.kind} budget exceeded`
      )
      recordWorkflowBudgetBreach(event.scheduledTaskId, event.runId, event.breach)
    } else if (event.kind === 'task-failed' && event.breach) {
      // POST-HOC grok/cursor overage (onTerminalUsage): no 'killed' event fired for
      // it, so record the breach here so the ledger still captures it.
      recordWorkflowBudgetBreach(event.scheduledTaskId, event.runId, event.breach)
    }
  }
})

/**
 * Re-derive + re-sign a CAPPED, non-escalating permission posture for an
 * auto-failover reroute TARGET. Runs at the dispatch seam after
 * applyReroutePlanToPayload cleared the cross-provider posture, before
 * normalize would downgrade it. Mutates routedPayload in place. Scoped to
 * failover runs so manual reroutes keep their existing fail-closed behavior.
 */
function applyFailoverReroutePosture(
  routedPayload: AgentRunPayload,
  originalPayload: AgentRunPayload
): void {
  applyVerifiedFailoverReroutePosture(routedPayload, originalPayload, {
    settings: AppStore.getSettings(),
    verifyPosture: verifyRunPosture,
    signPosture: signRunPosture
  })
}

/** Snapshot a dispatched request so a future quota wall can re-run it faithfully. */
function captureFailoverSnapshot(payload: AgentRunPayload): FailoverRunSnapshot {
  const sourceRunId = requireNonEmptyString(payload.appRunId, 'Failover source run id')
  return {
    sourceRunId,
    provider: payload.provider,
    scope: payload.scope,
    workspace: payload.workspace,
    prompt: payload.prompt,
    activeGoal: payload.activeGoal,
    appChatId: payload.appChatId,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    effectivePermissions: payload.effectivePermissions,
    effectivePermissionsSignature: payload.effectivePermissionsSignature,
    permissionPostureContext: runPostureContextFromPayload(payload),
    model: payload.model,
    reasoningEffort: payload.reasoningEffort,
    serviceTier: payload.serviceTier,
    claudeReasoningEffort: payload.claudeReasoningEffort,
    claudeFastMode: payload.claudeFastMode,
    kimiThinking: payload.kimiThinking,
    runtimeProfileId: payload.runtimeProfileId,
    geminiAuthProfileId: payload.geminiAuthProfileId,
    failoverHopCount: payload.failoverHopCount,
    // routedPayload is the PRE-normalize raw renderer payload, so scheduledTaskId
    // is still structurally present (normalizeAgentRunPayload strips it).
    scheduledTaskId: (payload as { scheduledTaskId?: string }).scheduledTaskId
  }
}

/** Gate + fire an auto-failover on a terminal failed exit; prune per-run state. */
function maybeTriggerProviderAutoFailover(
  appRunId: string,
  provider: ProviderId,
  appChatId: string | undefined,
  exitCode: number | null
): void {
  const failed = (exitCode ?? -1) !== 0
  const signal = quotaWallSignalByRun.get(appRunId)
  const snapshot = failoverSnapshotByRun.get(appRunId)
  quotaWallSignalByRun.delete(appRunId)
  failoverSnapshotByRun.delete(appRunId)
  if (channelAgentRunIsolationRegistry.isRunIsolated(appRunId)) return
  if (!failed) return
  if (
    scheduledOccurrenceOwners.isAppRunIdLiveOwned(appRunId) ||
    AppStore.getScheduledTasks().some((task) => task.runId === appRunId)
  ) {
    return
  }
  if (!signal || AppStore.getSettings().autoFailoverEnabled !== true) return
  // Dedup is via signal consumption above (signal+snapshot are deleted before
  // we fire), so a second terminal exit for the same run finds no signal and
  // no-ops — no separate triggered-ids set needed.
  // Ensemble participant runs share per-round accounting — never fail them over.
  const chat = appChatId ? AppStore.getChat(appChatId) : undefined
  if (chat?.chatKind === 'ensemble') return
  void triggerProviderAutoFailover(appRunId, provider, appChatId, signal.resetHintAt, snapshot)
}

/** Wire the failover orchestrator to live main-process dependencies. */
async function triggerProviderAutoFailover(
  failedRunId: string,
  failedProvider: ProviderId,
  appChatId: string | undefined,
  resetHintAt: string | undefined,
  snapshot: FailoverRunSnapshot | undefined
): Promise<void> {
  const dispatchRef = dispatchRunWithProviderPauseRef
  if (!dispatchRef) return
  const sender =
    mainWindow?.webContents && !mainWindow.webContents.isDestroyed()
      ? mainWindow.webContents
      : createHeadlessRunSender()
  try {
    await runProviderAutoFailover(
      {
        getSettings: () => AppStore.getSettings(),
        updateSettings: (partial) => AppStore.updateSettings(partial),
        availableProviders: () => selectableProviderIds(),
        isPaused: (candidate) => isProviderPaused(AppStore.getSettings(), candidate),
        signPosture: (mode, eff, ctx) => signRunPosture(mode, eff, ctx),
        verifyPosture: (mode, eff, signature, ctx) =>
          verifyRunPosture(mode, eff, signature, ctx),
        makeRunId: (candidate) => createFallbackRunId(candidate),
        dispatch: (payload) => dispatchRef(payload, { sender }),
        notify: (notice) => emitAutoFailoverNotice(notice)
      },
      { failedRunId, failedProvider, appChatId, snapshot, resetHintAt }
    )
  } catch (error) {
    console.warn('[auto-failover] orchestration failed', error)
  }
}

function emitAutoFailoverNotice(notice: AutoFailoverNotice): void {
  if (notice.kind === 'rerouted') {
    console.info(
      `[auto-failover] ${notice.failedProvider} quota wall → rerouted to ${notice.target} (resets ${notice.until}); new run ${notice.newRunId}`
    )
  } else {
    console.warn(`[auto-failover] ${notice.kind} for ${notice.failedProvider}`)
  }
}
