const ffmpegToolCallBudget = new ImageToolCallBudget()
const vtToolCallBudget = new ImageToolCallBudget()
// ffmpeg/ffprobe MCP tools (S1b). Run the USER-installed binary over a realpath-
// jailed input with a FIXED argv (intents not flags, -protocol_whitelist file).
// The runner is execFile with maxBuffer + timeout — argv array, no shell.
// Bound concurrent ffmpeg encoders (CPU-heavy transcode/thumbnail); ffprobe is
// metadata-only and stays uncapped. Output stages in a dir WE own.
const mediaProcessLimiter = createSemaphore(2)
const MEDIA_STAGING_ROOT = join(app.getPath('userData'), 'media-staging')
const PDF_ATTACHMENT_RENDER_CACHE_ROOT = defaultPdfAttachmentRenderCacheDir(app.getPath('userData'))
const regenerableHistoryByteStore = new RegenerableHistoryByteStore({
  roots: {
    media: MEDIA_STAGING_ROOT,
    pdf: PDF_ATTACHMENT_RENDER_CACHE_ROOT
  },
  journalPath: join(app.getPath('userData'), '.regenerable-history-bytes-purge-v1.json')
})
const producedMediaStagingReservations = new Map<string, RegenerableHistoryByteReservation>()
const COMPOSER_AUDIO_TRANSCRIPTION_MAX_BYTES = 32 * 1024 * 1024

function endRegenerableHistoryByteReservation(
  reservation: RegenerableHistoryByteReservation
): void {
  if (!regenerableHistoryByteStore.end(reservation)) {
    throw new Error('Regenerable history-byte reservation was no longer active.')
  }
}

async function stageWorkspaceMediaSnapshotInHistoryStore(
  options: Omit<StageWorkspaceMediaSnapshotOptions, 'stagingDirectory'>
): Promise<StagedWorkspaceMediaSnapshotResult> {
  const reservation = regenerableHistoryByteStore.begin('media')
  let reservationActive = true
  const releaseReservation = (): void => {
    if (!reservationActive) return
    reservationActive = false
    endRegenerableHistoryByteReservation(reservation)
  }
  try {
    const staged = await stageWorkspaceMediaSnapshot({
      ...options,
      stagingDirectory: reservation.root
    })
    if (!staged.ok) {
      releaseReservation()
      return staged
    }
    if (!regenerableHistoryByteStore.isCurrent(reservation)) {
      try {
        staged.cleanup()
      } finally {
        releaseReservation()
      }
      return { ok: false, reason: 'snapshot_failed' }
    }
    return {
      ...staged,
      cleanup: () => {
        try {
          return staged.cleanup()
        } finally {
          releaseReservation()
        }
      }
    }
  } catch (error) {
    releaseReservation()
    throw error
  }
}

function allocateProducedMediaStagingPath(extension: string): string {
  if (!/^[a-z0-9]{1,10}$/i.test(extension)) {
    throw new Error('Produced-media staging extension is invalid.')
  }
  const reservation = regenerableHistoryByteStore.begin('media')
  const outputPath = join(reservation.root, `tw-${randomUUID()}.${extension.toLowerCase()}`)
  if (producedMediaStagingReservations.has(outputPath)) {
    endRegenerableHistoryByteReservation(reservation)
    throw new Error('Produced-media staging path collided with an active reservation.')
  }
  producedMediaStagingReservations.set(outputPath, reservation)
  return outputPath
}

function releaseProducedMediaStagingPath(outputPath: string): void {
  const reservation = producedMediaStagingReservations.get(outputPath)
  if (!reservation || reservation.root !== dirname(outputPath)) {
    throw new Error('Produced-media staging path has no active reservation.')
  }
  producedMediaStagingReservations.delete(outputPath)
  try {
    fsSync.unlinkSync(outputPath)
  } catch (error) {
    if ((error as NodeJS.ErrnoException)?.code !== 'ENOENT') throw error
  } finally {
    endRegenerableHistoryByteReservation(reservation)
  }
}

async function readDescriptorAnchoredMediaFile(
  filePath: string,
  maxBytes: number
): Promise<Buffer> {
  const reservation = producedMediaStagingReservations.get(filePath)
  if (reservation && !regenerableHistoryByteStore.isCurrent(reservation)) {
    throw new Error('Produced-media output was revoked by history deletion.')
  }
  if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) {
    throw new Error('invalid output byte limit')
  }
  const pathStat = await fs.lstat(filePath)
  if (pathStat.isSymbolicLink() || !pathStat.isFile()) {
    throw new Error('output is not a regular file')
  }
  const handle = await fs.open(filePath, fsSync.constants.O_RDONLY | fsSync.constants.O_NOFOLLOW)
  let output: Buffer | null = null
  let failure: unknown = null
  try {
    const stat = await handle.stat()
    const uid = typeof process.getuid === 'function' ? process.getuid() : null
    const sameSnapshot = (left: fsSync.Stats, right: fsSync.Stats): boolean =>
      left.dev === right.dev &&
      left.ino === right.ino &&
      left.size === right.size &&
      left.mtimeMs === right.mtimeMs &&
      left.ctimeMs === right.ctimeMs
    if (
      !stat.isFile() ||
      !sameSnapshot(stat, pathStat) ||
      (uid !== null && (stat.uid !== uid || pathStat.uid !== uid))
    ) {
      throw new Error('output changed before read')
    }
    if (!Number.isSafeInteger(stat.size) || stat.size < 0) {
      throw new Error('output has an invalid size')
    }
    if (stat.size > maxBytes) {
      throw new Error(`output too large (${stat.size} bytes; max ${maxBytes})`)
    }
    const buffer = Buffer.allocUnsafe(stat.size)
    let offset = 0
    while (offset < stat.size) {
      const read = await handle.read(buffer, offset, stat.size - offset, offset)
      if (read.bytesRead <= 0) throw new Error('output ended before its declared size')
      offset += read.bytesRead
    }
    const [finalStat, finalPathStat] = await Promise.all([handle.stat(), fs.lstat(filePath)])
    if (
      finalPathStat.isSymbolicLink() ||
      !finalPathStat.isFile() ||
      !sameSnapshot(finalStat, stat) ||
      !sameSnapshot(finalPathStat, stat)
    ) {
      throw new Error('output changed during read')
    }
    if (reservation && !regenerableHistoryByteStore.isCurrent(reservation)) {
      throw new Error('Produced-media output was revoked during read.')
    }
    output = buffer
  } catch (error) {
    failure = error
  }
  return completeRegenerableHistoryByteOperation({
    cleanup: () => handle.close().catch(() => undefined),
    isCurrent: () => !reservation || regenerableHistoryByteStore.isCurrent(reservation),
    onCurrent: () => {
      if (failure) throw failure
      if (!output) throw new Error('Produced-media output read completed without bytes.')
      return output
    },
    onRevoked: () => {
      throw new Error('Produced-media output was revoked before read completion.')
    }
  })
}

interface ProducedMediaToolContext {
  appChatId?: string
  appRunId?: string
}

async function persistMediaOutputFile(
  filePath: string,
  mimeType: string,
  ctx: ProducedMediaToolContext
): Promise<ToolMediaPersistOutput> {
  const stagingReservation = producedMediaStagingReservations.get(filePath)
  if (stagingReservation && !regenerableHistoryByteStore.isCurrent(stagingReservation)) {
    return { ok: false, reason: 'authority_lost' }
  }
  const appChatId = ctx.appChatId?.trim()
  const appRunId = ctx.appRunId?.trim()
  if (!appChatId || !appRunId) return { ok: false, reason: 'authority_lost' }
  const session = runManager.get(appRunId)
  if (!session || session.appChatId !== appChatId) {
    return { ok: false, reason: 'authority_lost' }
  }
  const route = { appChatId, appRunId }
  const provider = session.provider
  const isAuthorized = (): boolean => providerRunPersistenceAuthorized(provider, route)
  const mediaStore = getTranscriptMediaAssetStore()
  const persisted = await mediaProcessLimiter.run(() =>
    mediaStore.writeOwnedContentAddressedFromFile({
      sourcePath: filePath,
      mimeType,
      appChatId,
      isAuthorized
    })
  )
  if (!persisted.ok) return persisted
  const { ownershipReceipt, ...result } = persisted
  return {
    ...result,
    pendingToolMediaPersistence: {
      commit: () => mediaStore.commitOwnedFileWrite(ownershipReceipt),
      rollback: async () => {
        const rolledBack = await mediaStore.rollbackOwnedFileWriteStrict(ownershipReceipt)
        if (!rolledBack) {
          throw new Error('Produced-media persistence receipt was no longer active at rollback.')
        }
      }
    }
  }
}

type ComposerAudioTranscriptionResult =
  | {
      ok: true
      text: string
      segments: Array<{ text: string; startMs: number; endMs: number; confidence: number }>
      localeIdentifier: string
      onDevice: boolean
    }
  | { ok: false; error: string }

function bufferFromComposerAudioPayload(rawWav: unknown): Buffer | null {
  if (Buffer.isBuffer(rawWav)) return rawWav
  if (rawWav instanceof ArrayBuffer) return Buffer.from(new Uint8Array(rawWav))
  if (ArrayBuffer.isView(rawWav)) {
    return Buffer.from(rawWav.buffer, rawWav.byteOffset, rawWav.byteLength)
  }
  return null
}

function isPcmWavBuffer(buffer: Buffer): boolean {
  return (
    buffer.length >= 44 &&
    buffer.toString('ascii', 0, 4) === 'RIFF' &&
    buffer.toString('ascii', 8, 12) === 'WAVE' &&
    buffer.toString('ascii', 12, 16) === 'fmt ' &&
    buffer.toString('ascii', 36, 40) === 'data'
  )
}

function normalizeComposerAudioLocale(rawLocale: unknown): string | undefined {
  if (typeof rawLocale !== 'string') return undefined
  const locale = rawLocale.trim()
  if (!locale || locale.length > 32) return undefined
  return locale
}

async function transcribeComposerAudioPayload(
  rawInput: unknown
): Promise<ComposerAudioTranscriptionResult> {
  if (process.platform !== 'darwin') {
    return { ok: false, error: 'Local dictation is not available on this platform yet.' }
  }
  const input = asRecord(rawInput)
  const wav = bufferFromComposerAudioPayload(input?.wav)
  if (!wav || wav.length === 0) return { ok: false, error: 'No microphone audio was captured.' }
  if (wav.length > COMPOSER_AUDIO_TRANSCRIPTION_MAX_BYTES) {
    return { ok: false, error: 'Microphone recording is too long to transcribe.' }
  }
  if (!isPcmWavBuffer(wav))
    return { ok: false, error: 'Microphone recording was not valid WAV audio.' }
  const daemon = bridgeDaemonRef
  if (!daemon) return { ok: false, error: 'Audio transcription service is not running.' }

  let reservation: RegenerableHistoryByteReservation
  try {
    reservation = regenerableHistoryByteStore.begin('media')
  } catch (error) {
    return {
      ok: false,
      error:
        error instanceof Error
          ? error.message
          : 'Local dictation storage is unavailable during history deletion.'
    }
  }
  const sourcePath = join(reservation.root, `composer-dictation-${randomUUID()}.wav`)
  let outcome: ComposerAudioTranscriptionResult
  try {
    await fs.writeFile(sourcePath, wav, { mode: 0o600 })
    const result = await mediaProcessLimiter.run(() =>
      daemon.request<{
        text: string
        segments: Array<{ text: string; startMs: number; endMs: number; confidence: number }>
        localeIdentifier: string
        onDevice: boolean
      }>(
        'audio.transcribe',
        { sourcePath, localeIdentifier: normalizeComposerAudioLocale(input?.localeIdentifier) },
        { timeoutMs: 120_000 }
      )
    )
    if (!regenerableHistoryByteStore.isCurrent(reservation)) {
      outcome = {
        ok: false,
        error: 'Local dictation was cancelled because history was cleared.'
      }
    } else if (result.onDevice !== true) {
      outcome = { ok: false, error: 'Local dictation refused a non-local transcription result.' }
    } else {
      outcome = {
        ok: true,
        text: typeof result.text === 'string' ? result.text : '',
        segments: Array.isArray(result.segments)
          ? result.segments
              .filter((segment) => segment && typeof segment.text === 'string')
              .map((segment) => ({
                text: segment.text,
                startMs: Number.isFinite(segment.startMs) ? segment.startMs : 0,
                endMs: Number.isFinite(segment.endMs) ? segment.endMs : 0,
                confidence: Number.isFinite(segment.confidence) ? segment.confidence : 0
              }))
          : [],
        localeIdentifier:
          typeof result.localeIdentifier === 'string' ? result.localeIdentifier : 'en-US',
        onDevice: true
      }
    }
  } catch (error) {
    outcome = {
      ok: false,
      error: error instanceof Error ? error.message : 'Local dictation failed.'
    }
  }
  return completeRegenerableHistoryByteOperation({
    cleanup: () => fs.rm(sourcePath, { force: true }).catch(() => undefined),
    isCurrent: () => regenerableHistoryByteStore.isCurrent(reservation),
    release: () => endRegenerableHistoryByteReservation(reservation),
    onCurrent: () => outcome,
    onRevoked: () => ({
      ok: false,
      error: 'Local dictation was cancelled because history was cleared.'
    })
  })
}
const ffmpegToolExecutors = createFfmpegToolExecutors({
  jailInput: async (sourcePath, ctx) => {
    const chat = ctx.appChatId ? AppStore.getChat(ctx.appChatId) : null
    if (!chat || !ctx.workspacePath) {
      return { ok: false, reason: 'no workspace to resolve sourcePath' }
    }
    const staged = await stageWorkspaceMediaSnapshotInHistoryStore({
      workspacePath: ctx.workspacePath,
      candidatePath: sourcePath,
      externalPathGrants: executableExternalPathGrantsForRun(chat, ctx.appRunId),
      kind: 'audio_video'
    })
    return staged.ok
      ? {
          ok: true,
          realPath: staged.realPath,
          mimeType: staged.mimeType,
          cleanup: staged.cleanup
        }
      : { ok: false, reason: staged.reason }
  },
  resolveFfprobe: () => resolveFfmpegBinaries().ffprobePath,
  // ffprobe is metadata-only (cheap CPU) but still spawns a subprocess; gate it on
  // the SAME concurrency semaphore as ffmpeg so N agents can't spawn N concurrent
  // probes. argv, no shell.
  runFfprobe: (binaryPath, args) =>
    mediaProcessLimiter.run(
      () =>
        new Promise((resolve, reject) => {
          execFile(
            binaryPath,
            args,
            { maxBuffer: 16 * 1024 * 1024, timeout: 60_000, shell: false },
            (err, stdout, stderr) => {
              if (err) {
                // Light error clarity: distinguish the two non-obvious failure
                // modes (timed-out vs metadata-too-large) from a real probe error
                // so the model gets an actionable message, not a bare exit code.
                const e = err as NodeJS.ErrnoException & { killed?: boolean; signal?: string }
                const detail =
                  e.code === 'ERR_CHILD_PROCESS_STDIO_MAXBUFFER'
                    ? 'metadata output exceeded 16MB (file has pathologically many streams/tags)'
                    : e.killed || e.signal === 'SIGTERM'
                      ? 'ffprobe timed out after 60s'
                      : String(stderr).trim() || err.message
                reject(new Error(`ffprobe failed: ${detail}`))
              } else resolve({ stdout, stderr })
            }
          )
        })
    ),
  resolveFfmpeg: () => resolveFfmpegBinaries().ffmpegPath,
  // Encoders are CPU-heavy + can run minutes — longer timeout, gated by the
  // concurrency semaphore so N agents can't spawn N encoders. argv, no shell.
  runFfmpeg: (binaryPath, args) =>
    mediaProcessLimiter.run(
      () =>
        new Promise((resolve, reject) => {
          execFile(
            binaryPath,
            args,
            { maxBuffer: 4 * 1024 * 1024, timeout: 300_000, shell: false },
            (err, stdout, stderr) => {
              if (err) reject(new Error(`ffmpeg failed: ${String(stderr).trim() || err.message}`))
              else resolve({ stdout, stderr })
            }
          )
        })
    ),
  stagingPath: (ext) => {
    return allocateProducedMediaStagingPath(ext)
  },
  // Only the bounded PNG thumbnail lane still materializes producer output.
  // Descriptor anchoring rejects symlinks/path replacement and the image cap is
  // applied before allocating the buffer.
  readOutput: (filePath, mimeType) =>
    readDescriptorAnchoredMediaFile(filePath, maxTranscriptMediaBytesForMime(mimeType)),
  removeFile: (filePath) => {
    releaseProducedMediaStagingPath(filePath)
  },
  // S1b-3 — bounded async copy+hash into the content-addressed store. The helper
  // runs under the shared media limiter and returns the durable canonical path.
  persistOutputFile: persistMediaOutputFile,
  // Quick-win — a small poster/waveform so the AV card isn't blank. Fail-tolerant
  // (undefined on any error); see generateAvPoster.
  generatePoster: generateAvPoster,
  missingMessage: (which) => ffmpegMissingError(which)
})

// S2 — native VideoToolbox single-frame decode in the Swift bridge daemon (NO
// ffmpeg needed; hardware-accelerated). The realpath jail mirrors the ffmpeg one
// (TS owns the security boundary; the daemon just opens the path it's handed).
// decodeFrame is the `video.decodeFrame` daemon RPC; the decoded PNG rides the
// PROVEN image-block lane (createToolResultMediaRefs), so no trusted-AV channel.
// Document tools (PDF text + on-device OCR). The wiring lives in
// ./documents/DocumentToolWiring so this hotspot only supplies what it actually
// owns: run authorization and the mutable bridge-daemon handle.
const documentToolExecutors = createWiredDocumentToolExecutors({
  authorize: (ctx) => {
    const chat = ctx.appChatId ? AppStore.getChat(ctx.appChatId) : null
    if (!chat?.workspacePath) return null
    return {
      workspacePath: chat.workspacePath,
      externalPathGrants: executableExternalPathGrantsForRun(chat, ctx.appRunId)
    }
  },
  requestDaemon: (method, params, options) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('OCR bridge daemon is not running')
    return daemon.request(method, params, options)
  },
  // Passed by reference so the staging still runs inside this module's
  // synchronous history-byte reservation.
  stageImage: stageWorkspaceMediaSnapshotInHistoryStore,
  // Vision is macOS-only and rides the bundled daemon, so reuse the same gate the
  // other native tools report through rather than inventing a second answer.
  isOcrAvailable: () => {
    const capabilities = getNativeCapabilitySnapshot()
    return capabilities.ocr.available
      ? { available: true }
      : { available: false, reason: capabilities.ocr.reason }
  }
})

const vtToolExecutors = createVtToolExecutors({
  jailInput: async (sourcePath, ctx) => {
    const chat = ctx.appChatId ? AppStore.getChat(ctx.appChatId) : null
    if (!chat || !ctx.workspacePath) {
      return { ok: false, reason: 'no workspace to resolve sourcePath' }
    }
    const staged = await stageWorkspaceMediaSnapshotInHistoryStore({
      workspacePath: ctx.workspacePath,
      candidatePath: sourcePath,
      externalPathGrants: executableExternalPathGrantsForRun(chat, ctx.appRunId),
      kind: 'audio_video'
    })
    return staged.ok
      ? { ok: true, realPath: staged.realPath, cleanup: staged.cleanup }
      : { ok: false, reason: staged.reason }
  },
  // S3-2 — jail an OVERLAY image (PNG/JPEG/WebP). MUST use the IMAGE validator
  // (validateWorkspaceImagePath sniffs raster mime, rejects SVG, size-caps), NOT
  // the video jailInput above (validateWorkspaceMediaPath rejects a PNG as
  // 'unsupported' since it only sniffs audio/video).
  jailOverlay: async (overlayPath, ctx) => {
    const chat = ctx.appChatId ? AppStore.getChat(ctx.appChatId) : null
    if (!chat || !ctx.workspacePath) {
      return { ok: false, reason: 'no workspace to resolve overlayPath' }
    }
    const staged = await stageWorkspaceMediaSnapshotInHistoryStore({
      workspacePath: ctx.workspacePath,
      candidatePath: overlayPath,
      externalPathGrants: executableExternalPathGrantsForRun(chat, ctx.appRunId),
      maxBytes: TRANSCRIPT_MEDIA_MAX_WORKSPACE_IMAGE_BYTES,
      kind: 'image'
    })
    return staged.ok
      ? { ok: true, realPath: staged.realPath, cleanup: staged.cleanup }
      : { ok: false, reason: staged.reason }
  },
  decodeFrame: async (params) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('video bridge daemon is not running')
    return daemon.request<{
      pngBase64: string
      width: number
      height: number
      timestampSeconds: number
      codec: string
      usedHardware: boolean
    }>('video.decodeFrame', params, { timeoutMs: 30_000 })
  },
  // S3 — native VideoToolbox encode. The daemon writes the MP4 to the TS-owned
  // staging path and returns metadata; TS persists + removes it (the
  // ffmpeg-producer pattern, but daemon-backed). 5-min timeout mirrors runFfmpeg.
  encodeClip: async (params) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('video bridge daemon is not running')
    // Share the ffmpeg encoders' concurrency semaphore (max 2): a native VT encode
    // contends for the same CPU/GPU/disk as transcode_video, so an ensemble can't
    // spawn N simultaneous multi-minute 512MB encodes (adversarial review).
    return mediaProcessLimiter.run(() =>
      daemon.request<{
        width: number
        height: number
        durationMs: number
        codec: string
        usedHardware: boolean
      }>('video.encodeClip', params, { timeoutMs: 300_000 })
    )
  },
  // S3-3 — native VideoToolbox concat (N segments → one MP4). Shares the
  // mediaProcessLimiter semaphore (a concat of many segments holds a slot for up
  // to 10 min, contending with transcode_video like the encoders do). The daemon
  // letterboxes mismatched-dimension segments to the first segment's size.
  concatClips: async (params) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('video bridge daemon is not running')
    return mediaProcessLimiter.run(() =>
      daemon.request<{
        width: number
        height: number
        durationMs: number
        codec: string
        usedHardware: boolean
        segmentCount: number
      }>('video.concatClips', params, { timeoutMs: 600_000 })
    )
  },
  // S4 — native audio mixdown (N tracks → one WAV/M4A). Shares the mediaProcessLimiter
  // semaphore (a multi-track mix contends for the same CPU/disk as the video encoders),
  // and uses the same 5-min daemon timeout as encodeClip.
  mixdown: async (params) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('audio bridge daemon is not running')
    return mediaProcessLimiter.run(() =>
      daemon.request<{
        durationMs: number
        sampleRate: number
        channels: number
        codec: string
        trackCount: number
      }>('audio.mixdown', params, { timeoutMs: 300_000 })
    )
  },
  // transcribe_audio — native on-device speech-to-text (Speech framework). Heavy
  // (the recognizer chews CPU on a long file), so gate it on the SAME
  // mediaProcessLimiter (max 2) the encoders/mixdown use, with a 2-min timeout. The
  // daemon recognizes ON-DEVICE ONLY; a denied OS permission rejects with the
  // actionable "enable it in System Settings" message which surfaces to the model.
  transcribe: async (params) => {
    const daemon = bridgeDaemonRef
    if (!daemon) throw new Error('audio bridge daemon is not running')
    return mediaProcessLimiter.run(() =>
      daemon.request<{
        text: string
        segments: Array<{ text: string; startMs: number; endMs: number; confidence: number }>
        localeIdentifier: string
        onDevice: boolean
      }>('audio.transcribe', params, { timeoutMs: 120_000 })
    )
  },
  // The output-file deps mirror the ffmpeg factory exactly (same generation-fenced staging root
  // and content-addressed store) so a daemon-produced MP4 rides the
  // identical persist→buildAvMediaRef→trustedMediaRefs lane as transcode_video.
  stagingPath: (ext) => {
    return allocateProducedMediaStagingPath(ext)
  },
  persistOutputFile: persistMediaOutputFile,
  // Quick-win — a small poster/waveform so the AV card isn't blank. Fail-tolerant
  // (undefined on any error); see generateAvPoster.
  generatePoster: generateAvPoster,
  removeFile: (filePath) => {
    releaseProducedMediaStagingPath(filePath)
  }
})

// image_generate egress. Endpoints are a FIXED allowlist (never agent-controlled),
// the API key comes from safeStorage and rides only in the Authorization header
// (never argv/curl), and any image URL the provider returns is SSRF-guarded
// (public-only) + size-capped before fetch. Default OFF.
const IMAGE_GEN_ENDPOINTS: Record<ImageGenProvider, string> = {
  openai: 'https://api.openai.com/v1/images/generations',
  xai: 'https://api.x.ai/v1/images/generations'
}
const IMAGE_GEN_MODELS: Record<ImageGenProvider, string> = {
  openai: 'gpt-image-1',
  xai: 'grok-2-image'
}
function decryptImageGenKey(provider: ImageGenProvider): string | null {
  const encrypted = AppStore.getSettings().imageGeneration?.encryptedKeys?.[provider]
  if (!encrypted || !safeStorage.isEncryptionAvailable()) return null
  try {
    return safeStorage.decryptString(Buffer.from(encrypted, 'base64'))
  } catch {
    return null
  }
}
function imageGenConfiguredProviders(): ImageGenProvider[] {
  const keys = AppStore.getSettings().imageGeneration?.encryptedKeys
  const out: ImageGenProvider[] = []
  if (keys?.openai) out.push('openai')
  if (keys?.xai) out.push('xai')
  return out
}
function imageGenConfig(): ImageGenConfig {
  const ig = AppStore.getSettings().imageGeneration
  return {
    enabled: Boolean(ig?.enabled),
    defaultProvider: ig?.provider === 'xai' ? 'xai' : 'openai',
    configuredProviders: imageGenConfiguredProviders()
  }
}
const IMAGE_GEN_REQUEST_TIMEOUT_MS = 60_000
const IMAGE_GEN_IMAGE_FETCH_TIMEOUT_MS = 30_000
// fetch + a hard abort timeout: neither `fetch` nor the broker cap bounds the
// socket here, so a slow/hostile endpoint would otherwise hang the run.
async function imageGenFetch(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  try {
    return await fetch(url, { ...init, signal: controller.signal })
  } finally {
    clearTimeout(timer)
  }
}
async function generateImageViaApi(input: {
  provider: ImageGenProvider
  prompt: string
  size?: string
}): Promise<ImageGenResult> {
  const key = decryptImageGenKey(input.provider)
  if (!key) return { ok: false, reason: `no usable API key for ${input.provider}` }
  const body: Record<string, unknown> = {
    model: IMAGE_GEN_MODELS[input.provider],
    prompt: input.prompt,
    n: 1
  }
  if (input.provider === 'openai') {
    body.size = input.size && /^\d{2,4}x\d{2,4}$/.test(input.size) ? input.size : '1024x1024'
  }
  let response: Response
  try {
    response = await imageGenFetch(
      IMAGE_GEN_ENDPOINTS[input.provider],
      {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${key}` },
        body: JSON.stringify(body),
        redirect: 'error'
      },
      IMAGE_GEN_REQUEST_TIMEOUT_MS
    )
  } catch (error) {
    return {
      ok: false,
      reason: `request failed: ${error instanceof Error ? error.message : String(error)}`
    }
  }
  if (!response.ok)
    return { ok: false, reason: `${input.provider} image API returned HTTP ${response.status}` }
  const parsed = parseImageGenResponse(await response.json().catch(() => null))
  if (!parsed.ok) return { ok: false, reason: parsed.reason }
  if (parsed.b64) {
    const buffer = Buffer.from(parsed.b64, 'base64')
    if (buffer.length > TRANSCRIPT_MEDIA_MAX_FULL_IMAGE_BYTES) {
      return { ok: false, reason: 'generated image exceeds the size limit' }
    }
    return { ok: true, buffer, mimeType: 'image/png' }
  }
  // URL fallback — fetch the provider's image, public-only (SSRF guard) + capped.
  try {
    await assertFetchTargetAllowed(parsed.url as string)
  } catch {
    return { ok: false, reason: 'provider returned a non-public image URL' }
  }
  try {
    const imageResponse = await imageGenFetch(
      parsed.url as string,
      { redirect: 'error' },
      IMAGE_GEN_IMAGE_FETCH_TIMEOUT_MS
    )
    if (!imageResponse.ok) return { ok: false, reason: `image fetch HTTP ${imageResponse.status}` }
    // Reject before buffering if the host declares an oversized body (a hostile
    // host could otherwise stream GBs into arrayBuffer and OOM the process).
    const declaredLength = Number(imageResponse.headers?.get?.('content-length') || 0)
    if (declaredLength > TRANSCRIPT_MEDIA_MAX_FULL_IMAGE_BYTES) {
      return { ok: false, reason: 'generated image exceeds the size limit' }
    }
    const buffer = Buffer.from(await imageResponse.arrayBuffer())
    if (buffer.length > TRANSCRIPT_MEDIA_MAX_FULL_IMAGE_BYTES) {
      return { ok: false, reason: 'generated image exceeds the size limit' }
    }
    return { ok: true, buffer, mimeType: 'image/png' }
  } catch (error) {
    return {
      ok: false,
      reason: `image fetch failed: ${error instanceof Error ? error.message : String(error)}`
    }
  }
}
const imageGenExecutor = createImageGenExecutor({
  getConfig: imageGenConfig,
  generate: generateImageViaApi
})
// Cross-thread retrospection (recall). Slice 1 wires it inert; Slice 2 passes
// the resolver deps (run-queue / chat-list / workspaces / run-events).
// Live remote-workspace allowlist (set at main-init below). Recall from a
// remote/phone-issued run is scoped to the workspaces this device may monitor.
let recallBridgeAllowlist: RemoteWorkspaceAllowlist | null = null
let externalPublishReceiptLedger: ExternalPublishReceiptWriter | null | undefined

function getExternalPublishReceiptLedger(): ExternalPublishReceiptWriter | null {
  if (externalPublishReceiptLedger !== undefined) return externalPublishReceiptLedger
  externalPublishReceiptLedger = createDefaultExternalPublishReceiptLedger({
    log: (line) => console.warn(line)
  })
  return externalPublishReceiptLedger
}

function externalPublishPolicyDecision(origin: ExternalPublishOrigin): {
  decision: 'allowed' | 'denied'
  reason: string
} {
  const policy = AppStore.getSettings().agenticServices?.externalPublish ?? 'ask'
  if (policy === 'deny') {
    return {
      decision: 'denied',
      reason: 'External publishing is blocked by policy.'
    }
  }
  if (origin === 'agent') {
    return {
      decision: 'allowed',
      reason: 'Agent external publishing passed TaskWraith external-publish policy.'
    }
  }
  if (origin === 'ios-bridge') {
    return {
      decision: 'allowed',
      reason: 'External publishing was initiated from a paired TaskWraith device.'
    }
  }
  return {
    decision: 'allowed',
    reason: 'External publishing was initiated by a human-controlled TaskWraith surface.'
  }
}

async function beginExternalPublishReceipt(
  input: Omit<ExternalPublishReceiptInput, 'decision' | 'reason'>
): Promise<ExternalPublishReceipt> {
  const ledger = getExternalPublishReceiptLedger()
  const decision = externalPublishPolicyDecision(input.origin)
  if (!ledger) {
    return {
      schemaVersion: 1,
      id: '',
      ...input,
      decision: 'denied',
      reason:
        decision.decision === 'denied'
          ? decision.reason
          : 'External publishing receipt ledger is unavailable.',
      requestedAt: new Date().toISOString()
    }
  }
  try {
    return ledger.begin({
      ...input,
      decision: decision.decision,
      reason: decision.reason
    })
  } catch (err) {
    return {
      schemaVersion: 1,
      id: '',
      ...input,
      decision: 'denied',
      reason: `External publishing receipt could not be recorded: ${
        err instanceof Error ? err.message : String(err)
      }`,
      requestedAt: new Date().toISOString()
    }
  }
}

async function completeExternalPublishReceipt(
  receipt: ExternalPublishReceipt | null,
  input: Omit<ExternalPublishReceiptCompletion, 'id'>
): Promise<void> {
  if (!receipt?.id) return
  try {
    await getExternalPublishReceiptLedger()?.complete({ id: receipt.id, ...input })
  } catch (err) {
    console.warn(
      `[ExternalPublishReceiptLedger] completion failed: ${err instanceof Error ? err.message : String(err)}`
    )
  }
}

function externalPublishReceiptsForOrigin(
  origin: ExternalPublishOrigin
): Pick<ExternalPublishReceiptWriter, 'begin' | 'complete'> {
  return {
    begin: async (input) => beginExternalPublishReceipt({ ...input, origin }),
    complete: async (input) => getExternalPublishReceiptLedger()?.complete(input) ?? null
  }
}

function listExternalPublishReceipts(): ExternalPublishReceipt[] {
  const ledger = getExternalPublishReceiptLedger()
  if (!ledger || typeof (ledger as { list?: unknown }).list !== 'function') return []
  return ledger.list()
}

/**
 * `thread_message` — peer thread-to-thread send. Self-gating like the recall
 * family: the decision logic is the pure `evaluateThreadMessageGate`, resolved by
 * `createThreadMessageAccessResolver`, which owns the approval-ledger row for
 * every allow no human saw. This block is wiring only.
 */
/**
 * Does this chat have an approval authority that is NOT an external human?
 *
 * A configured Boss is mandatory; configured Captains are fallback seats. An
 * authority held by an external is no authority at all for permission
 * purposes. If every configured authority is external, consent recorded on the
 * ensemble must stop elevating anything.
 *
 * Wiring only: the decision is `hasNonExternalApprovalAuthority` in
 * ExternalSeatResolution, where it is unit-tested. This gate FAILS CLOSED when
 * externals cannot be enumerated — an unknown set is not an empty one. It used
 * to fail open on the premise that an external id cannot satisfy a live-roster
 * check; that premise defends the id rather than the decision, and the
 * Channel-native seat authority can legitimately answer "recovery blocked".
 */
function hasNonExternalApprovalAuthority(
  chatId: string | undefined,
  chat: {
    ensemble?: {
      bossmanParticipantId?: string
      captainParticipantIds?: string[]
      secondInCommandParticipantId?: string
    }
  } | null
): boolean {
  return evaluateNonExternalApprovalAuthority({
    ensemble: chat?.ensemble ?? null,
    // null means "cannot enumerate externals", which the evaluator refuses.
    externalSeatIds:
      chatId && resolveExternalCollaboratorSeatIds
        ? resolveExternalCollaboratorSeatIds(chatId)
        : null
  })
}

/**
 * App Drive authority for the calling run.
 *
 * Putting a real running app under agent control is a control action, so in an
 * Ensemble it belongs to the Boss and its Captains. Solo threads are
 * unaffected. The caller's participant id comes from the live run (falling back
 * to the persisted run record); authority is then decided purely by id
 * equality against the roster — never by `role`/`stageRole`, which
 * participants can patch through `ensemble_roster_edit`.
 */
function appDriveEnsembleAuthorityForRun(
  appChatId: string | undefined,
  appRunId: string | undefined
): { ok: true } | { ok: false; reason: string } {
  const chat = appChatId ? AppStore.getChat(appChatId) : null
  const ensemble = chat?.ensemble
  if (!ensemble) return { ok: true }
  const session = appRunId ? runManager.get(appRunId) : null
  const state = session?.state as { ensembleRun?: { participantId?: string } } | undefined
  const persisted = appRunId ? (chat?.runs || []).find((run) => run.runId === appRunId) : undefined
  return resolveAppDriveEnsembleAuthority({
    ensemble,
    callerParticipantId: state?.ensembleRun?.participantId || persisted?.ensembleParticipantId
  })
}

const threadMessageAccessResolver = createThreadMessageAccessResolver({
  resolveServicePolicy: ({ context }) => {
    const ctx = context as { effectivePermissions?: EffectiveRunPermissions }
    // `?? 'ask'` because the field is optional for settings persisted before this
    // service existed. Absent must fail to a PROMPT, never to an allow.
    return (
      effectiveAgenticSettings(AppStore.getSettings(), ctx.effectivePermissions).agenticServices
        .threadMessage ?? 'ask'
    )
  },
  isReadOnlyRun: ({ context }) =>
    (context as { effectivePermissions?: EffectiveRunPermissions }).effectivePermissions
      ?.readOnly === true,
  isRemoteOriginRun: ({ context }) => isRemoteOriginRun(context.appRunId),
  resolveElevation: ({ context, parentProvider }) => {
    const ctx = context as { effectivePermissions?: EffectiveRunPermissions }
    const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
    const consent = chat?.ensemble?.bossmanAutoApprovals
    return {
      fullAccess: isFullShellAccessGranted(ctx.effectivePermissions),
      // Task-scoped Full Access for THIS chat/provider/workspace, not a
      // merely write-capable posture.
      trustedSession: Boolean(
        context.appChatId &&
        context.workspacePath &&
        trustedSessionGrants.isGranted({
          chatId: context.appChatId,
          provider: parentProvider as ProviderId,
          workspacePath: context.workspacePath
        })
      ),
      // The recorded user consent is the signal here. WHICH model participant
      // holds the authority is `evaluateBossmanAutoApproval`'s question, and
      // that gate deliberately never covers non-shell/file services — see
      // ThreadMessagePermission for why elevation lives in our own gate.
      //
      // One identity question this gate MUST answer for itself, though: an
      // authority held by an EXTERNAL human collaborator elevates nothing.
      // Externals never receive approval prompts, so treating their authority as
      // consent would let a thread-wide flag carry an unattended wake — a turn
      // started in another thread with nobody watching — on the strength of
      // someone who is never asked. `evaluateBossmanAutoApproval` cannot cover
      // it: this path never reaches that gate.
      bossAutoApproval:
        consent?.enabled === true &&
        consent.mode === 'permission_preset_once' &&
        hasNonExternalApprovalAuthority(context.appChatId, chat)
    }
  },
  requestApproval: async ({ context, parentProvider, crossWorkspace, requestedDelivery }) => {
    const ctx = context as { sender?: Electron.WebContents }
    return await requestAgenticServiceApproval(
      ctx.sender ?? null,
      parentProvider as ProviderId,
      'threadMessage',
      context.workspacePath,
      {
        method: `${parentProvider}-mcp/thread_message`,
        title: `Approve ${providerLabel(parentProvider as ProviderId)} thread message`,
        body: crossWorkspace
          ? 'send a message to a thread in another workspace'
          : requestedDelivery === 'wake'
            ? 'send a message and start a turn in another thread'
            : 'send a message to another thread',
        preview: { kind: 'tool', toolName: 'thread_message', params: {} },
        runId: context.appRunId
      }
    )
  },
  recordAutoAllowLedgerRow: ({ context, parentProvider }, metadata) => {
    const approvalId = `thread-message-${String(metadata.toChatId)}-${String(
      metadata.decisionReason
    )}-${Date.now()}`
    recordApprovalLedgerRequest(
      parentProvider as ProviderId,
      { appRunId: context.appRunId, appChatId: context.appChatId },
      {
        approvalId,
        method: `${parentProvider}-mcp/thread_message`,
        title: 'Thread message auto-allowed',
        body: String(metadata.rationale || 'Thread message auto-allowed.')
      },
      { service: 'threadMessage', workspacePath: context.workspacePath, metadata }
    )
  }
})

/**
 * Sweeps pending peer-message wake requests into runs. Held as a ref because the
 * dispatcher needs the run-dispatch path, which only exists after app-ready, while
 * the senders that trigger a sweep are constructed at module scope.
 *
 * Deliberately NOT given `signRunPermissionPosture` — see ThreadMessageWakeDispatcher.
 */
let threadMessageWakeDispatcherRef: ReturnType<typeof createThreadMessageWakeDispatcher> | null =
  null

function sweepThreadMessageWakes(): void {
  // Fire-and-forget with an explicit catch: a wake sweep must never fail the send
  // that triggered it — the message is already durably queued, and the dispatcher
  // retries on the next sweep.
  void threadMessageWakeDispatcherRef?.dispatchPendingWakes().catch((error) => {
    console.error('Failed to sweep thread-message wakes', error)
  })
}

const threadMessageToolExecutors = createThreadMessageToolExecutors({
  listTargetChats: () =>
    AppStore.getChats().map((chat) => ({
      chatId: chat.appChatId,
      title: chat.title || '',
      workspaceId: chat.workspaceId || null,
      archived: chat.archived === true
    })),
  resolveCallerChat: (context) => {
    const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
    if (!chat) return null
    return {
      chatId: chat.appChatId,
      title: chat.title || '',
      workspaceId: chat.workspaceId || null,
      archived: chat.archived === true
    }
  },
  resolveThreadMessageAccess: (input) => threadMessageAccessResolver(input),
  enqueueThreadMessage: (event) => AppStore.enqueueThreadMessage(event),
  mintThreadMessageId: (fromChatId, toChatId, nonce) =>
    createThreadMessageId(fromChatId, toChatId, nonce),
  now: () => Date.now(),
  notifyThreadMessageQueued: (event) => {
    const targetChat = AppStore.getChat(event.toChatId)
    if (targetChat) broadcastChatUpdated(targetChat)
    sweepThreadMessageWakes()
  },
  // The sending seat, captured now and stored on the message, so the receiving
  // card can say WHO sent it. `getParticipantIdForRun` names the roster seat
  // that actually made the tool call; without it (solo chats, unscoped callers)
  // the chat's own provider/model is used, and when neither resolves the seat
  // is omitted rather than guessed.
  resolveCallerSeat: (context) => {
    const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
    if (!chat) return null
    const participantId = ensembleOrchestratorRef?.getParticipantIdForRun(context.appRunId) || ''
    return resolveThreadMessageSenderSeat(chat, participantId)
  }
})

const recallToolExecutors = createRecallToolExecutors({
  listRunQueueJobs: (filter) => AppStore.getRunQueueJobs(filter),
  getWorkspaces: () => AppStore.getWorkspaces(),
  resolveCallerWorkspaceId: (context) => {
    const workspaces = AppStore.getWorkspaces()
    const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
    const fromChat = chat?.workspaceId
      ? resolveCanonicalWorkspaceId(chat.workspaceId, workspaces, canonicalPath)
      : null
    if (fromChat) return fromChat
    return context.workspacePath
      ? resolveCanonicalWorkspaceId(context.workspacePath, workspaces, canonicalPath)
      : null
  },
  loadChatText: (chatId) => {
    const chat = AppStore.getChat(chatId)
    if (!chat) return null
    const parts: string[] = [chat.title || '']
    for (const message of chat.messages || []) {
      if (isRetiredExternalChannelInboundMessage(message)) continue
      if (message.role === 'user' || message.role === 'assistant') {
        parts.push(message.content || '')
      }
    }
    return parts.join('\n').slice(0, 20000)
  },
  isForensicsAvailable: (runId) => AppStore.hasRunForensics(runId),
  getRunQueueJob: (runId) => AppStore.getRunQueueJob(runId),
  getRunEvents: (runId) => AppStore.getRunEvents({ runId }),
  loadFinalAssistantMessage: ({ runId, chatId }) => {
    if (!chatId) return null
    const chat = AppStore.getChat(chatId)
    if (!chat) return null
    const message = [...(chat.messages || [])]
      .reverse()
      .find((m) => m.role === 'assistant' && m.runId === runId)
    return message?.content?.trim() || null
  },
  loadPlanProgress: ({ runId, chatId }) => {
    if (!chatId) return null
    try {
      const chat = AppStore.getChat(chatId)
      if (!chat) return null
      // Latest todo/plan activity wins — the run's most recent checklist state.
      let items: TodoItem[] = []
      for (const message of chat.messages || []) {
        if (message.runId !== runId) continue
        for (const activity of message.toolActivities || []) {
          if (!isTodoToolName(activity.toolName)) continue
          const parsed = parseTodoItemsFromActivity({
            toolName: activity.toolName,
            parameters: activity.parameters,
            resultSummary: activity.resultSummary,
            outputPreview: activity.outputPreview
          })
          if (parsed.length) items = parsed
        }
      }
      if (!items.length) return null
      return {
        done: items.filter((item) => item.status === 'completed').length,
        total: items.length
      }
    } catch {
      return null
    }
  },
  mintCitationToken: ({ runId, kind, currentRunId }) => {
    const inner = `${kind}:${runId}`
    if (currentRunId) recordRecallCitation(currentRunId, inner)
    return formatRecallCitation(inner)
  },
  resolveRecallAccess: async ({
    context,
    parentProvider,
    crossWorkspace,
    targetWorkspacePath,
    targetWorkspaceId
  }) => {
    const ctx = context as RecallToolContext & {
      effectivePermissions?: EffectiveRunPermissions
      sender?: Electron.WebContents
    }
    // Remote/phone-issued runs may only investigate workspaces this device is
    // allowlisted to monitor. Times resolve in the Mac's LOCAL timezone (echoed
    // in the interpretation) — no phone-tz propagation needed.
    if (isRemoteOriginRun(ctx.appRunId)) {
      const decision =
        targetWorkspaceId && recallBridgeAllowlist
          ? recallBridgeAllowlist.evaluate({
              workspaceId: targetWorkspaceId,
              capability: 'monitor'
            })
          : { allowed: false }
      if (!decision.allowed) {
        return { allowed: false, reason: 'not_allowlisted' }
      }
    }
    // Read-only seat / cross-thread reads disabled in settings → refuse outright.
    const effSettings = effectiveAgenticSettings(AppStore.getSettings(), ctx.effectivePermissions)
    if (effSettings.agenticServices.crossThreadRead === 'deny') {
      return { allowed: false, reason: 'denied' }
    }
    // Caller's OWN workspace → auto-allow (no prompt). A different workspace
    // prompts the dedicated crossThreadRead service (grantable/expiring).
    if (!crossWorkspace) return { allowed: true }
    const approved = await requestAgenticServiceApproval(
      ctx.sender ?? null,
      parentProvider as ProviderId,
      'crossThreadRead',
      targetWorkspacePath ?? ctx.workspacePath,
      {
        method: `${parentProvider}-mcp/tw_recall`,
        title: `Approve ${providerLabel(parentProvider as ProviderId)} cross-thread read`,
        body: 'cross-thread read',
        preview: { kind: 'tool', toolName: 'tw_recall', params: {} },
        runId: ctx.appRunId
      }
    )
    return approved ? { allowed: true } : { allowed: false, reason: 'declined' }
  },
  now: () => Date.now(),
  normalizePath: canonicalPath
})

function resolveIntrospectionCallerWorkspaceId(context: IntrospectionToolContext): string | null {
  const workspaces = AppStore.getWorkspaces()
  const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
  const fromChat = chat?.workspaceId
    ? resolveCanonicalWorkspaceId(chat.workspaceId, workspaces, canonicalPath)
    : null
  if (fromChat) return fromChat
  return context.workspacePath
    ? resolveCanonicalWorkspaceId(context.workspacePath, workspaces, canonicalPath)
    : null
}

