// M11 (1.0.7) — sticky AppWatch: per-chat remembered attachment snapshots,
// persisted so they survive an app restart. The controller serializes
// cross-chat read-modify-write mutations while retaining best-effort disk
// persistence.
function stickyAppWatchPath(): string {
  return join(app.getPath('userData'), 'sticky-appwatch.json')
}
const stickyAppWatchStoreController = new StickyAppWatchStoreController({
  load: () => readJsonFile(stickyAppWatchPath()),
  persist: (next) => writeJsonFile(stickyAppWatchPath(), next),
  onPersistError: (error) => console.error('[sticky-appwatch] persist failed:', error)
})

async function readJsonFile(filePath: string): Promise<any | null> {
  try {
    return JSON.parse(await fs.readFile(filePath, 'utf8'))
  } catch {
    return null
  }
}

async function writeJsonFile(filePath: string, value: any): Promise<void> {
  await fs.mkdir(dirname(filePath), { recursive: true })
  await fs.writeFile(filePath, `${JSON.stringify(value, null, 2)}\n`, 'utf8')
}

const backgroundSubThreadTranscripts = new Map<string, BackgroundSubThreadTranscriptState>()

// Cross-provider reroutes are intentionally ephemeral: the destination
// provider has no canonical session lane on the source chat/seat. The central
// Claude session writer observes this through the MCP fence, while these ids
// keep older transcript closeout paths from independently writing the target
// session back onto the source owner.
const MAX_PROVIDER_SESSION_PERSISTENCE_DECISIONS = 512
const providerSessionPersistenceSuppressedRunIds = new Map<string, true>()
const channelAgentRunIsolationRegistry = new ChannelAgentRunIsolationRegistry()

function suppressProviderSessionPersistenceForRun(runId: string): void {
  providerSessionPersistenceSuppressedRunIds.delete(runId)
  providerSessionPersistenceSuppressedRunIds.set(runId, true)
  while (
    providerSessionPersistenceSuppressedRunIds.size > MAX_PROVIDER_SESSION_PERSISTENCE_DECISIONS
  ) {
    const oldestRunId = providerSessionPersistenceSuppressedRunIds.keys().next().value
    if (typeof oldestRunId !== 'string') break
    providerSessionPersistenceSuppressedRunIds.delete(oldestRunId)
  }
}

function shouldPersistProviderSessionForRun(runId: string): boolean {
  return (
    !channelAgentRunIsolationRegistry.isRunIsolated(runId) &&
    !providerSessionPersistenceSuppressedRunIds.has(runId)
  )
}

function recordProviderRunUsage(entry: Omit<UsageRecord, 'id' | 'timestamp'>): void {
  if (!channelAgentRunIsolationRegistry.isRunIsolated(entry.runId)) {
    AppStore.recordUsage(entry)
    return
  }
  AppStore.recordUsage(redactChannelAgentUsageContent(entry))
}

function releaseProviderSessionPersistenceDecision(runId: string): void {
  providerSessionPersistenceSuppressedRunIds.delete(runId)
}

/** iOS / bridge-initiated runs skip the renderer's `activeRunsRef`
 * registration, so provider compat lines would otherwise stream to
 * raw logs without persisting assistant text. Mirror the background
 * sub-thread transcript path: accumulate in main and flush to
 * `AppStore` so both Mac and phone snapshots stay live. */
type BridgeRunTranscriptState = {
  owner: 'bridge' | 'execution_graph'
  runId: string
  chatId: string
  provider: ProviderId
  promptMessageId: string
  assistantMessageId: string
  /** Tool-role sibling message carrying the run's ToolActivity stack. */
  toolMessageId: string
  startedAt: string
  content: string
  /** Ordered text/tool segments — interleaved like the desktop transcript
   * (text, tool burst, text, ...). Each part becomes its own message. */
  parts: Array<{
    id: string
    kind: 'text' | 'tools'
    content: string
    mediaRefs?: TranscriptMediaRef[]
    activities: ToolActivity[]
  }>
  streamBuffer?: string
  actualModel?: string
  modelLabel?: string
  providerSessionId?: string | null
  stats?: Record<string, unknown>
  status: 'running' | 'success' | 'failed' | 'cancelled'
  errorMessage?: string
  flushedOnce: boolean
  flushTimer?: NodeJS.Timeout
  /** Wall-clock ms of the last ingested event / lifecycle transition. The
   * `isChatRunLive` transcript probe only counts an entry as live while this
   * is recent (BRIDGE_TRANSCRIPT_ACTIVITY_GRACE_MS) — a leaked entry (terminal
   * flush threw, lane never finalized) must decay instead of pinning the run
   * live and blocking the stale-run reconciler for the whole process. */
  lastActivityAt?: number
  /** Activities parsed from tool_use/tool_result compat events. */
  activities: ToolActivity[]
  /** Codex item id of the last appended content delta — a transition
   * marks a NEW agentMessage item, which the desktop separates with a
   * horizontal rule instead of letting bursts jam into one paragraph. */
  lastContentItemId?: string
  /** Captured before dispatch; diffed against a post-run snapshot at
   * finalize so bridge runs get run.runDiff like desktop runs do. */
  preSnapshot?: WorkspaceSnapshot
  workspacePath?: string
  /** Secondary-workspace grants: pre-run snapshots keyed by path. */
  extraPreSnapshots?: Record<string, WorkspaceSnapshot>
  extraWorkspacePaths?: string[]
  runDiff?: ChatRun['runDiff']
  runDiffByPath?: ChatRun['runDiffByPath']
  executionGraphBinding?: ExecutionGraphAttemptResultBinding
  providerTerminalCandidate?: 'completed' | 'failed' | 'cancelled'
  providerTerminalCandidateConflict?: boolean
}

const bridgeRunTranscripts = new Map<string, BridgeRunTranscriptState>()

/** Stamp a transcript entry as recently active (see `lastActivityAt`). */
function touchBridgeRunTranscript(state: BridgeRunTranscriptState): void {
  state.lastActivityAt = Date.now()
}

function bridgeRunRouteMatches(
  state: BridgeRunTranscriptState,
  provider: ProviderId,
  chatId: string | undefined
): boolean {
  if (state.provider !== provider) return false
  return state.owner === 'execution_graph'
    ? chatId === state.chatId
    : !chatId || chatId === state.chatId
}
let pushBridgeRunSnapshot: ((chat: ChatRecord) => void) | null = null
let pushBridgeRunTaskCardDelta: ((chatId: string) => void) | null = null
/** Kicks the remote-composer queue pump (assigned in app.whenReady with the
 * rest of the queue closure). Module-scoped so the stale-run reconciler and
 * cancelProviderRun can nudge the pump after settling a job that was the
 * phantom keeping a chat's queued prompts blocked. */
let scheduleRemoteComposerQueuePumpRef: (() => void) | null = null
let pushRemoteThreadSnapshotForChat: ((chat: ChatRecord) => boolean) | null = null

/**
 * Phase B3 — thin proxy. Delegates to `approvalService.scheduleTimeout`
 * once the service is initialized. Kept at module scope so the
 * existing `pending*Approvals.set` call sites (which currently live
 * scattered through `runXxxProvider` functions) can call into the
 * service without changing every site to pass the service explicitly.
 */
function scheduleApprovalTimeout(args: {
  approvalId: string
  provider: ProviderId
  route?: AgentRunRoute | null
  isMainAuthority?: boolean
  kind?: string
}): void {
  approvalService?.scheduleTimeout(args)
}

/**
 * Live wrapper around `isUserAtDesktop` (pure logic in
 * `./ApnsIdleGate.ts`). Reads window-focus + system-idle from the
 * Electron runtime; the pure helper handles the env-var gating and
 * threshold logic. Fail-open: any throw returns false so an approval
 * push always goes out when in doubt.
 */
function userIsAtDesktop(): boolean {
  try {
    return pureIsUserAtDesktop({
      idleGateEnv: process.env.TASKWRAITH_APNS_IDLE_GATE,
      idleThresholdEnv: process.env.TASKWRAITH_APNS_IDLE_THRESHOLD_S,
      windowFocused: mainWindow?.isFocused?.() === true,
      idleSec:
        typeof powerMonitor?.getSystemIdleTime === 'function' ? powerMonitor.getSystemIdleTime() : 0
    })
  } catch {
    return false
  }
}

/**
 * Notify all paired iOS devices that an approval needs the user's
 * decision. Best-effort: fires per-device pushes via APNs in parallel,
 * doesn't block the caller, and silently no-ops when APNs is
 * un-configured (the factory returns `NoopApnsPusher` which doesn't
 * expose `pushApprovalToToken`).
 *
 * Token cleanup: only Apple's `Unregistered` response proves that a device
 * token is permanently invalid, so the fan-out prunes only that reason.
 * `BadDeviceToken` can be an APNs environment mismatch; the live token is
 * retained and the mismatch is logged.
 *
 * Call sites: every place a `pendingXxxApprovals.set(approvalId, ...)`
 * happens — host commands, Codex permissions/elicitation/userInput,
 * Gemini tool prompts, Kimi prompts, main approval flow.
 */
/** Phase B3 — thin proxy. Delegates to `approvalService.notifyPairedDevices`
 * once the service is initialized; no-op until then. */
function notifyPairedDevicesOfApproval(args: {
  approvalId: string
  workspaceId: string | null
  threadId: string
  summary: string
}): void {
  if (remoteAttentionApnsFanoutRef) {
    remoteAttentionApnsFanoutRef.notify({
      reason: 'approval',
      workspaceId: args.workspaceId,
      threadId: args.threadId,
      approvalId: args.approvalId,
      projectionKind: 'MobileApprovalCard'
    })
    return
  }
  approvalService?.notifyPairedDevices({
    ...args,
    summary: 'Open TaskWraith to respond.'
  })
}

/**
 * Resolve a workspace path to its store-managed opaque `WorkspaceRecord.id`.
 * APNs payloads must never contain local filesystem paths, so unregistered
 * workspace paths deliberately omit the workspace id instead of falling back
 * to the path.
 */
function workspaceIdForApprovalPush(workspacePath: string | undefined): string | null {
  if (!workspacePath) return 'global'
  try {
    const record = findRegisteredWorkspace(workspacePath)
    return record?.id ?? null
  } catch {
    return null
  }
}

function workspaceIdForHistoryClearAuthority(
  runId?: string,
  explicitWorkspacePath?: string
): string | null {
  const session = runId ? runManager.get(runId) : undefined
  const chatId = session?.appChatId
  if (chatId) {
    const chat = AppStore.getChat(chatId)
    if (chat?.workspaceId) return chat.workspaceId
  }
  const workspacePath = explicitWorkspacePath || session?.workspacePath
  return workspacePath ? workspaceIdForApprovalPush(workspacePath) : null
}

function durableHistoryDeletionBlocks(
  chatId?: string | null,
  workspaceId?: string | null
): boolean {
  let pending: HistoryDeletionPreparation | null
  try {
    pending = AppStore.getPendingHistoryDeletion()
  } catch {
    // An unreadable destructive intent is not evidence that a scope is safe.
    return true
  }
  if (!pending) return false
  if (pending.kind === 'global') return true
  if (chatId && pending.chatIds.includes(chatId)) return true
  return Boolean(pending.kind === 'workspace' && workspaceId && pending.workspaceId === workspaceId)
}

function historyClearAdmissionBlocked(
  runId?: string,
  workspacePath?: string,
  chatId?: string
): boolean {
  if (historyClearAdmissionGate.isGlobalBlocked()) return true
  const session = runId ? runManager.get(runId) : undefined
  const authoritativeChatId = chatId || session?.appChatId
  const chat = authoritativeChatId ? AppStore.getChat(authoritativeChatId) : null
  const pathWorkspaceId = workspacePath
    ? workspaceIdForApprovalPush(workspacePath)
    : session?.workspacePath
      ? workspaceIdForApprovalPush(session.workspacePath)
      : null
  if (durableHistoryDeletionBlocks(authoritativeChatId, chat?.workspaceId || pathWorkspaceId)) {
    return true
  }
  return historyClearAdmissionGate.isAuthorityBlocked({
    chatId: authoritativeChatId,
    chatWorkspaceId: chat?.workspaceId,
    pathWorkspaceId
  })
}

function assertParentChatRelationshipCreationAllowed(parentChatId: string): void {
  const seen = new Set<string>()
  let chat = AppStore.getChat(parentChatId)
  if (!chat) throw new Error('Parent chat authority is unavailable.')
  while (chat && !seen.has(chat.appChatId)) {
    seen.add(chat.appChatId)
    if (historyClearAdmissionBlocked(undefined, chat.workspacePath, chat.appChatId)) {
      throw new Error('Parent chat is being deleted or cleared.')
    }
    chat = chat.parentChatId ? AppStore.getChat(chat.parentChatId) : null
  }
}

function historyClearBlocksRunPayload(payload: AgentRunPayload): boolean {
  if (historyClearAdmissionGate.isGlobalBlocked()) return true
  const chat = payload.appChatId ? AppStore.getChat(payload.appChatId) : null
  const pathWorkspaceId =
    payload.scope === 'global' ? null : workspaceIdForApprovalPush(payload.workspace)
  if (durableHistoryDeletionBlocks(payload.appChatId, chat?.workspaceId || pathWorkspaceId)) {
    return true
  }
  return historyClearAdmissionGate.isAuthorityBlocked({
    chatId: payload.appChatId,
    chatWorkspaceId: chat?.workspaceId,
    pathWorkspaceId
  })
}

