function executionGraphOwnsOrAnchorsRunId(runId: string | undefined): boolean {
  return isExecutionGraphReservedRunIdentity({
    runId,
    getRunQueueJob: (runIdOrId) => AppStore.getRunQueueJob(runIdOrId),
    listExecutions: () =>
      executionGraphCoordinatorRef?.listExecutions({ includeTerminal: true }) ?? []
  })
}

function executionGraphOwnsAttemptRunId(runId: string | undefined): boolean {
  if (!runId) return false
  const queued = AppStore.getRunQueueJob(runId)
  if (queued?.runId === runId && queued.executionGraph) return true
  return Boolean(
    executionGraphCoordinatorRef
      ?.listExecutions({ includeTerminal: true })
      .some((projection) =>
        Object.values(projection.attempts).some((attempt) => attempt.providerRunRef === runId)
      )
  )
}

function clearExecutionGraphTerminalJoinWatchdog(runId: string): void {
  const timer = executionGraphTerminalJoinWatchdogs.get(runId)
  if (timer) clearTimeout(timer)
  executionGraphTerminalJoinWatchdogs.delete(runId)
}

function armExecutionGraphTerminalJoinWatchdog(runId: string): void {
  if (executionGraphTerminalJoinWatchdogs.has(runId)) return

  const schedule = (delayMs: number): void => {
    const timer = setTimeout(() => {
      executionGraphTerminalJoinWatchdogs.delete(runId)
      const session = runManager.get(runId)
      const decision = decideExecutionGraphTerminalJoinWatchdog({
        active: Boolean(
          session &&
          isActiveRunSessionStatus(session.status) &&
          executionGraphOwnsAttemptRunId(runId)
        ),
        nowMs: Date.now(),
        state: runManager.getTerminalJoinState(runId)
      })
      if (decision.kind === 'stop') return
      if (decision.kind === 'wait') {
        schedule(decision.delayMs)
        return
      }
      void containExecutionGraphTerminalJoin(runId, decision.reason).catch((error) => {
        console.error(
          `[ExecutionGraph] terminal join containment failed for runId=${runId}:`,
          error
        )
      })
    }, delayMs)
    timer.unref?.()
    executionGraphTerminalJoinWatchdogs.set(runId, timer)
  }

  schedule(0)
}

function isExecutionGraphIsolatedPayload(payload: AgentRunPayload): boolean {
  const runId = payload.appRunId?.trim()
  if (!runId || !executionGraphDispatchesInFlight.has(runId)) return false
  const admission = executionGraphAdapterAdmissions.get(runId)
  const job = AppStore.getRunQueueJob(runId)
  return Boolean(
    admission &&
    job?.executionGraph &&
    job.runId === runId &&
    admission.executionId === job.executionGraph.executionId &&
    admission.attemptId === job.executionGraph.attemptId &&
    admission.payload.provider === payload.provider &&
    admission.payload.appChatId === payload.appChatId
  )
}

function isMainOwnedContextIsolatedPayload(payload: AgentRunPayload): boolean {
  return (
    isExecutionGraphIsolatedPayload(payload) ||
    channelAgentRunIsolationRegistry.isPayloadIsolated(payload)
  )
}

function getActiveTaskWraithThreadCount(): number {
  const chatIds = new Set<string>()
  let anonymousRuns = 0
  for (const provider of RUN_MANAGER_PROVIDERS) {
    for (const session of runManager.getActiveByProvider(provider)) {
      if (session.appChatId) {
        chatIds.add(session.appChatId)
      } else {
        anonymousRuns += 1
      }
    }
  }
  return chatIds.size + anonymousRuns
}

function hasActiveStreamingTaskWraithRun(): boolean {
  return hasStreamingRemoteRunSessions(
    RUN_MANAGER_PROVIDERS.flatMap((provider) => runManager.getActiveByProvider(provider))
  )
}

