function trustStatusAllowsRun(status: string | undefined): boolean {
  return status === 'trusted' || status === 'inherited'
}

async function ensureWorkspaceTrustForRun(
  sender: Electron.WebContents,
  payload: AgentRunPayload,
  reservation?: object
): Promise<boolean> {
  if (payload.scope === 'global') return true
  if (payload.provider !== 'gemini') return true
  const trust = TrustStatusService.checkTrust(payload.workspace || '')
  if (trustStatusAllowsRun(trust.status)) return true

  const route = routeWithRunId('gemini', payload)
  payload.appRunId = route.appRunId
  if (payload.sessionTrust) {
    const approved = await requestMainApproval(sender, 'gemini', route, {
      method: 'workspace/session-trust',
      title: 'Approve session-only workspace trust',
      body: `${payload.workspace}\n${trust.reason || trust.status}`,
      workspacePath: payload.workspace,
      preview: {
        kind: 'workspaceTrust',
        workspacePath: payload.workspace,
        trustStatus: trust.status,
        reason: trust.reason,
        duration: 'thisRun'
      }
    })
    if (approved) return true
  }

  sendProviderPreflightError(
    sender,
    'gemini',
    `Gemini run blocked because workspace trust is ${trust.status}${trust.reason ? `: ${trust.reason}` : '.'}`,
    route,
    reservation
  )
  sendProviderPreflightExit(sender, 'gemini', -1, route, reservation)
  return false
}

function resolveGeminiMcpScopedPath(context: GeminiToolContext, filePath: string): string {
  if (typeof filePath !== 'string' || !filePath.trim()) {
    throw new Error(
      context.scope === 'global' ? 'A host path is required.' : 'A workspace path is required.'
    )
  }
  if (context.scope === 'global') {
    return isAbsolute(filePath) ? resolve(filePath) : resolve(context.cwd, filePath)
  }
  return resolveGeminiMcpPath(context.workspacePath || context.cwd, filePath)
}

function externalPathGrantForTarget(
  context: GeminiToolContext,
  provider: ProviderId,
  targetPath: string,
  access: 'read' | 'write'
): ExternalPathGrant | undefined {
  const chat = context.appChatId ? AppStore.getChat(context.appChatId) : null
  const grants = executableExternalPathGrantsForRun(chat, context.appRunId).filter(
    (grant) => grant.provider === provider
  )
  const target = (canonicalExternalGrantPath(targetPath) || resolve(targetPath)).replace(/\/+$/, '')
  return grants.find((grant) => {
    // `grant.path` is the signed canonical authority. Re-realpathing it here
    // would let a later symlink replacement retarget that signature.
    const grantPath = resolve(grant.path).replace(/\/+$/, '')
    try {
      const grantStat = fsSync.lstatSync(grantPath)
      if (grantStat.isSymbolicLink()) return false
      if (grant.kind === 'directory' ? !grantStat.isDirectory() : !grantStat.isFile()) {
        return false
      }
    } catch {
      return false
    }
    const coversPath =
      target === grantPath || (grant.kind === 'directory' && target.startsWith(grantPath + sep))
    if (!coversPath) return false
    return access === 'read' || grant.access === 'write'
  })
}

function resolveGeminiMcpGrantAwarePath(
  context: GeminiToolContext,
  provider: ProviderId,
  filePath: string,
  access: 'read' | 'write',
  options: { allowWorkspaceRoot?: boolean } = {}
): string {
  return resolveGeminiMcpGrantAwarePathAuthority(context, provider, filePath, access, options)
    .targetPath
}

function resolveGeminiMcpGrantAwarePathAuthority(
  context: GeminiToolContext,
  provider: ProviderId,
  filePath: string,
  access: 'read' | 'write',
  options: { allowWorkspaceRoot?: boolean } = {}
): ScopedPathAuthority {
  if (typeof filePath !== 'string' || !filePath.trim()) {
    throw new Error(
      context.scope === 'global' ? 'A host path is required.' : 'A workspace path is required.'
    )
  }
  if (context.scope === 'global') {
    const lexicalTarget = isAbsolute(filePath) ? resolve(filePath) : resolve(context.cwd, filePath)
    const targetPath = canonicalExternalGrantPath(lexicalTarget) || lexicalTarget
    return {
      rootPath: dirname(targetPath) === targetPath ? targetPath : dirname(targetPath),
      targetPath
    }
  }

  const lexicalWorkspaceRoot = resolve(context.workspacePath || context.cwd)
  const workspaceRoot = canonicalExternalGrantPath(lexicalWorkspaceRoot)
  if (!workspaceRoot) throw new Error('Active workspace could not be resolved safely.')
  const lexicalTarget = isAbsolute(filePath)
    ? resolve(filePath)
    : resolve(lexicalWorkspaceRoot, filePath)
  const targetPath = canonicalExternalGrantPath(lexicalTarget)
  if (!targetPath) throw new Error('Selected path could not be resolved safely.')
  if (isPathInsideWorkspace(workspaceRoot, targetPath)) {
    return {
      rootPath: workspaceRoot,
      targetPath: resolveGeminiMcpPath(workspaceRoot, targetPath, options)
    }
  }
  if (
    canAutoApproveTrustedSessionExternalWrite({
      provider,
      chatId: context.appChatId,
      workspacePath: context.workspacePath,
      runtimeProfileId: context.runtimeProfileId,
      ensembleRun: context.ensembleRun,
      effectivePermissions: context.effectivePermissions,
      externalPathAccess: access,
      isTrustedSessionGranted: (scope) => trustedSessionGrants.isGranted(scope)
    })
  ) {
    return {
      rootPath: dirname(targetPath),
      targetPath
    }
  }
  if (isAbsolute(filePath)) {
    const grant = externalPathGrantForTarget(context, provider, targetPath, access)
    if (grant) {
      const grantPath = resolve(grant.path)
      return {
        rootPath: grant.kind === 'directory' ? grantPath : dirname(grantPath),
        targetPath
      }
    }
  }
  const accessLabel = access === 'write' ? 'edit' : 'read'
  throw new Error(`Path is outside the workspace and has no ${accessLabel} grant.`)
}

function previewGeminiMcpPath(context: GeminiToolContext, filePath: string): string {
  if (typeof filePath !== 'string' || !filePath.trim()) return filePath
  try {
    if (context.scope === 'global') {
      return isAbsolute(filePath) ? resolve(filePath) : resolve(context.cwd, filePath)
    }
    const workspaceRoot = resolve(context.workspacePath || context.cwd)
    const targetPath = isAbsolute(filePath) ? resolve(filePath) : resolve(workspaceRoot, filePath)
    return isPathInsideWorkspace(workspaceRoot, targetPath)
      ? formatScopedPath(context, targetPath)
      : targetPath
  } catch {
    return filePath
  }
}

function readApprovalPreviewFileContent(
  context: GeminiToolContext,
  filePath: string
): string | null {
  try {
    const targetPath = resolveGeminiMcpScopedPath(context, filePath)
    const stat = fsSync.statSync(targetPath)
    if (!stat.isFile() || stat.size > MAX_EDITOR_FILE_BYTES) return null
    const buffer = fsSync.readFileSync(targetPath)
    assertTextBuffer(buffer)
    return buffer.toString('utf8')
  } catch {
    return null
  }
}

function formatScopedPath(context: GeminiToolContext, targetPath: string): string {
  if (context.scope === 'global') return resolve(targetPath)
  const workspaceRoot = resolve(context.workspacePath || context.cwd)
  return isPathInsideWorkspace(workspaceRoot, targetPath)
    ? toWorkspaceRelativePath(workspaceRoot, targetPath)
    : resolve(targetPath)
}

function mcpWriteLockApprovalContext(
  context: GeminiToolContext,
  toolName: TaskWraithMcpToolName,
  args: Record<string, any>,
  cwd: string
): { note: string; laneId: string; lockTarget: string } | null {
  const laneId = context.ensembleRun?.laneId
  if (!laneId || !concurrentWriteLanesEnabled() || context.scope === 'global') return null
  const contract = resolveToolDispatchContractStrict(toolName)
  if (
    !contract.ok ||
    (contract.lock !== 'workspace-paths' && contract.lock !== 'workspace-repository')
  ) {
    return null
  }
  const workspacePath = resolve(context.workspacePath || context.cwd || cwd)
  let lockTarget =
    contract.lock === 'workspace-repository'
      ? formatScopedPath(context, resolve(workspacePath, '.git'))
      : 'the exact paths declared by this tool call'
  if (toolName === 'write_file' || toolName === 'replace') {
    const rawPath = String(args.path || args.file_path || '')
    lockTarget = rawPath ? previewGeminiMcpPath(context, rawPath) : lockTarget
  }
  const kind = contract.lock === 'workspace-paths' ? 'file/hunk' : 'repository-metadata'
  return {
    laneId,
    lockTarget,
    note: `Ensemble lane ${laneId} will request an exact ${kind} mutation scope only while this operation executes: ${lockTarget}.`
  }
}

function applyMcpWriteLockApprovalContext(
  approvalPreview: {
    body: string
    preview: Record<string, unknown>
  },
  context: GeminiToolContext,
  toolName: TaskWraithMcpToolName,
  args: Record<string, any>,
  cwd: string
): void {
  const lockContext = mcpWriteLockApprovalContext(context, toolName, args, cwd)
  if (!lockContext) return
  approvalPreview.body = `${approvalPreview.body}\n\n${lockContext.note}`
  approvalPreview.preview = {
    ...approvalPreview.preview,
    ensembleLaneId: lockContext.laneId,
    writeLockTarget: lockContext.lockTarget
  }
}

/**
 * Build the approval prompt (title + body + service + preview) for an
 * MCP tool call. Originally Gemini-only — hence the name + hardcoded
 * "Approve Gemini …" titles — but the same MCP surface is reused by
 * Codex / Claude / Kimi when they call TaskWraith-hosted tools via the
 * shared `parentProvider` dispatch path (`callTaskWraithMcpTool` →
 * line 13857). Before the fix every cross-provider MCP approval read
 * "Approve Gemini tool call" regardless of which model emitted it,
 * which the panel-consensus review (1.0.4-AC) flagged.
 *
 * Solution: accept `parentProvider` as an argument and compose all
 * provider-flavoured titles via `providerDisplayName(parentProvider)`.
 * Generic, provider-agnostic titles ("Approve task run", "Approve
 * git stage", "Capture attached window") are unchanged.
 */
const previewForGeminiMcpTool = createMcpToolApprovalPreviewer({
  mediaEditingTools: MEDIA_EDITING_TOOLS,
  providerDisplayName,
  optionalString,
  isRecord,
  ollamaShellApprovalPreviewMetadata,
  ollamaTextDiffPreview,
  previewPath: previewGeminiMcpPath,
  readApprovalPreviewFileContent,
  getAttachedWindowMeta: (chatId) =>
    chatId ? (nativeWindowCoordinatorRef?.statusForChat(chatId).observation?.window ?? null) : null
})

function runHostCommand(
  command: unknown,
  cwd: string,
  // Default bumped from 120s → 600s (10 min). The prior 120s ceiling
  // was killing legitimate SwiftPM cold-cache `swift build` / `swift
  // test` cycles (60-180s on a warm cache, much longer cold) and
  // agents were having to manually split tests to fit. Fast commands
  // (grep / ls / file ops) finish in seconds so the new default is
  // free; failed / hung commands cost an extra ~8 minutes before the
  // killer fires, which is an acceptable tradeoff. `run_task` lets
  // agents override up to a 30-minute hard clamp via its `timeoutMs`
  // arg if they need more.
  options: HostCommandRunArgument = 600_000
): Promise<HostCommandResult> {
  return new Promise((resolveRun) => {
    const startedAt = Date.now()
    const timeoutMs = typeof options === 'number' ? options : (options.timeoutMs ?? 600_000)
    const releaseApproval = typeof options === 'number' ? undefined : options.releaseApproval
    const projectionScope = hostCommandProjectionContext.getStore()
    const operationSource = projectionScope?.source ?? 'internal-host-command'
    const historyOperation = hostCommandOperations.register(
      {
        operationId: `${operationSource}:${projectionScope?.appRunId ?? 'unowned'}:${randomUUID()}`,
        appRunId: projectionScope?.appRunId,
        appChatId: projectionScope?.appChatId,
        workspaceId: projectionScope?.workspaceId,
        workspacePath: projectionScope?.workspacePath
      },
      { killGraceMs: DEFAULT_HOST_COMMAND_KILL_GRACE_MS }
    )
    if (projectionScope) projectionScope.operations.add(historyOperation)
    let stdout = ''
    let stderr = ''
    let settled = false
    let child: ChildProcess
    let childError: Error | undefined
    let timedOut = false
    let timeoutKill: NodeJS.Timeout | undefined
    const commandText = codexCommandText(command)
    const resolveCommand = (result: HostCommandResult): void => {
      // Scope-less/internal callers have no later transcript projection seam.
      // Resolving their runner promise is the terminal result delivery. Resolve
      // it first so its awaiting continuation is queued before a global-history
      // join can continue from the projection latch.
      resolveRun(result)
      if (!projectionScope) historyOperation.markTerminalProjectionComplete()
    }
    const resolveWithoutChild = (error: string): void => {
      historyOperation.markNoChild()
      resolveCommand({
        stdout,
        stderr,
        exitCode: null,
        error,
        timedOut: false,
        durationMs: Date.now() - startedAt
      })
    }
    // The route operation is registered before this admission check. The
    // destructive-history gate is raised synchronously before its cancellation
    // snapshot and remains held through commit, so a command that arrives after
    // that snapshot proves no-child instead of escaping as a late spawn.
    if (
      historyClearAdmissionBlocked(
        projectionScope?.appRunId,
        projectionScope?.workspacePath,
        projectionScope?.appChatId
      )
    ) {
      resolveWithoutChild('TaskWraith is clearing history; this command was not started.')
      return
    }
    const blockedReleaseCommand =
      releaseCommandBlockReason(command, releaseApproval) ||
      releasePackageScriptBlockReason(command, packageScriptsForCwd(cwd), releaseApproval)
    if (blockedReleaseCommand) {
      resolveWithoutChild(blockedReleaseCommand)
      return
    }
    const blockedRunningBundleMutation = runningAppBundleMutationBlockReason({
      command,
      cwd,
      executablePath: process.execPath,
      packageScripts: packageScriptsForCwd(cwd)
    })
    if (blockedRunningBundleMutation) {
      resolveWithoutChild(blockedRunningBundleMutation)
      return
    }
    // Brokered mutations always get an exact process-group identity so timeout,
    // transport abandonment, and run terminalization can join every descendant
    // rather than treating the wrapper shell's close as settlement. The Local
    // Servers preference retains the same protection for other host commands.
    const brokeredMutation = projectionScope?.source === 'brokered-mcp'
    const detachSpawns =
      brokeredMutation || AppStore.getSettings().localServersDetachSpawns === true

    try {
      if (Array.isArray(command) && command.length > 0) {
        const [binary, ...args] = command.map(codexString)
        child = spawn(binary, args, {
          cwd,
          shell: false,
          detached: detachSpawns,
          windowsHide: true,
          env: createCliEnv({ FORCE_COLOR: '0', NO_COLOR: '1' }, binary)
        })
      } else {
        const shellCommand =
          process.env.SHELL || (process.platform === 'win32' ? 'powershell.exe' : '/bin/zsh')
        const shellArgs =
          process.platform === 'win32'
            ? ['-NoProfile', '-Command', commandText]
            : ['-lc', commandText]
        child = spawn(shellCommand, shellArgs, {
          cwd,
          shell: false,
          detached: detachSpawns,
          windowsHide: true,
          env: createCliEnv({ FORCE_COLOR: '0', NO_COLOR: '1' }, shellCommand)
        })
      }
    } catch (error) {
      resolveWithoutChild(error instanceof Error ? error.message : String(error))
      return
    }

    const processTree =
      brokeredMutation && child.pid ? createHostCommandProcessTreeJoin(child.pid) : null

    // Track the spawn so the Local Servers panel can attribute + reap any
    // long-running server it (or a descendant) leaves behind. Untracked the
    // moment this command settles.
    if (child.pid) {
      spawnRegistry.track({
        pid: child.pid,
        pgid: detachSpawns ? child.pid : undefined,
        startedAt: new Date().toISOString(),
        workspacePath: cwd
      })
    }
    const untrackChild = (): void => {
      if (child?.pid) spawnRegistry.untrack(child.pid)
    }
    const signalChild = (signal: 'SIGTERM' | 'SIGKILL'): boolean => {
      if (detachSpawns && child.pid) {
        // Group-kill the whole tree the detached spawn leads.
        try {
          process.kill(-child.pid, signal)
          return true
        } catch {
          return child.kill(signal)
        }
      }
      return child.kill(signal)
    }

    child.stdout?.on('data', (chunk) => {
      stdout += chunk.toString()
      if (stdout.length > 500_000) stdout = stdout.slice(-500_000)
    })
    child.stderr?.on('data', (chunk) => {
      stderr += chunk.toString()
      if (stderr.length > 500_000) stderr = stderr.slice(-500_000)
    })
    child.on('error', (error) => {
      // Node reports spawn failures here before `close`. Error delivery is not
      // process-close evidence, so retain the exact join and surface it only
      // when the child emits its real close event.
      childError = error
    })
    child.on('close', (code, signal) => {
      if (timeout) clearTimeout(timeout)
      void (async () => {
        await processTree?.joinAfterRootClose()
        if (settled) return
        settled = true
        if (timeoutKill) clearTimeout(timeoutKill)
        untrackChild()
        const cancellationReason = historyOperation.cancellationReason
        const error = timedOut
          ? 'Command timed out.'
          : cancellationReason
            ? `Command cancelled: ${cancellationReason}.`
            : childError?.message || (signal ? `Command terminated by ${signal}.` : undefined)
        resolveCommand({
          stdout,
          stderr,
          exitCode: code,
          ...(error ? { error } : {}),
          timedOut,
          durationMs: Date.now() - startedAt
        })
      })().catch((error) => {
        childError = error instanceof Error ? error : new Error(String(error))
        console.error('[host-command] Exact process-tree join failed:', childError)
      })
    })

    historyOperation.attachChild({
      once: (_event, listener) => child.once('close', listener),
      kill: signalChild,
      ...(processTree ? { joinProcessTreeAfterClose: () => processTree.joinAfterRootClose() } : {})
    })

    // Declared here (not above with timeoutKill): the only reader is the
    // 'close' handler, which cannot run before this synchronous assignment.
    const timeout = setTimeout(() => {
      if (settled || timedOut) return
      timedOut = true
      try {
        signalChild('SIGTERM')
      } catch {
        // Signal delivery is not close evidence. Keep waiting and escalate.
      }
      timeoutKill = setTimeout(() => {
        if (settled) return
        try {
          signalChild('SIGKILL')
        } catch {
          // A failed SIGKILL still is not close evidence; the join stays pending.
        }
      }, DEFAULT_HOST_COMMAND_KILL_GRACE_MS)
      timeoutKill.unref?.()
    }, timeoutMs)
  })
}

function codexNeedsApprovalGate(settings: AppSettings = AppStore.getSettings()): boolean {
  const services = settings.agenticServices
  return (
    !services ||
    services.shellCommands !== 'allow' ||
    services.fileChanges !== 'allow' ||
    services.mcpTools !== 'allow'
  )
}

function resolveGeminiApprovalModeForServices(approvalMode: string, settings: AppSettings): string {
  const services = settings.agenticServices
  if (!services || approvalMode === 'plan') return approvalMode
  if (services.shellCommands === 'deny' || services.fileChanges === 'deny') return 'plan'
  return approvalMode
}

// 1.0.72 — opt-in (default OFF) flag for the Gemini read-only MCP advertise path.
// When ON, a plan-mode workspace Gemini run advertises the non-mutating safe
// subset over the bridge instead of being seatbelt-killed. SECURITY: this drops
// the --sandbox seatbelt (the ONLY containment for Gemini's NATIVE write/shell),
// so it stays env-gated until runtime-write-verified that read-only Gemini still
// refuses native writes. Env flag (dev/test), mirroring the grok/cursor gates.
function geminiReadOnlyMcpAdvertiseEnabled(): boolean {
  const v = process.env.TASKWRAITH_GEMINI_READONLY_MCP
  return v === '1' || v === 'true' || v === 'yes'
}

function geminiWriteModeRequiresBridge(
  scope: ChatScope | undefined,
  approvalMode: string
): boolean {
  return scope !== 'global' && approvalMode !== 'plan'
}

function clearScheduledTaskTimer() {
  if (scheduledTaskTimer) {
    clearTimeout(scheduledTaskTimer)
    scheduledTaskTimer = null
  }
}

const ENSEMBLE_FANOUT_POLICIES = new Set<EnsembleFanoutPolicy>([
  'off',
  'read_only',
  'all',
  'locked_writers_with_boss',
  'locked_writers_user_preflight'
])

function normalizeScheduledFanoutPolicy(
  value: unknown,
  legacyEnabled?: boolean
): EnsembleFanoutPolicy {
  return ENSEMBLE_FANOUT_POLICIES.has(value as EnsembleFanoutPolicy)
    ? (value as EnsembleFanoutPolicy)
    : legacyEnabled
      ? 'read_only'
      : 'off'
}

// Stage 0b-dispatch (ensemble) — apply a schedule-time ensemble snapshot onto a
// chat MAIN-side. Tiny pure replica of the renderer's applyScheduledEnsembleSnapshot
// (src/renderer/src/lib/scheduledEnsembleSnapshot.ts) so the main process doesn't
// import renderer code. Returns a new chat (original unchanged).
function applyScheduledEnsembleSnapshotMain(
  chat: ChatRecord,
  snapshot: ScheduledEnsembleSnapshot
): ChatRecord {
  if (!chat.ensemble) return chat
  return {
    ...chat,
    ensemble: {
      ...chat.ensemble,
      orchestrationMode: snapshot.orchestrationMode,
      fanoutPolicy: normalizeScheduledFanoutPolicy(
        snapshot.fanoutPolicy,
        snapshot.concurrentModeEnabled
      ),
      concurrentModeEnabled:
        typeof snapshot.concurrentModeEnabled === 'boolean'
          ? snapshot.concurrentModeEnabled
          : normalizeScheduledFanoutPolicy(snapshot.fanoutPolicy) !== 'off',
      participants: snapshot.participants.map((participant) => ({ ...participant })),
      ...(typeof snapshot.maxParticipants === 'number'
        ? { maxParticipants: snapshot.maxParticipants }
        : {}),
      ...(typeof snapshot.maxContinuationHops === 'number'
        ? { maxContinuationHops: snapshot.maxContinuationHops }
        : {}),
      updatedAt: new Date().toISOString()
    }
  }
}

function verifyScheduledTaskAttachmentOwnership(task: ScheduledTask): boolean {
  const resolved = scheduledAttachmentPersistence.resolve({
    source: 'scheduled-task',
    recordId: task.id,
    appChatId: task.chatId,
    workspaceId: task.workspaceId,
    workspacePath: task.workspacePath,
    externalPathGrants: normalizeExternalPathGrants(task.externalPathGrants),
    attachments: task.imageAttachments || []
  })
  if (!resolved.ok) {
    console.warn(
      `[TranscriptMedia] scheduled attachment ownership failed for ${task.id}: ${resolved.reason}`
    )
  }
  return resolved.ok
}

function assertScheduledOccurrenceWorkspace(owner: ScheduledOccurrenceOwner): string {
  if (scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner) {
    throw new Error('Scheduled occurrence no longer has live process ownership.')
  }
  const task = AppStore.getScheduledTasks().find((candidate) => candidate.id === owner.taskId)
  if (
    !task ||
    task.status !== 'running' ||
    task.runId !== owner.ownerRunId ||
    task.provider !== owner.provider ||
    task.chatId !== owner.chatId ||
    task.workspaceId !== owner.workspaceId ||
    task.workspacePath !== owner.workspacePath
  ) {
    throw new Error('Scheduled occurrence no longer matches its exact durable owner.')
  }
  if (owner.workflowOccurrence) {
    if (
      task.workflowId !== owner.workflowOccurrence.workflowId ||
      task.workflowExecutionId !== owner.workflowOccurrence.executionId ||
      task.workflowOccurrenceAt !== owner.workflowOccurrence.plannedFor
    ) {
      throw new Error('Scheduled occurrence workflow linkage changed after claim.')
    }
  }

  const chat = AppStore.getChat(owner.chatId)
  if (
    !chat ||
    chat.scope === 'global' ||
    chat.workspaceId !== owner.workspaceId ||
    chat.workspacePath !== owner.workspacePath ||
    (owner.rootOwner === 'ensemble-root') !== (chat.chatKind === 'ensemble')
  ) {
    throw new Error('Scheduled occurrence chat authority changed after claim.')
  }
  const workspace = AppStore.getWorkspaces().find((candidate) => candidate.id === owner.workspaceId)
  if (!workspace) throw new Error('Scheduled occurrence workspace is no longer registered.')
  const workflow = owner.workflowOccurrence
    ? AppStore.getWorkflowDefinition(owner.workflowOccurrence.workflowId)
    : null
  if (
    owner.workflowOccurrence &&
    (!workflow ||
      workflow.workspaceId !== owner.workspaceId ||
      workflow.workspacePath !== owner.workspacePath)
  ) {
    throw new Error('Scheduled occurrence workflow authority changed after claim.')
  }

  return assertPinnedWorkspaceTarget({
    workspace,
    task,
    chat: { workspaceId: owner.workspaceId, workspacePath: owner.workspacePath },
    workflow,
    canonicalPath,
    resolveRealDirectory: (value) => {
      const stat = fsSync.statSync(value)
      if (!stat.isDirectory()) throw new Error('Workspace target is not a directory.')
      return fsSync.realpathSync.native(value)
    }
  })
}

function isScheduledOccurrenceChatBusy(task: ScheduledTask): boolean {
  if (
    scheduledOccurrenceOwners.lookupByChatId(task.chatId) ||
    scheduledOccurrenceOwners.hasOrdinaryChatDispatchReservation(task.chatId)
  ) {
    return true
  }
  if (
    RUN_MANAGER_PROVIDERS.some((provider) =>
      runManager.getActiveByProvider(provider).some((session) => session.appChatId === task.chatId)
    )
  ) {
    return true
  }
  if (
    AppStore.getRunQueueJobs({
      chatId: task.chatId,
      statuses: ['queued', 'steer_promoting', 'starting', 'active', 'paused', 'cancelling']
    }).length > 0
  ) {
    return true
  }
  const chat = AppStore.getChat(task.chatId)
  if (chat?.ensemble?.activeRound?.status === 'running') return true
  return AppStore.getScheduledTasks().some(
    (candidate) =>
      candidate.id !== task.id && candidate.chatId === task.chatId && candidate.status === 'running'
  )
}

function failScheduledOccurrence(owner: ScheduledOccurrenceOwner, lastError: string): void {
  if (scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner) return
  const settled = settleScheduledOccurrence(owner, 'failed', {
    completedAt: new Date().toISOString(),
    lastError
  })
  if (!settled) {
    console.error(
      `[scheduled-occurrence] exact failure settlement rejected for task ${owner.taskId}, run ${owner.ownerRunId}`
    )
  }
}

function failScheduledEnsembleOccurrenceAndAbort(
  owner: ScheduledOccurrenceOwner,
  expectedRoundId: string,
  lastError: string
): void {
  if (
    owner.rootOwner !== 'ensemble-root' ||
    scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner ||
    scheduledOccurrenceOwners.lookupEnsembleRoundIdForOwner(owner) !== expectedRoundId
  ) {
    return
  }
  const settled = settleScheduledOccurrence(owner, 'failed', {
    completedAt: new Date().toISOString(),
    lastError
  })
  if (!settled) {
    console.error(
      `[scheduled-occurrence] exact ensemble failure settlement rejected for task ${owner.taskId}, run ${owner.ownerRunId}`
    )
    return
  }

  workflowBudgetRegistry.onExit(owner.ownerRunId)
  void ensembleOrchestratorRef
    ?.cancelRound(owner.chatId, lastError, expectedRoundId)
    .catch((error) => {
      console.error(
        '[scheduled-occurrence] exact failed ensemble round abort failed',
        error instanceof Error ? error.message : String(error)
      )
      return false
    })
}

function publishScheduledOccurrenceSettlement(): void {
  try {
    mainWindow?.webContents.send('scheduled-tasks-changed', AppStore.getScheduledTasks())
    mainWindow?.webContents.send('workflow-definitions-changed', AppStore.getWorkflowDefinitions())
  } catch (error) {
    console.error(
      '[scheduled-occurrence] durable settlement renderer publication failed',
      error instanceof Error ? error.message : String(error)
    )
  }
  try {
    requestThrottledRemoteProjectionSnapshot()
  } catch (error) {
    console.error(
      '[scheduled-occurrence] durable settlement remote publication failed',
      error instanceof Error ? error.message : String(error)
    )
  }
  try {
    scheduleNextTaskTimer()
  } catch (error) {
    console.error(
      '[scheduled-occurrence] durable settlement timer rearm failed',
      error instanceof Error ? error.message : String(error)
    )
  }
}

function settleScheduledOccurrence(
  owner: ScheduledOccurrenceOwner,
  status: ScheduledOccurrenceTerminalStatus,
  options: { completedAt?: string; lastError?: string } = {}
): ScheduledTask | null {
  const settled = scheduledOccurrenceTransaction.settle(owner, status, options)
  if (settled) publishScheduledOccurrenceSettlement()
  return settled
}

async function cancelScheduledOccurrence(
  taskId: string,
  reason = 'Cancelled by user.'
): Promise<ScheduledTask | null> {
  const task = AppStore.getScheduledTasks().find((candidate) => candidate.id === taskId)
  if (!task) return null
  if (task.status === 'completed' || task.status === 'failed' || task.status === 'cancelled') {
    return task
  }
  const completedAt = new Date().toISOString()
  if ((task.status === 'pending' || task.status === 'due') && !task.runId) {
    const cancelled = AppStore.updateScheduledTask(task.id, {
      status: 'cancelled',
      completedAt,
      lastError: reason
    })
    if (cancelled?.status === 'cancelled') publishScheduledOccurrenceSettlement()
    return cancelled?.status === 'cancelled' ? cancelled : null
  }
  if (task.status !== 'running' || !task.runId) return null

  const owner = scheduledOccurrenceOwners.lookupByTaskId(task.id)
  if (
    !owner ||
    owner.ownerRunId !== task.runId ||
    owner.provider !== task.provider ||
    owner.chatId !== task.chatId ||
    owner.workspaceId !== task.workspaceId ||
    owner.workspacePath !== task.workspacePath
  ) {
    return null
  }

  const exactTransportTargets: Array<{ provider: ProviderId; runId: string }> = []
  let soloHarvestRoute: unknown
  if (owner.rootOwner === 'solo') {
    const session = runManager.get(owner.ownerRunId)
    if (
      session &&
      session.provider === owner.provider &&
      isActiveRunSessionStatus(session.status)
    ) {
      exactTransportTargets.push({ provider: session.provider, runId: session.runId })
      soloHarvestRoute = session.state
    }
  } else if (owner.rootOwner === 'loop-root') {
    for (const childRunId of scheduledOccurrenceOwners.lookupChildRunIdsForOwner(owner)) {
      const session = runManager.get(childRunId)
      if (
        session &&
        isActiveRunSessionStatus(session.status) &&
        scheduledOccurrenceOwners.lookupLoopChildRun(childRunId, session.provider) === owner
      ) {
        exactTransportTargets.push({ provider: session.provider, runId: session.runId })
      }
    }
  }
  const expectedRoundId =
    owner.rootOwner === 'ensemble-root'
      ? scheduledOccurrenceOwners.lookupEnsembleRoundIdForOwner(owner)
      : undefined

  // Durable exact settlement is the authorization boundary. If it rejects,
  // transport state is untouched; a stale caller cannot kill a replacement.
  const settled = settleScheduledOccurrence(owner, 'cancelled', {
    completedAt,
    lastError: reason
  })
  if (!settled) return null

  workflowBudgetRegistry.onExit(owner.ownerRunId)
  for (const target of exactTransportTargets) {
    cancelPendingAgentQuestionsForRun(target.runId, 'scheduled-run-cancelled')
  }
  if (owner.rootOwner === 'ensemble-root' && expectedRoundId) {
    await ensembleOrchestratorRef
      ?.cancelRound(owner.chatId, reason, expectedRoundId)
      .catch(() => false)
  } else {
    await Promise.allSettled(
      exactTransportTargets.map((target) => cancelProviderRun(target.provider, target.runId))
    )
  }
  if (owner.rootOwner === 'solo') {
    finalizeBridgeRunTranscript(owner.ownerRunId, 'cancelled')
    recordWorkflowRunHarvest(owner.taskId, owner.ownerRunId, soloHarvestRoute)
  }
  return settled
}

function scheduledOccurrenceOwnerForCancellationRunId(
  runId: string,
  provider: ProviderId
): ScheduledOccurrenceOwner | undefined {
  const root = scheduledOccurrenceOwners.lookupByOwnerRunId(runId)
  const loop = scheduledOccurrenceOwners.lookupLoopChildRun(runId, provider)
  const ensemble = scheduledOccurrenceOwners.lookupEnsembleChildRun(runId, provider)
  const candidates = [root && root.provider === provider ? root : undefined, loop, ensemble].filter(
    (candidate): candidate is ScheduledOccurrenceOwner => Boolean(candidate)
  )
  return new Set(candidates).size === 1 ? candidates[0] : undefined
}

const SCHEDULED_CHILD_BOUND_EVENT_TYPE = 'scheduled_occurrence_child_bound'

function recordScheduledOccurrenceChildBinding(input: {
  owner: ScheduledOccurrenceOwner
  childRunId: string
  childKind: 'loop' | 'ensemble'
  childProvider: ProviderId
}): void {
  AppStore.recordScheduledRunIdTombstone({
    runId: input.childRunId,
    rootRunId: input.owner.ownerRunId,
    taskId: input.owner.taskId,
    kind: input.childKind === 'loop' ? 'loop-child' : 'ensemble-child'
  })
  try {
    appendDurableRunEvent({
      runId: input.childRunId,
      chatId: input.owner.chatId,
      workspaceId: input.owner.workspaceId,
      workspacePath: input.owner.workspacePath,
      provider: input.childProvider,
      kind: 'lifecycle',
      phase: 'control',
      source: 'main',
      summary: `Bound scheduled ${input.childKind} child to its exact occurrence root`,
      payload: {
        eventType: SCHEDULED_CHILD_BOUND_EVENT_TYPE,
        scheduledTaskId: input.owner.taskId,
        rootRunId: input.owner.ownerRunId,
        childKind: input.childKind
      }
    })
  } catch (error) {
    // The dedicated tombstone ledger is the authority record. Ordinary audit
    // publication is useful evidence but must not strand a claimed occurrence.
    console.error('[scheduled-occurrence] child-binding audit publication failed', error)
  }
}

function wasDurableScheduledRunIdObserved(runId: string): boolean {
  return AppStore.hasScheduledRunIdTombstone(runId)
}

function wasScheduledOccurrenceRunIdObserved(runId: string): boolean {
  return (
    scheduledOccurrenceOwners.isAppRunIdLiveOwned(runId) ||
    scheduledOccurrenceOwners.wasChildRunIdObserved(runId) ||
    AppStore.getScheduledTasks().some((task) => task.runId === runId) ||
    wasDurableScheduledRunIdObserved(runId)
  )
}

const SCHEDULED_ENSEMBLE_INTERACTIVE_BLOCK =
  'A scheduled occurrence currently owns this chat. Cancel it before starting, queueing, or steering interactive Ensemble work.'

function scheduledEnsembleInteractiveBlock(chatId: string): string | undefined {
  return scheduledOccurrenceOwners.lookupByChatId(chatId)
    ? SCHEDULED_ENSEMBLE_INTERACTIVE_BLOCK
    : undefined
}

function assertScheduledEnsembleInteractiveAvailable(chatId: string): void {
  const reason = scheduledEnsembleInteractiveBlock(chatId)
  if (reason) throw new Error(reason)
}

// Stage 0b-dispatch (ensemble) — start a due ENSEMBLE scheduled round from MAIN
// when no renderer can (windowless). Mirrors the run-ensemble-round IPC handler:
// apply the schedule-time roster/mode snapshot + persist (the orchestrator reads
// the chat LIVE via getChat), then startRound with the headless sender. The
// 'running' mark + startRound are SYNCHRONOUS, so a racing tick can't
// double-dispatch. Completion rides the EXISTING bridge —
// The round-reservation callback binds this root into the exact occurrence
// registry; completeSessionCheckpoint settles that same owner terminal.
async function dispatchDueEnsembleScheduledTaskHeadless(
  task: ScheduledTask,
  owner: ScheduledOccurrenceOwner
): Promise<void> {
  const orchestrator = ensembleOrchestratorRef
  if (!orchestrator) {
    failScheduledOccurrence(owner, 'Scheduled ensemble dispatch is not initialized.')
    return
  }
  try {
    const chat = AppStore.getChat(task.chatId)
    if (!chat || chat.chatKind !== 'ensemble' || !chat.ensemble) {
      failScheduledOccurrence(owner, 'Scheduled ensemble dispatch: chat is not an ensemble.')
      return
    }
    if (!verifyScheduledTaskAttachmentOwnership(task)) {
      failScheduledOccurrence(
        owner,
        'Scheduled ensemble dispatch: attachment ownership could not be verified.'
      )
      return
    }
    // P2 — honor a verified unattended elevation (HMAC + current); null => the
    // orchestrator clamps every participant read-only (P1b).
    const elevation = resolveUnattendedElevation(task.id)
    const scheduledImageAttachments = imageAttachmentSnapshots(task.imageAttachments)
    const dispatchImageAttachments = await expandPdfAttachmentsForDispatch(
      scheduledImageAttachments,
      task.chatId
    )
    const scheduledExternalPathGrants = normalizeExternalPathGrants(task.externalPathGrants)
    // Async attachment preparation can race a workspace retarget. Re-read every
    // main-owned binding and pin the current real directory immediately before
    // the synchronous round reservation/launch.
    assertScheduledOccurrenceWorkspace(owner)
    const scheduledSnapshot = task.ensembleSnapshot
    const scheduledRoutingRoster = scheduledSnapshot?.participants ?? chat.ensemble.participants
    const scheduledDmTargetResolution = resolveEnsembleDmTargetForDispatch({
      text: task.prompt,
      participants: scheduledRoutingRoster,
      advisoryParticipantId: scheduledSnapshot?.dmTargetParticipantId,
      exactPickerParticipantId: scheduledSnapshot?.exactPickerParticipantId
    })
    const scheduledDmTargetError = ensembleDmTargetResolutionError(
      scheduledDmTargetResolution,
      scheduledRoutingRoster
    )
    if (scheduledDmTargetError) {
      failScheduledOccurrence(owner, `Scheduled ensemble dispatch: ${scheduledDmTargetError}`)
      return
    }
    const scheduledDmTargetParticipantId =
      scheduledDmTargetResolution.kind === 'target'
        ? scheduledDmTargetResolution.participantId
        : undefined
    const scheduledFanoutPolicy = scheduledSnapshot
      ? normalizeScheduledFanoutPolicy(
          scheduledSnapshot.fanoutPolicy,
          scheduledSnapshot.concurrentModeEnabled
        )
      : undefined
    const scheduledConcurrentMode = scheduledSnapshot
      ? (scheduledSnapshot.concurrentModeEnabled ?? scheduledFanoutPolicy !== 'off')
      : undefined
    const sender =
      mainWindow && !mainWindow.webContents.isDestroyed()
        ? mainWindow.webContents
        : headlessRunSender
    const started = orchestrator.startRound({
      chatId: task.chatId,
      prompt: task.prompt,
      event: { sender },
      mode: 'normal',
      imageAttachments: dispatchImageAttachments,
      unattended: true,
      requireFreshRound: true,
      ...(scheduledConcurrentMode !== undefined
        ? { concurrentMode: Boolean(scheduledConcurrentMode) }
        : {}),
      ...(scheduledFanoutPolicy !== undefined ? { fanoutPolicy: scheduledFanoutPolicy } : {}),
      ...(scheduledDmTargetParticipantId
        ? { dmTargetParticipantId: scheduledDmTargetParticipantId }
        : {}),
      ...(scheduledExternalPathGrants.length > 0
        ? { externalPathGrants: scheduledExternalPathGrants }
        : {}),
      ...(elevation ? { unattendedElevationLevel: elevation.ack.level } : {}),
      ...(scheduledSnapshot
        ? {
            prepareFreshChat: (current: ChatRecord) =>
              applyScheduledEnsembleSnapshotMain(current, scheduledSnapshot)
          }
        : {}),
      onRoundReserved: (roundId) => {
        scheduledOccurrenceOwners.bindEnsembleRound(roundId, owner.ownerRunId)
      }
    })
    if (started.status !== 'started' || !started.roundId) {
      failScheduledOccurrence(
        owner,
        `Scheduled ensemble dispatch: round did not start (${started.status}).`
      )
    }
  } catch (error) {
    failScheduledOccurrence(
      owner,
      `Scheduled ensemble dispatch failed: ${error instanceof Error ? error.message : String(error)}`
    )
  }
}

// Stage 0b-dispatch: compose + dispatch a due SOLO scheduled task from MAIN when
// no renderer can (windowless). Mirrors the renderer executeRun dispatch essence
// (composeRun -> runAgent) without the renderer-only UI bookkeeping. The
// 'running' mark is SYNCHRONOUS (before the first await) so a racing scheduler
// tick can't double-dispatch — getDueScheduledTasks stops returning a non-'due'
// task once claimed. Completion + the per-occurrence budget kill are handled by
// the shared dispatch chokepoint, which keys off the threaded scheduledTaskId.
// ENSEMBLE occurrences delegate to dispatchDueEnsembleScheduledTaskHeadless
// (composeRun is solo-only; ensemble runs through the orchestrator).
// Stage 2 slice 5/5b — run a due LOOP-workflow occurrence as a maker→verifier loop
// in MAIN (the renderer has no loop engine). Slice 5b honors a configured verifier:
// each iteration the maker produces, then an independent verifier judges it via a
// LOOP_VERDICT marker (buildLoopVerifierPrompt/parseLoopVerdict) and the engine
// stops on accept/reject (or a no-evidence revise → inconclusive). With no verifier
// configured this is the slice-5 maker-only loop. The loop is bounded fail-safe by
// maxIterations + the verifier's evidence-anchor rule +
// the cumulative budget. CRUX (per recon): each iteration's run carries a fresh
// appRunId and NO scheduledTaskId on its payload, so the dispatch chokepoint skips
// the per-occurrence solo-completion / budget bookkeeping (Option A) — the LOOP owns
// the SINGLE terminal mark at loop-end. Completion of each iteration's run is awaited
// via auditRunTracker (the provider-agnostic stash-a-resolver the central pumps
// already feed), tracked BEFORE dispatch (the Claude SDK fires the exit INLINE).
async function dispatchDueScheduledLoopHeadless(
  task: ScheduledTask,
  loopCfg: WorkflowLoopConfig,
  owner: ScheduledOccurrenceOwner
): Promise<void> {
  const composer = composerServiceRef
  const dispatch = dispatchMainOwnedScheduledOccurrenceRef
  if (!composer || !dispatch) {
    failScheduledOccurrence(owner, 'Scheduled workflow loop dispatch is not initialized.')
    return
  }
  if (!verifyScheduledTaskAttachmentOwnership(task)) {
    failScheduledOccurrence(owner, 'Workflow loop attachment ownership could not be verified.')
    return
  }
  if (owner.rootOwner !== 'loop-root') {
    failScheduledOccurrence(owner, 'Scheduled workflow loop has the wrong root owner.')
    return
  }
  let ownershipLost = false

  // 7c — live loop-progress broadcast to BOTH the local Electron renderer (a window may
  // be open) and paired phones. Reused at run-start (reset), per iteration (onState), and
  // at completion. The Electron send is guarded for the headless case (no/destroyed
  // window); the iOS push rebuilds RemoteWorkflow from the freshly-cached def fields.
  const broadcastWorkflowProgress = (force = false): void => {
    if (mainWindow && !mainWindow.webContents.isDestroyed()) {
      mainWindow.webContents.send('workflow-definitions-changed', AppStore.getWorkflowDefinitions())
    }
    // For important transitions (run-start reset + completion), force an immediate
    // full projection; per-iteration calls stay coalesced by the broadcaster.
    if (force) bridgeBroadcasterRef?.resetThrottle()
    requestThrottledRemoteProjectionSnapshot()
  }

  // 7c — reset the cached loop summary at the START of a new run so the live badge drops
  // the PRIOR run's "Nx · <reason>" immediately (count 0 hides it via the >0 guard)
  // rather than showing it stale until this run's first iteration completes.
  if (task.workflowId) {
    AppStore.updateWorkflowDefinition(task.workflowId, {
      lastRunIterationCount: 0,
      lastRunStopReason: undefined,
      lastRunTokens: 0
    })
    broadcastWorkflowProgress(true)
  }

  const ledger = resolveWorkflowExecutionForTask(task.id)
  // Per-iteration backstop: the workflow's configured per-run timeout if set, else a
  // generous default — so a long-but-healthy maker isn't mislabeled an infra failure.
  const wfLimits = task.workflowId
    ? AppStore.getWorkflowDefinition(task.workflowId)?.limits
    : undefined
  const stepTimeoutMs =
    typeof wfLimits?.timeoutSeconds === 'number' && wfLimits.timeoutSeconds > 0
      ? wfLimits.timeoutSeconds * 1000
      : WORKFLOW_LOOP_STEP_TIMEOUT_MS
  const appendLoopEvent = (input: WorkflowRunEventInput): void => {
    if (!ledger) return
    try {
      AppStore.appendWorkflowRunEvent({ ...ledger, ...input } as WorkflowRunEventInput)
    } catch (e) {
      console.error('Failed to append workflow loop ledger event', e)
    }
  }

  // Slice 5b — honor the verifier when configured: the engine then runs a
  // maker→verifier→decide loop (slice 5 was maker-only). The verifier.provider
  // OVERRIDE (cross-provider judging) is preserved on the config but NOT yet honored
  // — the verifier run reuses the maker's provider/model (5c follow-up); passing it
  // through here is inert at the engine level (only dispatchStep reads a provider).
  // With no verifier configured this is exactly the maker-only loop from slice 5.
  const engineConfig: WorkflowLoopConfig = {
    acceptance: {
      maxIterations: loopCfg.acceptance.maxIterations,
      ...(loopCfg.acceptance.verifier ? { verifier: loopCfg.acceptance.verifier } : {})
    },
    limits: loopCfg.limits
  }

  // 5c — honor a configured CROSS-PROVIDER verifier. acceptance.verifier.provider is an
  // UNVALIDATED raw string off the WorkflowDefinition (normalizeWorkflowLoopConfig
  // defers validation to the dispatch path), so validate it as a LIVE provider here; an
  // invalid/retired value fails safe to undefined → the verifier runs on the maker's
  // provider (same as before 5c) rather than crashing the loop.
  let verifierProvider: ProviderId | undefined
  const rawVerifierProvider = loopCfg.acceptance.verifier?.provider
  if (rawVerifierProvider) {
    try {
      verifierProvider = assertLiveProviderId(rawVerifierProvider)
    } catch {
      verifierProvider = undefined
    }
  }

  const dispatchStep = async (input: WorkflowLoopStepInput): Promise<WorkflowLoopStepResult> => {
    const isVerifier = input.role === 'verifier'
    // 5c — when a validated verifier provider is configured AND differs from the maker's,
    // the verifier judges CROSS-PROVIDER (a more independent check). Such a run composes
    // with the verifier provider's OWN default model: the maker's customModel /
    // selectedModelType / per-provider effort flags would misroute (e.g. a Claude model
    // id handed to Grok), so they are dropped from the compose below.
    const crossProviderVerifier =
      isVerifier && verifierProvider !== undefined && verifierProvider !== task.provider
    const composeProvider = crossProviderVerifier ? verifierProvider! : task.provider
    try {
      // Revalidate the exact durable root at every child iteration. The central
      // provider preflight repeats this after its async probes, immediately before
      // adapter launch, using the child binding installed below.
      assertScheduledOccurrenceWorkspace(owner)
    } catch (error) {
      ownershipLost = true
      return { failed: true, error: error instanceof Error ? error.message : String(error) }
    }
    // Role branch (slice 5b). MAKER: continue/refine the task, threading the prior
    // attempt + the reviewer's revise feedback. VERIFIER: an independent judge run
    // over the maker's latest output (buildLoopVerifierPrompt); its final text is
    // parsed back into a verdict below. Both roles share the Option-A dispatch (no
    // scheduledTaskId on the payload), so neither writes per-iteration bookkeeping.
    const reviewerFeedback =
      input.role === 'maker'
        ? input.priorVerdict?.evidence || input.priorVerdict?.rationale || ''
        : ''
    const prompt =
      input.role === 'verifier'
        ? buildLoopVerifierPrompt(task.prompt, input.priorOutput ?? '')
        : input.priorOutput
          ? `${task.prompt}\n\n[Your previous attempt — iteration ${input.iteration - 1}]\n${input.priorOutput}${
              reviewerFeedback ? `\n\n[Reviewer feedback — address this]\n${reviewerFeedback}` : ''
            }\n\n[Refine or continue the work above for iteration ${input.iteration}.]`
          : task.prompt
    let composed: AgentRunPayload
    try {
      // scheduledTaskId is passed to the INPUT (forces the unattended posture +
      // resolves any verified elevation internally) but is deliberately NOT re-added
      // to the output payload below — so the chokepoint skips the per-iteration
      // solo/budget bookkeeping (Option A). appRunId = input.runId bridges completion.
      composed = await composer.composeRun({
        chatId: task.chatId,
        appRunId: input.runId,
        provider: composeProvider,
        workspace: task.workspacePath,
        prompt,
        // Provider-specific model config — applied for SAME-provider runs (the maker, or
        // a verifier on the maker's provider). For a cross-provider verifier these are
        // dropped AND overrideModel is forced to the verifier provider's own default:
        // dropping the inputs alone is NOT enough — resolveRequestedModel would fall
        // through to the chat's stored (maker) model metadata and hand a foreign model
        // id to the verifier provider (which Codex/Claude/Gemini dispatch verbatim → the
        // run errors). overrideModel short-circuits that entire resolution chain.
        ...(crossProviderVerifier
          ? { overrideModel: getDefaultModelForProvider(composeProvider) }
          : {
              selectedModelType: task.selectedModelType,
              customModel: task.customModel,
              codexReasoningEffort: task.codexReasoningEffort,
              grokReasoningEffort: task.grokReasoningEffort,
              museReasoningEffort: task.museReasoningEffort,
              cursorReasoningEffort: task.cursorReasoningEffort,
              cursorFastMode: task.cursorFastMode,
              codexServiceTier: task.codexServiceTier,
              claudeReasoningEffort: task.claudeReasoningEffort,
              claudeFastMode: task.claudeFastMode,
              kimiReasoningEffort: task.kimiReasoningEffort,
              kimiThinkingEnabled: task.kimiThinkingEnabled,
              runtimeProfileId: task.runtimeProfileId,
              geminiAuthProfileId: task.geminiAuthProfileId
            }),
        approvalMode: task.approvalMode,
        ...scheduledHeadlessComposeFields(task),
        sessionTrust: task.sessionTrust,
        imageAttachments: task.imageAttachments,
        externalPathGrants: task.externalPathGrants,
        scheduledTaskId: task.id
      }) as AgentRunPayload
    } catch (error) {
      return { failed: true, error: error instanceof Error ? error.message : String(error) }
    }
    // Track BEFORE dispatch (inline-exit landmine) + arm an absolute backstop.
    try {
      recordScheduledOccurrenceChildBinding({
        owner,
        childRunId: input.runId,
        childKind: 'loop',
        childProvider: composeProvider
      })
      scheduledOccurrenceOwners.bindLoopChildRun(input.runId, owner.ownerRunId, composeProvider)
    } catch (error) {
      ownershipLost = scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner
      return { failed: true, error: error instanceof Error ? error.message : String(error) }
    }
    const completion = auditRunTracker.track(input.runId)
    const clearBackstop = armScheduledLoopStepTimeout({
      composeProvider,
      runId: input.runId,
      timeoutMs: stepTimeoutMs,
      cancelProviderRun,
      handleExit: (runId, exitCode) => auditRunTracker.handleExit(runId, exitCode)
    })
    void completion.finally(clearBackstop)
    const sender =
      mainWindow && !mainWindow.webContents.isDestroyed()
        ? mainWindow.webContents
        : headlessRunSender
    // The loop root owns terminal settlement; each child is bound process-locally
    // and receives a one-shot MAIN authorization at the dedicated dispatch seam.
    const failDispatch = async (): Promise<void> => {
      if (scheduledOccurrenceOwners.lookupLoopChildRun(input.runId, composeProvider) === owner) {
        await terminateExactProviderSession(composeProvider, input.runId, 'failed')
      }
      auditRunTracker.handleExit(input.runId, -1)
    }
    void dispatch(composed, { sender })
      .then((r) => (r?.dispatched ? undefined : failDispatch()))
      .catch(() => failDispatch())
    const outcome = await completion
    // Verifier steps parse a structured verdict from their final text; a missing or
    // unparseable marker leaves verdict null → the engine defaults to an evidence-less
    // { decision: 'revise' } → a fail-safe 'inconclusive' stop (never an infinite loop).
    // NOTE: outcome.finalText is reliable only for providers whose output flows through
    // the auditRunTracker pump (the CLI streamers + Codex-ACP); a tracker-bypassing
    // path (e.g. Codex exec-fallback) yields empty finalText → null → inconclusive on
    // iteration 1. Fail-safe (no streak poison). 5c lets a workflow pin a cross-provider
    // judge via verifier.provider; the warn below makes a verifier on a non-streaming
    // provider diagnosable rather than silently stalling the loop every iteration.
    const verdict =
      input.role === 'verifier' && outcome.ok ? parseLoopVerdict(outcome.finalText) : null
    if (isVerifier && outcome.ok && !verdict) {
      console.warn(
        `[workflow-loop] verifier produced no parseable LOOP_VERDICT (provider=${composeProvider}, run=${input.runId}); loop will stop inconclusive`
      )
    }
    // Per-iteration forensics (tagged iteration:N so the fold sums them without
    // terminalizing the execution); the verifier iteration also persists its verdict
    // (slice 7) so the loop-progress UI can show WHY each iteration continued / stopped.
    appendLoopEvent({
      kind: 'harvested',
      scheduledTaskId: task.id,
      runId: input.runId,
      iteration: input.iteration,
      ...(typeof outcome.tokens === 'number' ? { tokens: outcome.tokens } : {}),
      ...(typeof outcome.costUsd === 'number' ? { costUsd: outcome.costUsd } : {}),
      ...(typeof outcome.durationMs === 'number' ? { durationMs: outcome.durationMs } : {}),
      ...(verdict ? { verdict } : {})
    } as WorkflowRunEventInput)
    return {
      ...(outcome.finalText !== undefined ? { output: outcome.finalText } : {}),
      ...(typeof outcome.tokens === 'number' ? { tokens: outcome.tokens } : {}),
      ...(typeof outcome.costUsd === 'number' ? { costUsd: outcome.costUsd } : {}),
      ...(!outcome.ok ? { failed: true, error: outcome.error } : {}),
      ...(verdict ? { verdict } : {})
    }
  }

  const engine = new WorkflowLoopEngine({
    dispatchStep,
    now: () => Date.now(),
    uuid: () => `loop-${task.provider}-${randomUUID()}`,
    isCancelled: () =>
      ownershipLost || scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner,
    onState: (snap) => {
      // Keep the stall reconciler's basis fresh per iteration: each completed
      // iteration re-stamps runningSince so the 6h backstop measures time-since-last-
      // iteration, not loop-start (a loop running > 6h total is NOT falsely reaped).
      // Only on running snapshots — never resurrect a terminal task. Note: the
      // run-queue liveness cross-check does NOT help a loop (a main-side run creates no
      // RunQueueJob), so runningSince freshness is the sole stall safety — which
      // suffices, since each iteration is itself bounded by stepTimeoutMs.
      if (snap.status !== 'running') return
      if (!scheduledOccurrenceTransaction.heartbeat(owner, new Date().toISOString())) {
        ownershipLost = true
        failScheduledOccurrence(owner, 'Scheduled workflow loop heartbeat could not be persisted.')
        return
      }
      // 7c — LIVE per-iteration progress: refresh the cached count/spend on the
      // definition (the start-of-run reset already cleared the prior stopReason, so it
      // stays absent until completion) and fire the broadcasts so the Electron row + iOS
      // badge update live. No new IPC, no schema change (reuses the slice-7b fields).
      // Bounded to <= maxIterations writes/loop — each iteration is a full provider run.
      if (task.workflowId) {
        AppStore.updateWorkflowDefinition(task.workflowId, {
          lastRunIterationCount: snap.iterationsCompleted,
          ...(typeof snap.budget.spentTokens === 'number'
            ? { lastRunTokens: snap.budget.spentTokens }
            : {})
        })
        broadcastWorkflowProgress()
      }
    }
  })

  let snap
  try {
    snap = await engine.run(engineConfig)
  } catch (error) {
    failScheduledOccurrence(
      owner,
      `Workflow loop crashed: ${error instanceof Error ? error.message : String(error)}`
    )
    return
  }

  // An external cancel or failed heartbeat can release/poison authority while
  // the current child transport unwinds. Do not append a second terminal event
  // or try to overwrite the already-settled durable outcome.
  if (ownershipLost || scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) !== owner) {
    return
  }

  // Execution-level terminal ledger event; NO iteration tag and NO tokens/costUsd —
  // the per-iteration 'harvested' events already sum to the cumulative total
  // (foldWorkflowRunSummary SUMS forensics across events), so repeating the cumulative
  // here would DOUBLE-count the loop's spend in the summary.
  appendLoopEvent({
    kind: 'loop_settled',
    scheduledTaskId: task.id,
    ...(snap.stopReason ? { stopReason: snap.stopReason } : {}),
    ...(snap.error ? { error: snap.error } : {})
  } as WorkflowRunEventInput)

  // The SINGLE terminal mark — only an infra 'failed' bumps failureStreak.
  const outcome = mapLoopSnapshotToScheduledOutcome(snap)
  const settled = settleScheduledOccurrence(owner, outcome.status, {
    completedAt: new Date().toISOString(),
    ...(outcome.lastError ? { lastError: outcome.lastError } : {})
  })
  if (!settled && !ownershipLost) {
    console.error(`[scheduled-occurrence] exact loop settlement rejected for task ${owner.taskId}`)
  }
  if (!settled) return

  // Slice 7b — cache THIS loop's summary on the workflow definition (mirrors how
  // lastStatus/lastRunAt are cached) so the SYNC remote-projection builder can carry
  // the iteration count / spend / stop reason to iOS, then push it immediately. The
  // projection otherwise only re-fires on the NEXT definition change, which would
  // leave the phone's loop badge stale. updateWorkflowDefinition MERGES, so it
  // preserves the lastStatus the scheduled-task sync just wrote.
  if (task.workflowId) {
    AppStore.updateWorkflowDefinition(task.workflowId, {
      lastRunIterationCount: snap.iterationsCompleted,
      ...(snap.stopReason ? { lastRunStopReason: snap.stopReason } : {}),
      ...(typeof snap.budget.spentTokens === 'number'
        ? { lastRunTokens: snap.budget.spentTokens }
        : {})
    })
    // 7c — final state to both surfaces (was iOS-only); the Electron row now shows the
    // terminal "Nx · <reason>" live instead of waiting for the next scheduler tick.
    // Forced past the throttle so the phone reliably lands the terminal verdict.
    broadcastWorkflowProgress(true)
  }
}

// ── Mid-run steering (append-now / deliver-at-boundary) ─────────────────────
// Bookkeeping core in src/main/run/MidRunSteering.ts. The registry is
// in-memory only; the transcript message is the durable record and every
// consumer degrades gracefully when the registry is empty (restart).
const midRunSteeringRegistry = new MidRunSteeringRegistry()

const liveSteeringCoordinator = new LiveSteeringCoordinator({
  runManager,
  registry: midRunSteeringRegistry,
  steering: {
    midTurnSteeringEnabled: midTurnSteerEnabled(),
    piLiveSteerEnabled: piLiveSteerEnabled()
  },
  completeQueuedRun: (runId, reason) =>
    Boolean(
      runQueueServiceRef?.transitionJob(runId, 'completed', {
        statusReason: reason
      })
    ),
  fallbackQueuedRun: ({ runId, ownerToken, reason }) =>
    Boolean(
      runQueueServiceRef?.fallbackPromotedSteerJob({
        runId,
        ownerToken,
        reason,
        fallbackStatus: 'queued'
      })
    )
})

/** Append a steering user message to the chat and make it visible on every
 * surface immediately (renderer via chat-updated, paired devices via the
 * bridge thread snapshot — the same pair `seedScheduledSoloTranscript`
 * uses). Returns the saved chat. */
function appendMidRunSteeringMessage(chat: ChatRecord, message: ChatMessage): ChatRecord {
  const updated = saveAndBroadcastChat({
    ...chat,
    messages: [...(chat.messages || []), message],
    updatedAt: Date.now()
  })
  bridgeBroadcasterRef?.broadcastThreadUpdated(updated.appChatId)
  pushRemoteThreadSnapshotForChat?.(updated)
  return updated
}

/**
 * Runtime-evidence gate for steer absorption. `isEnsembleRoundDispatchLive`
 * reads only the PERSISTED round record, which can still say "running" after
 * a crash — absorbing into such a round would strand the interjection because
 * no hop or same-round boundary turn is coming. Require corroboration that the
 * round genuinely resumes or is executing: a live in-memory RunManager
 * session for the chat (absent after restart by construction), or persisted
 * pending/sleeping wakeups (which
 * boot recovery re-arms, so their round WILL produce further hops). A brief
 * between-hop gap can false-negative — that degrades to the legacy
 * interrupt-steer, never to a stranded message.
 */
function ensembleRoundLiveForSteerAbsorb(
  chatId: string,
  round: Parameters<typeof isEnsembleRoundDispatchLive>[0]
): boolean {
  if (!isEnsembleRoundDispatchLive(round)) return false
  if (ensembleOrchestratorRef?.canAbsorbMidRunSteering(chatId, round?.roundId)) return true
  if ((round?.pendingWakeupIds?.length || 0) > 0) return true
  if ((round?.sleepingParticipantIds?.length || 0) > 0) return true
  return RUN_MANAGER_PROVIDERS.some((provider) =>
    runManager.getActiveByProvider(provider).some((session) => session.appChatId === chatId)
  )
}

/**
 * Absorb an ensemble steer/queue interjection into the LIVE round instead of
 * cancel-round-and-restart. The message is appended (and broadcast)
 * immediately; every subsequent hop's prompt is rebuilt from the live chat
 * record and its "new since your previous turn" delta transcript carries the
 * interjection natively — full and slim turns alike — so no round, hop, or
 * provider session is disturbed. Optional attachment metadata rides on the
 * message for transcript previews; runtime merge (images/grants/DM) is owned
 * by the orchestrator absorb path. Callers gate on
 * `midRunSteeringAbsorbEligible`.
 */
function appendEnsembleSteerIntoLiveRound(
  chatId: string,
  text: string,
  extras?: {
    imageAttachments?: Array<{ id?: string; path: string; name?: string }>
    imageThumbnails?: Array<{
      dataBase64: string
      mimeType: string
      width?: number
      height?: number
    }>
  }
): { messageId: string; entryId: string } {
  const chat = AppStore.getChat(chatId)
  if (!chat) {
    throw new Error('Ensemble steer target chat disappeared before absorption.')
  }
  const nowIso = new Date().toISOString()
  const messageId = `midrun-steer-${randomUUID()}`
  const imageAttachments = Array.isArray(extras?.imageAttachments) ? extras.imageAttachments : []
  const imageThumbnails = Array.isArray(extras?.imageThumbnails) ? extras.imageThumbnails : []
  appendMidRunSteeringMessage(
    chat,
    buildMidRunSteeringMessage({
      id: messageId,
      content: text,
      timestampIso: nowIso,
      author: HOST_MIDRUN_STEERING_AUTHOR,
      ...(imageAttachments.length > 0 ? { imageAttachments } : {}),
      ...(imageThumbnails.length > 0 ? { imageThumbnails } : {})
    })
  )
  const entry = midRunSteeringRegistry.register({
    chatId,
    messageId,
    text,
    source: 'ensembleSteer',
    authorKind: 'host',
    createdAtIso: nowIso
  })
  // The seat that is RUNNING right now is the one seat no later hop prompt can
  // reach. A pi seat can take the interjection mid-turn; every other provider
  // composes its turn once at dispatch and must wait for the boundary. Opt-in,
  // best-effort, and confirmed only by pi's own queue drain.
  attemptPiLiveSteerDelivery(chatId, entry)
  return { messageId, entryId: entry.id }
}

/**
 * Scheduler-tick companion for a due task whose chat is busy: the tick keeps
 * skipping dispatch (never collide with a live run), but a plain solo task's
 * message now lands in the transcript AT FIRE TIME, timestamped with
 * `firedAt`. The later idle-time dispatch recognizes the append (via the
 * registry, or the deterministic message id after a restart) and suppresses
 * its own seed. Idempotent across the tick's ~1s due-retry cadence.
 */
function maybeAppendScheduledSteeringForBusyTask(
  task: ScheduledTask,
  hasWorkflowLoop: boolean
): void {
  try {
    const chat = AppStore.getChat(task.chatId)
    if (!chat) return
    if (
      !shouldAppendScheduledSteeringOnBusy({
        taskKind: task.kind,
        hasWorkflowLoop,
        chatIsEnsemble: Boolean(chat.ensemble) || chat.chatKind === 'ensemble'
      })
    ) {
      return
    }
    if (midRunSteeringRegistry.entryForScheduledTask(task.chatId, task.id)) return
    const firedAtIso = task.firedAt || new Date().toISOString()
    const messageId = scheduledSteeringMessageId(task.id, firedAtIso)
    const content = task.displayPrompt || task.prompt
    const alreadyAppended = (chat.messages || []).some((message) => message.id === messageId)
    if (!alreadyAppended) {
      appendMidRunSteeringMessage(
        chat,
        buildMidRunSteeringMessage({
          id: messageId,
          content,
          timestampIso: firedAtIso,
          author: HOST_MIDRUN_STEERING_AUTHOR
        })
      )
    }
    // Register either way: after a restart the durable append survives while
    // the registry does not, and the seed suppression keys off the registry.
    midRunSteeringRegistry.register({
      chatId: task.chatId,
      messageId,
      text: content,
      source: 'scheduledTask',
      authorKind: 'host',
      createdAtIso: firedAtIso,
      scheduledTaskId: task.id
    })
  } catch (error) {
    console.warn('[midrun-steering] scheduled fire-time append failed:', error)
  }
}

function seedScheduledSoloTranscript(
  task: ScheduledTask,
  owner: ScheduledOccurrenceOwner,
  payload: AgentRunPayload,
  executionWorkspacePath: string
): string | null {
  const chat = AppStore.getChat(owner.chatId)
  if (!chat || chat.chatKind === 'ensemble') {
    throw new Error('Scheduled solo transcript target is not a solo chat.')
  }
  if ((chat.runs || []).some((run) => run.runId === owner.ownerRunId)) {
    throw new Error('Scheduled solo transcript already contains this occurrence run.')
  }
  const timestamp = new Date().toISOString()
  // Fire-time steering append: when this task fired on a busy chat, its
  // message already sits in the transcript timestamped at fire time. Reuse
  // it as this run's prompt message instead of appending a duplicate. If the
  // fire-time append was lost (whole-record renderer save race), re-append
  // it with the ORIGINAL fire timestamp — self-healing in both directions.
  const steeringEntry = midRunSteeringRegistry.entryForScheduledTask(owner.chatId, task.id)
  const existingSteeringMessage =
    (steeringEntry
      ? (chat.messages || []).find((message) => message.id === steeringEntry.messageId)
      : null) || findScheduledSteeringMessage(chat.messages || [], task.id, task.firedAt)
  const promptMessageId =
    steeringEntry?.messageId || existingSteeringMessage?.id || `scheduled-user-${randomUUID()}`
  const userMessage: ChatMessage | null = existingSteeringMessage
    ? null
    : steeringEntry
      ? buildMidRunSteeringMessage({
          id: steeringEntry.messageId,
          content: task.displayPrompt || task.prompt,
          timestampIso: steeringEntry.createdAtIso,
          author: HOST_MIDRUN_STEERING_AUTHOR
        })
      : {
          id: promptMessageId,
          role: 'user',
          content: task.displayPrompt || task.prompt,
          timestamp
        }
  const run: ChatRun = {
    runId: owner.ownerRunId,
    provider: owner.provider,
    startedAt: timestamp,
    promptMessageId,
    requestedModel: payload.model,
    approvalMode: payload.approvalMode,
    workflowMode: payload.workflowMode,
    ...(payload.runtimeProfileId ? { runtimeProfileId: payload.runtimeProfileId } : {}),
    ...(payload.geminiAuthProfileId !== undefined
      ? { geminiAuthProfileId: payload.geminiAuthProfileId }
      : {}),
    effectiveWorkspacePath: executionWorkspacePath,
    status: 'running',
    rawEventsFile: `run-events/${owner.ownerRunId}.jsonl`
  }
  // Install the terminal-finalization owner before persistence. If chat saving
  // succeeds and any later seed step throws, the catch path can still close the
  // exact persisted ChatRun instead of leaving a permanent running transcript.
  registerBridgeRunTranscript({
    runId: owner.ownerRunId,
    chatId: owner.chatId,
    provider: owner.provider,
    promptMessageId,
    workspacePath: executionWorkspacePath
  })
  const updated = saveAndBroadcastChat({
    ...chat,
    messages: userMessage ? [...(chat.messages || []), userMessage] : [...(chat.messages || [])],
    runs: [...(chat.runs || []), run],
    updatedAt: Date.now()
  })
  void captureWorkspaceSnapshot(executionWorkspacePath)
    .then((snapshot) => {
      const transcript = bridgeRunTranscripts.get(owner.ownerRunId)
      if (transcript) transcript.preSnapshot = snapshot
    })
    .catch((error) => {
      console.warn(`[scheduled-occurrence] pre-run snapshot failed for ${owner.ownerRunId}:`, error)
    })
  bridgeBroadcasterRef?.broadcastThreadUpdated(updated.appChatId)
  pushRemoteThreadSnapshotForChat?.(updated)
  return steeringEntry?.id || null
}

async function failScheduledSoloLaunchAfterTranscriptSeed(
  owner: ScheduledOccurrenceOwner,
  error: unknown
): Promise<void> {
  const message = error instanceof Error ? error.message : String(error)
  const route = { appRunId: owner.ownerRunId, appChatId: owner.chatId }
  await terminateExactProviderSession(owner.provider, owner.ownerRunId, 'failed')
  const bridgeState = bridgeRunTranscripts.get(owner.ownerRunId)
  if (bridgeState?.status !== 'running') {
    workflowBudgetRegistry.onExit(owner.ownerRunId)
    failScheduledOccurrence(owner, `Headless scheduled dispatch failed: ${message}`)
    return
  }
  try {
    sendAgentCompatError(headlessRunSender, owner.provider, message, route)
  } catch (publishError) {
    console.error('[scheduled-occurrence] solo launch error publication failed', publishError)
  }
  try {
    sendAgentCompatExit(headlessRunSender, owner.provider, -1, route)
  } catch (exitError) {
    console.error('[scheduled-occurrence] solo launch exit publication failed', exitError)
    finalizeBridgeRunTranscript(owner.ownerRunId, 'failed')
  } finally {
    workflowBudgetRegistry.onExit(owner.ownerRunId)
    failScheduledOccurrence(owner, `Headless scheduled dispatch failed: ${message}`)
  }
}

async function dispatchDueScheduledTaskHeadless(
  task: ScheduledTask,
  owner: ScheduledOccurrenceOwner
): Promise<void> {
  const composer = composerServiceRef
  const dispatch = dispatchMainOwnedScheduledOccurrenceRef
  if (!composer || !dispatch) {
    failScheduledOccurrence(owner, 'Scheduled solo dispatch is not initialized.')
    return
  }
  let transcriptSeeded = false
  let unsealedLaunchReason: string | null = null
  try {
    if (!verifyScheduledTaskAttachmentOwnership(task)) {
      failScheduledOccurrence(
        owner,
        'Headless scheduled attachment ownership could not be verified.'
      )
      return
    }
    const executionWorkspacePath = assertScheduledOccurrenceWorkspace(owner)
    // Fire-time steering: the task's message may already be in the transcript
    // (appended when the countdown ended on a busy chat). Providers whose
    // composition injects host transcript would read the content twice — once
    // as history, once as the request — so exclude the pre-appended message.
    // Session-native lanes inject no history and take no exclusion.
    const dispatchSteeringEntry = midRunSteeringRegistry.entryForScheduledTask(task.chatId, task.id)
    const dispatchSteeringMessage =
      (dispatchSteeringEntry
        ? (AppStore.getChat(task.chatId)?.messages || []).find(
            (message) => message.id === dispatchSteeringEntry.messageId
          )
        : null) ||
      findScheduledSteeringMessage(
        AppStore.getChat(task.chatId)?.messages || [],
        task.id,
        task.firedAt
      )
    const dispatchSteeringMessageId =
      dispatchSteeringEntry?.messageId || dispatchSteeringMessage?.id
    const dispatchSteeringPlan = dispatchSteeringMessageId
      ? planSteeringContext({
          lane: 'solo-boundary',
          provider: task.provider,
          resumeProviderSessionId: null
        })
      : null
    const composed = await composer.composeRun({
      chatId: task.chatId,
      appRunId: owner.ownerRunId,
      provider: task.provider,
      workspace: owner.workspacePath,
      prompt: task.prompt,
      selectedModelType: task.selectedModelType,
      customModel: task.customModel,
      approvalMode: task.approvalMode,
      ...scheduledHeadlessComposeFields(task),
      sessionTrust: task.sessionTrust,
      imageAttachments: task.imageAttachments,
      externalPathGrants: task.externalPathGrants,
      codexReasoningEffort: task.codexReasoningEffort,
      grokReasoningEffort: task.grokReasoningEffort,
      museReasoningEffort: task.museReasoningEffort,
      cursorReasoningEffort: task.cursorReasoningEffort,
      cursorFastMode: task.cursorFastMode,
      codexServiceTier: task.codexServiceTier,
      claudeReasoningEffort: task.claudeReasoningEffort,
      claudeFastMode: task.claudeFastMode,
      kimiReasoningEffort: task.kimiReasoningEffort,
      kimiThinkingEnabled: task.kimiThinkingEnabled,
      runtimeProfileId: task.runtimeProfileId,
      geminiAuthProfileId: task.geminiAuthProfileId,
      handoffSourceRunId: task.handoffSourceRunId,
      scheduledTaskId: task.id,
      ...(dispatchSteeringMessageId &&
      dispatchSteeringPlan?.kind === 'prompt-with-history-exclusion'
        ? { excludeMessageIds: [dispatchSteeringMessageId] }
        : {})
    })
    const sealService = scheduledOccurrenceSealServiceRef
    if (sealService) {
      const sealOutcome = await sealService.sealSoloOccurrence({
        task,
        ownerRunId: owner.ownerRunId,
        workspaceRealPath: executionWorkspacePath,
        composed: scheduledSealComposedFacts(composed, AppStore.getChat(task.chatId))
      })
      if (sealOutcome.ok === false) {
        failScheduledOccurrence(
          owner,
          `Scheduled occurrence seal verification failed: ${sealOutcome.reason}`
        )
        return
      }
      if (sealOutcome.ok === 'skipped') {
        unsealedLaunchReason = sealOutcome.reason
        console.warn(`[scheduled-occurrence] ${sealOutcome.reason}`)
      }
    }
    transcriptSeeded = true
    const scheduledSteeringEntryId = seedScheduledSoloTranscript(
      task,
      owner,
      composed,
      executionWorkspacePath
    )
    if (unsealedLaunchReason) {
      try {
        sendAgentCompatLine(
          headlessRunSender,
          owner.provider,
          {
            type: 'provider_warning',
            provider: owner.provider,
            severity: 'warning',
            title: 'Scheduled launch ran without an exact launch seal',
            message: unsealedLaunchReason
          },
          { appRunId: owner.ownerRunId, appChatId: owner.chatId }
        )
      } catch (warningError) {
        console.warn(
          `[scheduled-occurrence] could not publish unsealed-launch warning for ${owner.ownerRunId}:`,
          warningError
        )
      }
    }
    const result = await dispatch({ ...composed, scheduledTaskId: task.id } as AgentRunPayload, {
      sender: headlessRunSender
    })
    if (result.dispatched && scheduledSteeringEntryId) {
      midRunSteeringRegistry.markDelivered(
        owner.chatId,
        [scheduledSteeringEntryId],
        new Date().toISOString()
      )
    }
    if (
      !result.dispatched &&
      scheduledOccurrenceOwners.lookupByOwnerRunId(owner.ownerRunId) === owner
    ) {
      failScheduledOccurrence(owner, 'Scheduled solo provider preflight did not dispatch.')
    }
  } catch (error) {
    if (transcriptSeeded) {
      await failScheduledSoloLaunchAfterTranscriptSeed(owner, error)
    } else {
      failScheduledOccurrence(
        owner,
        `Headless scheduled dispatch failed: ${error instanceof Error ? error.message : String(error)}`
      )
    }
  }
}

function emitDueScheduledTasks() {
  let dueTaskCount = 0
  try {
    if (scheduledOccurrenceRecoveryBlockedReason) {
      console.error(
        `[scheduled-occurrence] dispatch disabled: ${scheduledOccurrenceRecoveryBlockedReason}`
      )
      return
    }
    let materialized: ScheduledTask[] = []
    try {
      materialized = AppStore.materializeDueWorkflows(
        Date.now(),
        scheduledAttachmentPersistence.resolve
      ).map(ensureScheduledTaskSignedPosture)
    } catch (error) {
      console.error('[scheduled-occurrence] workflow materialization failed', error)
    }
    try {
      mainWindow?.webContents.send(
        'workflow-definitions-changed',
        AppStore.getWorkflowDefinitions()
      )
      if (materialized.length > 0) {
        mainWindow?.webContents.send('scheduled-tasks-changed', AppStore.getScheduledTasks())
      }
    } catch (error) {
      console.warn('[scheduled-occurrence] initial scheduler broadcast failed', error)
    }

    let dueTasks: ScheduledTask[] = []
    try {
      dueTasks = AppStore.getDueScheduledTasks(Date.now(), scheduledAttachmentPersistence.resolve)
    } catch (error) {
      console.error('[scheduled-occurrence] due-task listing failed', error)
    }
    dueTaskCount = dueTasks.length
    const rendererAvailable = Boolean(mainWindow && !mainWindow.webContents.isDestroyed())
    const headlessEnabled = AppStore.getSettings().headlessScheduledDispatchEnabled !== false
    for (const task of dueTasks) {
      try {
        const dueTaskRaw =
          task.status === 'due'
            ? task
            : AppStore.updateScheduledTask(task.id, {
                status: 'due',
                firedAt: new Date().toISOString()
              }) || task
        const dueTask = ensureScheduledTaskSignedPosture(dueTaskRaw)
        const configuredLoop = dueTask.workflowId
          ? AppStore.getWorkflowDefinition(dueTask.workflowId)?.loop
          : undefined
        if (dueTask.kind === 'ensemble' && configuredLoop) {
          const invalid = AppStore.updateScheduledTask(dueTask.id, {
            status: 'failed',
            completedAt: new Date().toISOString(),
            lastError: 'Ensemble scheduled occurrences cannot own workflow loops.'
          })
          if (invalid?.status === 'failed') {
            publishScheduledOccurrenceSettlement()
          } else {
            console.error(
              `[scheduled-occurrence] invalid ensemble loop could not be settled for task ${dueTask.id}`
            )
          }
          continue
        }
        const loopCfg = dueTask.kind !== 'ensemble' ? configuredLoop : undefined
        const ready =
          dueTask.kind === 'ensemble'
            ? Boolean(ensembleOrchestratorRef)
            : Boolean(composerServiceRef && dispatchMainOwnedScheduledOccurrenceRef)
        // The setting remains a daemon-mode kill switch. A live renderer no longer
        // owns dispatch; MAIN does, so opening or closing a window cannot change who
        // claims an occurrence.
        if (!ready || (!rendererAvailable && !headlessEnabled)) continue
        if (isScheduledOccurrenceChatBusy(dueTask)) {
          // Mid-run steering: the dispatch skip stands (never collide with a
          // live run), but a plain solo task's message lands in the
          // transcript at fire time and delivers on the next due-retry tick
          // once the chat idles.
          maybeAppendScheduledSteeringForBusyTask(dueTask, Boolean(configuredLoop))
          continue
        }

        const owner = scheduledOccurrenceTransaction.claim(dueTask)
        if (!owner) continue
        const claimedTask = AppStore.getScheduledTasks().find(
          (candidate) => candidate.id === owner.taskId
        )
        if (!claimedTask) {
          failScheduledOccurrence(owner, 'Claimed scheduled occurrence disappeared before launch.')
          continue
        }
        const launch =
          owner.rootOwner === 'ensemble-root'
            ? dispatchDueEnsembleScheduledTaskHeadless(claimedTask, owner)
            : owner.rootOwner === 'loop-root' && loopCfg
              ? dispatchDueScheduledLoopHeadless(claimedTask, loopCfg, owner)
              : owner.rootOwner === 'solo'
                ? dispatchDueScheduledTaskHeadless(claimedTask, owner)
                : Promise.reject(new Error('Scheduled occurrence root family is inconsistent.'))
        void launch.catch((error) => {
          failScheduledOccurrence(
            owner,
            `Scheduled occurrence launch failed: ${error instanceof Error ? error.message : String(error)}`
          )
        })
      } catch (error) {
        console.error(`[scheduled-occurrence] task ${task.id} failed in scheduler pump`, error)
      }
    }
  } catch (error) {
    console.error('[scheduled-occurrence] scheduler pump failed', error)
  } finally {
    if (dueTaskCount > 0) {
      try {
        mainWindow?.webContents.send(
          'workflow-definitions-changed',
          AppStore.getWorkflowDefinitions()
        )
        mainWindow?.webContents.send('scheduled-tasks-changed', AppStore.getScheduledTasks())
      } catch (error) {
        console.warn('[scheduled-occurrence] terminal scheduler broadcast failed', error)
      }
    }
    try {
      reconcileStalledScheduledTasks()
    } catch (error) {
      console.error('[scheduled-occurrence] stalled-task reconciliation failed', error)
    }
    emitDueIntrospectionSchedules()
    scheduleNextTaskTimer()
  }
}

function emitDueIntrospectionSchedules(): void {
  try {
    dispatchDueIntrospectionSchedules({
      getIntrospectionScheduleRecords: () => AppStore.getIntrospectionScheduleRecords(),
      updateIntrospectionScheduleRecord: (partial) => AppStore.updateIntrospectionSchedule(partial),
      getIntrospectionRuns: (workspaceId) => AppStore.getIntrospectionRuns(workspaceId),
      getWorkspacePath: (workspaceId) =>
        AppStore.getWorkspaces().find((workspace) => workspace.id === workspaceId)?.path,
      runManualIntrospection: (input) =>
        runManualIntrospection(
          createIntrospectionRunServiceDeps({
            getChats: (workspaceId) => AppStore.getChats(workspaceId),
            getRunEvents: (filter) => AppStore.getRunEvents(filter),
            getApprovalLedger: (filter) => AppStore.getApprovalLedger(filter),
            getMessageFeedbackReceipts: (filter) => AppStore.getMessageFeedbackReceipts(filter),
            createIntrospectionRun: (record) => AppStore.createIntrospectionRun(record),
            updateIntrospectionRun: (id, partial) => AppStore.updateIntrospectionRun(id, partial),
            saveMemoryProposalPack: (pack) => AppStore.saveMemoryProposalPack(pack)
          }),
          input
        )
    })
  } catch {
    // Scheduler failures must not wedge workflow timers.
  }
}

/**
 * Liveness predicate for the stall reconciler. MAIN-owned occurrence roots and
 * active RunManager sessions are authoritative even when no RunQueueJob exists;
 * otherwise a queue job counts as live only in a non-terminal state. The queue
 * status is `active` (not `running`) and approval-paused work remains live.
 */
function isScheduledRunLive(runId: string): boolean {
  const owner = scheduledOccurrenceOwners.lookupByOwnerRunId(runId)
  const transportRunIds = owner
    ? [owner.ownerRunId, ...scheduledOccurrenceOwners.lookupChildRunIdsForOwner(owner)]
    : [runId]
  if (
    transportRunIds.some((transportRunId) => {
      const session = runManager.get(transportRunId)
      return Boolean(session && isActiveRunSessionStatus(session.status))
    })
  ) {
    return true
  }
  return transportRunIds.some((transportRunId) => {
    const job = AppStore.getRunQueueJob(transportRunId)
    if (!job) return false
    switch (job.status) {
      case 'queued':
      case 'starting':
      case 'active':
      case 'paused':
      case 'cancelling':
        return true
      default:
        return false
    }
  })
}

/**
 * BACKSTOP sweep: settle wedged scheduled-workflow occurrences so a stuck one
 * can't silently disable a workflow forever. Settling clears `activeExecutionId`
 * (unblocking the next occurrence). Idempotent in the store. LOUD surface, de-duped
 * per occurrence: one durable run event + a scheduled-tasks-changed /
 * workflow-definitions-changed broadcast, the first time each workflowExecutionId
 * is settled this session.
 */
function reconcileStalledScheduledTasks(): void {
  let settled: ScheduledTask[]
  try {
    settled = AppStore.settleStalledScheduledTasks(isScheduledRunLive, Date.now())
  } catch {
    return
  }
  if (settled.length === 0) return

  try {
    for (const task of settled) {
      try {
        const owner = task.runId
          ? scheduledOccurrenceOwners.lookupByOwnerRunId(task.runId)
          : undefined
        if (owner && owner.taskId === task.id) {
          scheduledOccurrenceOwners.release(owner)
        }
      } catch (error) {
        console.error('[scheduled-occurrence] stalled owner release failed', error)
      }
      const key = task.workflowExecutionId || task.id
      if (stalledOccurrenceEventKeys.has(key)) continue
      stalledOccurrenceEventKeys.add(key)
      try {
        appendDurableRunEvent({
          runId: task.runId || task.id,
          chatId: task.chatId,
          workspaceId: task.workspaceId,
          workspacePath: task.workspacePath,
          provider: task.provider,
          kind: 'lifecycle',
          phase: 'control',
          source: 'main',
          summary:
            task.lastError ||
            'Settled a wedged scheduled-workflow occurrence to unblock future runs',
          payload: {
            eventType: 'scheduled_workflow_stall_settled',
            scheduledTaskId: task.id,
            workflowId: task.workflowId,
            workflowExecutionId: task.workflowExecutionId,
            settledAt: task.completedAt,
            lastError: task.lastError
          }
        })
      } catch (error) {
        console.error('[scheduled-occurrence] stalled settlement audit failed', error)
      }
    }
  } finally {
    publishScheduledOccurrenceSettlement()
  }
}

function scheduleNextTaskTimer() {
  clearScheduledTaskTimer()
  // Workspace-lock STARTUP failure already sets `scheduledOccurrenceRecoveryBlockedReason`
  // in the same catch, so that case is covered by the first disjunct. Reading the
  // workspace-lock flag directly here additionally caught the MID-SESSION mutation
  // poison, which has nothing to do with scheduling and would stop the timer for
  // the rest of the process.
  if (scheduledOccurrenceRecoveryBlockedReason || historyDeletionStartupRecoveryBlockedReason) {
    return
  }
  const nowMs = Date.now()
  const nextRunAtMs = getNextScheduledTaskRunAtMs({
    // Pending history-deletion scopes are deliberately absent from the
    // dispatchable projection. Using the raw durable list here can otherwise
    // re-arm a zero-delay timer forever while the deletion remains fenced.
    tasks: AppStore.getDispatchableScheduledTasks(),
    nextWorkflowRunAtMs: AppStore.getNextWorkflowRunAtMs(),
    nextIntrospectionRunAtMs: AppStore.getNextIntrospectionScheduleRunAtMs(nowMs),
    nowMs
  })
  if (nextRunAtMs === null) {
    return
  }
  const delay = Math.max(0, Math.min(MAX_SCHEDULE_TIMER_DELAY_MS, nextRunAtMs - nowMs))
  scheduledTaskTimer = setTimeout(emitDueScheduledTasks, delay)
}

async function getCodexStatusSnapshotForCliRuntime(): Promise<any> {
  let accountStatus: any = null
  let rateLimitStatus: any = null
  let codexUsage: any = null
  let startupError: string | null = null
  try {
    await withUnownedCodexClientLifecycle(
      'status-snapshot',
      async (client) => {
        await client.ensureStarted(app.getVersion())
        try {
          accountStatus = await client.request('account/read', { refreshToken: false }, 15_000)
        } catch (error) {
          accountStatus = { error: error instanceof Error ? error.message : String(error) }
        }
        try {
          rateLimitStatus = await client.request('account/rateLimits/read', {}, 15_000)
        } catch (error) {
          rateLimitStatus = { error: error instanceof Error ? error.message : String(error) }
        }
      },
      { borrowActiveProviderClient: true }
    )
  } catch (error) {
    startupError = error instanceof Error ? error.message : String(error)
  }
  try {
    codexUsage = await fetchCodexUsageSnapshot()
  } catch (error) {
    codexUsage = {
      configured: Boolean(AppStore.getSettings().codexUsageCredential?.accountId),
      source: 'chatgpt-wham',
      error: error instanceof Error ? error.message : String(error)
    }
  }
  return buildCodexStatusSnapshot({
    version: await readCliVersion('codex'),
    clientStarted: Boolean(codexClient),
    accountStatus,
    rateLimitStatus,
    codexUsage,
    startupError
  })
}

async function getCodexMcpStatusSnapshotForCliRuntime(): Promise<any> {
  return withUnownedCodexClientLifecycle(
    'mcp-status-snapshot',
    async (client) => {
      await client.ensureStarted(app.getVersion())
      return client.request(
        'mcpServerStatus/list',
        {
          detail: 'toolsAndAuthOnly',
          limit: 100
        },
        20_000
      )
    },
    { borrowActiveProviderClient: true }
  )
}

async function getKimiAdmittedStatusSnapshot(): Promise<any> {
  const resolved = await resolveCliProviderBinary('kimi')
  if (!resolved.binaryPath) {
    return {
      provider: 'kimi',
      label: providerLabel('kimi'),
      available: false,
      version: 'missing',
      appServer: 'unsupported',
      authState: 'unknown',
      setupRequired: true,
      binaryPath: null,
      binarySource: resolved.source,
      error: resolved.error
    }
  }
  const admission = await admitKimiRuntime({
    binaryPath: resolved.binaryPath,
    isPackaged: app.isPackaged,
    environment: process.env
  })
  if (!admission.admitted) {
    return {
      provider: 'kimi',
      label: providerLabel('kimi'),
      available: false,
      version: 'security-unavailable',
      appServer: 'unsupported',
      authState: 'unknown',
      setupRequired: true,
      binaryPath: resolved.binaryPath,
      binarySource: resolved.source,
      error: admission.message,
      supportsSessions: false,
      supportsApprovals: false,
      supportsQuota: false,
      supportsMcpStatus: false
    }
  }
  const managedAuthState = await detectKimiManagedAuthState(
    join(os.homedir(), '.kimi-code'),
    kimiHomeFsAdapter
  )
  return {
    provider: 'kimi',
    label: providerLabel('kimi'),
    available: true,
    version: admission.capability.version,
    appServer: 'acp',
    authState: managedAuthState,
    setupRequired: false,
    binaryPath: admission.binaryPath,
    binarySource: resolved.source,
    supportsSessions: true,
    supportsApprovals: true,
    supportsQuota: false,
    // The admitted seat has a mandatory per-run authenticated HTTP gateway.
    // This is not a provider-native/global MCP installation claim.
    supportsMcpStatus: true,
    runtimeAdmissionMode: admission.mode
  }
}

async function getKimiRosterConfigurationStatus(): Promise<{
  available: boolean
  authState?: string
}> {
  const resolved = await resolveCliProviderBinary('kimi')
  if (!resolved.binaryPath) return { available: false, authState: 'unknown' }
  return {
    available: true,
    authState: await detectKimiManagedAuthState(join(os.homedir(), '.kimi-code'), kimiHomeFsAdapter)
  }
}

const managedRunConfiguredProviderDiscovery = createConfiguredProviderDetector({
  getCodexConfiguredStatus: async () => {
    const resolved = await resolveCliProviderBinary('codex')
    if (!resolved.binaryPath) return { available: false, authState: 'unknown' }
    const accountStatus = await withUnownedCodexClientLifecycle(
      'configured-provider-probe',
      async (client) => {
        await client.ensureStarted(app.getVersion())
        return client.request('account/read', { refreshToken: false }, 15_000)
      },
      { borrowActiveProviderClient: true }
    )
    const snapshot = buildCodexStatusSnapshot({
      version: 'configured-provider-probe',
      clientStarted: true,
      accountStatus
    })
    return {
      available: snapshot.available === true,
      // The private-home app-server account result is authoritative. Imported
      // quota telemetry never configures a runtime seat.
      authState: snapshot.authState
    }
  },
  getClaudeConfiguredStatus: async (settings) => {
    const resolved = await resolveCliProviderBinary('claude')
    return {
      available: Boolean(resolved.binaryPath),
      authState: settings.claudeApiKey ? 'api-key' : await readClaudeAuthState(resolved)
    }
  },
  getKimiConfiguredStatus: getKimiRosterConfigurationStatus,
  getPiConfiguredUpstreamCount: () =>
    piKeyStoreRef ? piKeyStoreRef.getStatus().configuredUpstreams.length : 0,
  getOllamaStatus: async (settings) => {
    const models = await fetchOllamaModels(settings)
    return { available: true, modelCount: models.length }
  },
  getAntigravityCombinedModels: (settings) =>
    discoverAuthenticatedAntigravityCombinedModels(settings, {
      getSecretStore: () => antigravityGeminiApiSecretStoreRef,
      // Without a userDataPath the agy last-known-good cache is inert and every
      // failed discovery drops to the hardcoded floor, so this is the wiring that
      // makes the cache real rather than dead code.
      agyDependencies: { cache: { userDataPath: app.getPath('userData') } },
      recordGeminiApiOutcome: (outcome) =>
        antigravityGeminiApiDiscoveryOutcomeStore.record(outcome.status, outcome.modelCount)
    }),
  getAntigravityGeminiApiKeyGeneration: () => {
    try {
      const status = antigravityGeminiApiSecretStoreRef?.getStatus()
      return status?.updatedAt ?? (status?.configured ? 'configured' : 'unconfigured')
    } catch {
      return 'unavailable'
    }
  },
  onDiscoveryComplete: requestRemoteProviderModelsRefresh
})
const detectManagedRunConfiguredProviders = (settings: AppSettings): Promise<Set<ProviderId>> =>
  managedRunConfiguredProviderDiscovery.snapshot(settings)

const cliProviderRuntimeDeps: CliProviderRuntimeDependencies = {
  getSettings: () => AppStore.getSettings(),
  getRuntimeProfiles: (provider?: ProviderId) => AppStore.getRuntimeProfiles(provider),
  getGeminiAuthStatusSnapshot: () => getGeminiAuthStatusSnapshot(),
  getGeminiMcpBridgeStatus: (options) => getGeminiMcpBridgeStatus(options),
  getCodexStatusSnapshot: getCodexStatusSnapshotForCliRuntime,
  getCodexMcpStatusSnapshot: getCodexMcpStatusSnapshotForCliRuntime,
  getKimiStatusSnapshot: getKimiAdmittedStatusSnapshot
}

function taskWraithMcpProfileStoreStateForPayload(payload: AgentRunPayload): {
  storeSessionId: string | null
  storeReceipt: ChatRecord['taskWraithMcpProfileReceipt']
  chatFound: boolean
  missingEnsembleParticipant: boolean
  routeProviderMismatch: boolean
  ephemeralProviderReroute: boolean
  mainOwnedContextIsolated: boolean
  storeWritable: boolean
} {
  const chat = payload.appChatId ? AppStore.getChat(payload.appChatId) : null
  if (isMainOwnedContextIsolatedPayload(payload)) {
    return {
      storeSessionId: null,
      storeReceipt: undefined,
      chatFound: Boolean(chat),
      missingEnsembleParticipant: false,
      routeProviderMismatch: false,
      ephemeralProviderReroute: false,
      mainOwnedContextIsolated: true,
      storeWritable: false
    }
  }
  const ensembleParticipantId = payload.ensembleRun?.participantId
  const participant =
    chat?.ensemble && ensembleParticipantId
      ? chat.ensemble.participants.find((candidate) => candidate.id === ensembleParticipantId) ||
        null
      : null
  const missingEnsembleParticipant = !isTaskWraithMcpEnsembleLanePresent({
    chatIsEnsemble: Boolean(chat?.ensemble),
    participantId: ensembleParticipantId,
    participantFound: Boolean(participant)
  })
  const routeOwnerProvider = participant ? participant.provider : chat?.provider
  const rawRouteProviderMismatch = Boolean(
    routeOwnerProvider &&
    !isTaskWraithMcpRouteProviderMatch({
      payloadProvider: payload.provider,
      ownerProvider: routeOwnerProvider
    })
  )
  const ephemeralProviderReroute = Boolean(
    chat &&
    !missingEnsembleParticipant &&
    isTaskWraithMcpAuthorizedEphemeralReroute({
      payloadProvider: payload.provider,
      providerReroute: payload.providerReroute
    })
  )
  const routeProviderMismatch = rawRouteProviderMismatch && !ephemeralProviderReroute
  const storeWritable = Boolean(chat && !missingEnsembleParticipant && !ephemeralProviderReroute)
  return {
    storeSessionId:
      missingEnsembleParticipant || ephemeralProviderReroute
        ? null
        : participant
          ? (participant.linkedProviderSessionId ?? null)
          : (chat?.linkedProviderSessionId ?? null),
    storeReceipt:
      missingEnsembleParticipant || ephemeralProviderReroute
        ? undefined
        : participant
          ? participant.taskWraithMcpProfileReceipt
          : chat?.taskWraithMcpProfileReceipt,
    chatFound: Boolean(chat),
    missingEnsembleParticipant,
    routeProviderMismatch,
    ephemeralProviderReroute,
    mainOwnedContextIsolated: false,
    storeWritable
  }
}

interface ProviderSeatStoreTarget {
  chat: ChatRecord
  participantId?: string
  linkedProviderSessionId?: string | null
  generation?: ChatRecord['seatGeneration']
  lastRun?: ChatRun
}

function providerSeatStoreTarget(
  appChatId: string | undefined,
  provider: ProviderId,
  participantId?: string
): ProviderSeatStoreTarget | null {
  if (!appChatId) return null
  const chat = AppStore.getChat(appChatId)
  if (!chat) return null
  if (chat.ensemble) {
    if (!participantId) return null
    const participant = chat.ensemble.participants.find(
      (candidate) => candidate.id === participantId && candidate.provider === provider
    )
    if (!participant) return null
    const lastRun = [...(chat.runs || [])]
      .reverse()
      .find(
        (run) =>
          run.ensembleParticipantId === participant.id &&
          (run.provider === undefined || run.provider === provider)
      )
    return {
      chat,
      participantId: participant.id,
      linkedProviderSessionId: participant.linkedProviderSessionId,
      generation: participant.seatGeneration,
      lastRun
    }
  }
  if (participantId || (chat.provider && chat.provider !== provider)) return null
  const lastRun = [...(chat.runs || [])]
    .reverse()
    .find(
      (run) =>
        !run.ensembleParticipantId &&
        (run.provider === provider || (run.provider === undefined && chat.provider === provider))
    )
  return {
    chat,
    linkedProviderSessionId: chat.linkedProviderSessionId,
    generation: chat.seatGeneration,
    lastRun
  }
}

function providerSeatMetadataString(
  metadata: Record<string, unknown> | undefined,
  ...keys: string[]
): string | undefined {
  for (const key of keys) {
    const value = metadata?.[key]
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return undefined
}

function providerSeatGenerationInputForPayload(args: {
  payload: AgentRunPayload
  taskWraithMcpProfileId: NonNullable<AgentRunPayload['taskWraithMcpProfileId']>
  taskWraithMcpAdvertised: boolean
  capability: Pick<ProviderSeatGenerationInput, 'transport' | 'guaranteeTier'>
  previousRun?: ChatRun
}): ProviderSeatGenerationInput {
  const { payload, previousRun } = args
  const metadata = previousRun?.providerMetadata
  const settings = AppStore.getSettings()
  // Requested-first: generation configs are recorded from payload.model, so a
  // bootstrap reconstruction must stay in that namespace. Provider-reported
  // actualModel diverges by alias (claude '-1m', codex/kimi 'cli-default',
  // antigravity 'gemini-api:') and would fabricate a 'model' transition.
  const model = normalizeCliProviderModel(
    payload.provider,
    previousRun?.requestedModel || previousRun?.actualModel || payload.model
  )
  const approvalMode = previousRun?.approvalMode || payload.approvalMode || 'default'
  const workflowMode = previousRun?.workflowMode || payload.workflowMode || 'normal'
  const runtimeProfileId = previousRun?.runtimeProfileId || payload.runtimeProfileId || null
  // Lane-normalized posture: the renderer boundary clamp resolves an unsigned
  // default posture to the 'default' preset while the signed remote-composer
  // lane defers effectivePermissions to gate-time resolution. Both shapes
  // describe the same seat, so the fingerprint must not distinguish them
  // (un-normalized, an iOS→Mac continuation read as a 'system' change and
  // rotated the Claude session — total context loss, 2026-07-28).
  const posture = providerSeatPosturePrefixComponents({
    approvalMode,
    presetId:
      previousRun?.permissionPosture?.presetId ?? payload.effectivePermissions?.presetId ?? null,
    readOnly:
      previousRun?.permissionPosture?.readOnly ?? payload.effectivePermissions?.readOnly ?? null
  })
  const systemPromptFingerprint = providerSeatSystemPromptFingerprint({
    provider: payload.provider,
    scope: payload.scope,
    approvalMode,
    workflowMode,
    permissionPresetId: posture.presetId,
    readOnly: posture.readOnly,
    runtimeProfileId,
    runtimeProfileUpdatedAt: payload.runtimeProfile?.updatedAt || null,
    ollamaRunProfile: payload.ollamaRunProfile || null,
    nativeSubAgentRequests: settings.nativeSubAgentRequests || null,
    // Bootstrap semantics match every other field here: reconstruct from the
    // previous run's durable record when one exists, else the current payload.
    instructionsDigest: seatInstructionsDigestComponent(
      previousRun ? previousRun.promptEnvelope?.instructionsDigest : payload.instructionsDigest
    )
  })
  const toolsFingerprint = fingerprintProviderSeatPrefix('tools', [
    args.taskWraithMcpProfileId,
    args.taskWraithMcpAdvertised,
    payload.runtimeProfile?.mcpProfileId || null
  ])
  const priorKimiThinking = metadata?.kimiThinking
  const thinkingMode = previousRun
    ? typeof priorKimiThinking === 'boolean'
      ? priorKimiThinking
      : undefined
    : payload.provider === 'kimi'
      ? payload.kimiThinking
      : undefined
  const reasoningEffort = previousRun
    ? providerSeatMetadataString(metadata, 'claudeReasoningEffort', 'reasoningEffort')
    : payload.claudeReasoningEffort || payload.reasoningEffort
  const serviceTier = previousRun
    ? providerSeatMetadataString(metadata, 'serviceTier', 'claudeFastMode')
    : payload.serviceTier || (payload.claudeFastMode ? 'fast' : undefined)
  return {
    provider: payload.provider,
    model,
    transport: args.capability.transport,
    guaranteeTier: args.capability.guaranteeTier,
    systemPromptFingerprint,
    toolsFingerprint,
    taskWraithMcpProfileId: args.taskWraithMcpProfileId,
    thinkingMode,
    reasoningEffort,
    serviceTier
  }
}

/** Normalize the user-instructions digest into a seat-fingerprint component.
 * 'none' (nothing applied), absent, and pre-feature runs (no recorded digest)
 * must all hash IDENTICALLY, or shipping this feature would rotate every
 * healthy API-lane session once for users with no instructions configured. */
function seatInstructionsDigestComponent(digest: unknown): string | null {
  return typeof digest === 'string' && digest && digest !== 'none' ? digest : null
}

/** Single source of the seat 'system' fingerprint component order. The strict
 * stored-session reconstruction below hashes the same tuple from recorded run
 * fields; adding a component here without threading it there re-opens the
 * false-rotation class fixed on 2026-07-28. */
function providerSeatSystemPromptFingerprint(args: {
  provider: ProviderId
  scope: AgentRunPayload['scope']
  approvalMode: string
  workflowMode: string
  permissionPresetId: string
  readOnly: boolean
  runtimeProfileId: string | null
  runtimeProfileUpdatedAt: unknown
  ollamaRunProfile: unknown
  nativeSubAgentRequests: unknown
  /** Pre-normalized via seatInstructionsDigestComponent at every call site. */
  instructionsDigest: string | null
}): string {
  return fingerprintProviderSeatPrefix('system', [
    TASKWRAITH_RUNTIME_PREAMBLE_VERSION,
    args.provider,
    args.scope,
    args.approvalMode,
    args.workflowMode,
    args.permissionPresetId,
    args.readOnly,
    args.runtimeProfileId,
    args.runtimeProfileUpdatedAt,
    args.ollamaRunProfile,
    args.nativeSubAgentRequests,
    // Conditional, not a trailing null: the tuple is JSON.stringify'd, so a
    // 12th null element would change EVERY existing fingerprint on upgrade
    // and cold-start prompt caches fleet-wide. No instructions ⇒ the exact
    // pre-feature 11-element tuple.
    ...(args.instructionsDigest ? [args.instructionsDigest] : [])
  ])
}

/** Reconstruct the stored session's configuration from what the previous run
 * durably recorded — and nothing else. A field the run never persisted is
 * returned as undefined (unknown) so the mismatch check skips it; backfilling
 * it from the current dispatch is what used to rotate healthy sessions
 * whenever the two dispatch lanes phrased the same configuration
 * differently. */
function storedSeatSessionObservationForPayload(args: {
  payload: AgentRunPayload
  transport: ProviderSeatGenerationInput['transport']
  taskWraithMcpProfileId: NonNullable<AgentRunPayload['taskWraithMcpProfileId']>
  taskWraithMcpAdvertised: boolean
  previousRun?: ChatRun
}): StoredSeatSessionObservation {
  const { payload, previousRun } = args
  const settings = AppStore.getSettings()
  // Requested-model namespace ONLY: the stored generation's model was
  // normalized from payload.model, so the observation must come from the same
  // namespace. Provider-REPORTED actualModel diverges by alias for most
  // providers (claude '-1m' variants, codex/kimi/grok/cursor 'cli-default',
  // antigravity 'gemini-api:' ids) and is a serving detail, not a session
  // identity change — comparing it here is what rotated healthy sessions.
  const recordedModel = previousRun?.requestedModel
  let systemPromptFingerprint: string | undefined
  if (previousRun?.approvalMode) {
    const posture = providerSeatPosturePrefixComponents({
      approvalMode: previousRun.approvalMode,
      presetId: previousRun.permissionPosture?.presetId ?? null,
      readOnly: previousRun.permissionPosture?.readOnly ?? null
    })
    systemPromptFingerprint = providerSeatSystemPromptFingerprint({
      provider: payload.provider,
      scope: payload.scope,
      approvalMode: previousRun.approvalMode,
      workflowMode: previousRun.workflowMode || 'normal',
      permissionPresetId: posture.presetId,
      readOnly: posture.readOnly,
      runtimeProfileId: previousRun.runtimeProfileId || null,
      runtimeProfileUpdatedAt: payload.runtimeProfile?.updatedAt || null,
      ollamaRunProfile: payload.ollamaRunProfile || null,
      nativeSubAgentRequests: settings.nativeSubAgentRequests || null,
      // Recorded-observation contract: only what the previous run durably
      // recorded. A pre-feature run has no envelope → null → hashes the same
      // as 'none', so this addition alone never rotates an existing session.
      instructionsDigest: seatInstructionsDigestComponent(
        previousRun.promptEnvelope?.instructionsDigest
      )
    })
  }
  return {
    provider: payload.provider,
    transport: args.transport,
    model: recordedModel ? normalizeCliProviderModel(payload.provider, recordedModel) : undefined,
    toolsFingerprint: fingerprintProviderSeatPrefix('tools', [
      args.taskWraithMcpProfileId,
      args.taskWraithMcpAdvertised,
      payload.runtimeProfile?.mcpProfileId || null
    ]),
    taskWraithMcpProfileId: args.taskWraithMcpProfileId,
    systemPromptFingerprint
  }
}

/** Surface a REAL session rotation to the user as an ordinary system chat
 * message (mirrors the context-compaction notice pattern). Only called for
 * context-carrying (CLI) transports — API lanes replay history, so rotation
 * there is invisible to the conversation. Idempotent per run id: the seat
 * check can run again on retry without duplicating the row. */
function appendProviderSeatRotationNotice(args: {
  payload: AgentRunPayload
  previousModel: string | null
  nextModel: string | null
  causes: ProviderSeatGenerationTransition['causes']
  storedSessionMismatch: boolean
}): void {
  const appChatId = args.payload.appChatId
  if (!appChatId) return
  const chat = AppStore.getChat(appChatId)
  if (!chat) return
  const messageId = `seat-rotation-${args.payload.appRunId || Date.now()}`
  if (chat.messages.some((message) => message.id === messageId)) return
  const content = providerSeatRotationNoticeText({
    providerLabel: providerLabel(args.payload.provider),
    causes: args.causes,
    storedSessionMismatch: args.storedSessionMismatch,
    previousModel: args.previousModel,
    nextModel: args.nextModel
  })
  const updated: ChatRecord = {
    ...chat,
    messages: [
      ...chat.messages,
      {
        id: messageId,
        role: 'system',
        content,
        timestamp: new Date().toISOString(),
        ...(args.payload.appRunId ? { runId: args.payload.appRunId } : {}),
        metadata: {
          kind: 'providerSeatRotation',
          provider: args.payload.provider,
          ...(args.payload.ensembleRun?.participantId
            ? { ensembleParticipantId: args.payload.ensembleRun.participantId }
            : {})
        }
      }
    ],
    updatedAt: Date.now()
  }
  AppStore.saveChat(updated)
  broadcastChatUpdated(updated)
}

function saveProviderSeatGeneration(
  target: ProviderSeatStoreTarget,
  generation: NonNullable<ChatRecord['seatGeneration']>,
  clearProviderSession: boolean
): ChatRecord | null {
  const chat = AppStore.getChat(target.chat.appChatId) || target.chat
  if (target.participantId) {
    if (!chat.ensemble) return null
    const participant = chat.ensemble.participants.find(
      (candidate) => candidate.id === target.participantId
    )
    if (!participant || participant.provider !== generation.config.provider) return null
    const updated: ChatRecord = {
      ...chat,
      ensemble: {
        ...chat.ensemble,
        participants: chat.ensemble.participants.map((candidate) =>
          candidate.id === target.participantId
            ? {
                ...candidate,
                seatGeneration: generation,
                ...(clearProviderSession
                  ? {
                      linkedProviderSessionId: null,
                      taskWraithMcpProfileReceipt: undefined
                    }
                  : {})
              }
            : candidate
        )
      },
      updatedAt: Date.now()
    }
    saveAndBroadcastChat(updated)
    return updated
  }
  if (chat.provider && chat.provider !== generation.config.provider) return null
  const updated: ChatRecord = {
    ...chat,
    seatGeneration: generation,
    ...(clearProviderSession
      ? {
          linkedProviderSessionId: undefined,
          taskWraithMcpProfileReceipt: undefined
        }
      : {}),
    updatedAt: Date.now()
  }
  saveAndBroadcastChat(updated)
  return updated
}

function applyProviderSeatGeneration(args: {
  payload: AgentRunPayload
  actualTaskWraithMcpProfileId: NonNullable<AgentRunPayload['taskWraithMcpProfileId']>
  desiredTaskWraithMcpProfileId: NonNullable<AgentRunPayload['taskWraithMcpProfileId']>
  actualTaskWraithMcpAdvertised: boolean
  desiredTaskWraithMcpAdvertised: boolean
  storeWritable: boolean
}): {
  profileId: NonNullable<AgentRunPayload['taskWraithMcpProfileId']>
  advertised: boolean
} {
  const actual = {
    profileId: args.actualTaskWraithMcpProfileId,
    advertised: args.actualTaskWraithMcpAdvertised
  }
  if (!args.storeWritable) return actual
  const participantId = args.payload.ensembleRun?.participantId
  const target = providerSeatStoreTarget(
    args.payload.appChatId,
    args.payload.provider,
    participantId
  )
  if (!target) return actual
  const capability = buildPromptCacheCapabilitySummary(AppStore.getSettings()).capabilities.find(
    (candidate) => candidate.provider === args.payload.provider
  )
  if (!capability) return actual
  const currentInput = providerSeatGenerationInputForPayload({
    payload: args.payload,
    taskWraithMcpProfileId: args.desiredTaskWraithMcpProfileId,
    taskWraithMcpAdvertised: args.desiredTaskWraithMcpAdvertised,
    capability
  })
  const bootstrapInput =
    target.linkedProviderSessionId || args.payload.providerSessionId
      ? providerSeatGenerationInputForPayload({
          payload: args.payload,
          taskWraithMcpProfileId: args.actualTaskWraithMcpProfileId,
          taskWraithMcpAdvertised: args.actualTaskWraithMcpAdvertised,
          capability,
          previousRun: target.lastRun
        })
      : undefined
  const runtimePlan = planProviderSeatRuntime(target.generation, currentInput, {
    linkedProviderSessionId:
      target.linkedProviderSessionId || args.payload.providerSessionId || null,
    bootstrapInput
  })
  const { transition } = runtimePlan
  const storedSessionConfigMismatch = storedSeatSessionRotationRequired(
    target.generation?.config,
    storedSeatSessionObservationForPayload({
      payload: args.payload,
      transport: capability.transport,
      taskWraithMcpProfileId: args.actualTaskWraithMcpProfileId,
      taskWraithMcpAdvertised: args.actualTaskWraithMcpAdvertised,
      previousRun: target.lastRun
    }),
    Boolean(target.linkedProviderSessionId || args.payload.providerSessionId)
  )
  const shouldRotateSession = runtimePlan.shouldRotateSession || storedSessionConfigMismatch
  const shouldPersist =
    !target.generation ||
    transition.causes.length > 0 ||
    target.generation.guaranteeTier !== transition.generation.guaranteeTier
  if (shouldPersist || shouldRotateSession) {
    saveProviderSeatGeneration(target, transition.generation, shouldRotateSession)
  }
  if (shouldRotateSession) args.payload.providerSessionId = null
  if (
    shouldRotateSession &&
    providerSeatRotationDropsContext(args.payload.provider, capability.transport)
  ) {
    appendProviderSeatRotationNotice({
      payload: args.payload,
      previousModel: target.generation?.config.model || null,
      nextModel: transition.generation.config.model || null,
      causes: transition.causes,
      storedSessionMismatch: storedSessionConfigMismatch
    })
  }
  if (shouldPersist || shouldRotateSession) {
    try {
      appendDurableRunEventForRoute(
        args.payload.provider,
        args.payload,
        'lifecycle',
        'control',
        shouldRotateSession
          ? 'Rotated provider seat generation before dispatch'
          : 'Recorded provider seat generation',
        {
          eventType: 'provider_seat_generation',
          generationId: transition.generation.id,
          ordinal: transition.generation.ordinal,
          model: transition.generation.config.model,
          taskWraithMcpProfileId: transition.generation.config.taskWraithMcpProfileId,
          guaranteeTier: transition.generation.guaranteeTier,
          cacheImpact: transition.cacheImpact,
          causes: transition.causes,
          preservedCacheTiers: transition.preservedCacheTiers,
          rotatedSession: shouldRotateSession,
          recoveredStoredSessionMismatch: storedSessionConfigMismatch,
          bootstrappedExistingSession: runtimePlan.bootstrappedExistingSession,
          ensembleParticipantId: participantId
        }
      )
    } catch {
      // Cache/continuity audit is best-effort; the persisted generation owns state.
    }
  }
  return {
    profileId: args.desiredTaskWraithMcpProfileId,
    advertised: args.desiredTaskWraithMcpAdvertised
  }
}

function recordProviderSeatCacheEvidenceForRun(
  session: NonNullable<ReturnType<typeof runManager.get>>
): void {
  if (executionGraphOwnsAttemptRunId(session.runId)) return
  const chat = session.appChatId ? AppStore.getChat(session.appChatId) : null
  if (!chat) return
  const state = session.state as
    | { ensembleRun?: { participantId?: string }; tokenUsage?: unknown; startedAt?: number }
    | undefined
  const persistedRun = (chat.runs || []).find((run) => run.runId === session.runId)
  const participantId = state?.ensembleRun?.participantId || persistedRun?.ensembleParticipantId
  const target = providerSeatStoreTarget(chat.appChatId, session.provider, participantId)
  if (!target?.generation) return
  const stats =
    buildAgentExitStats(session.provider, state as AgentRunRoute | undefined) || persistedRun?.stats
  const nextGeneration = recordProviderSeatCacheEvidence(target.generation, stats, {
    runId: session.runId
  })
  if (nextGeneration === target.generation) return
  if (!saveProviderSeatGeneration(target, nextGeneration, false)) return
  try {
    appendDurableRunEventForRoute(
      session.provider,
      { appRunId: session.runId, appChatId: session.appChatId },
      'lifecycle',
      'control',
      'Recorded provider-reported seat cache evidence',
      {
        eventType: 'provider_seat_cache_evidence',
        generationId: nextGeneration.id,
        ensembleParticipantId: participantId,
        cacheEvidence: nextGeneration.cacheEvidence
      }
    )
  } catch {
    // Evidence is already durable on the seat generation.
  }
}

function refreshTaskWraithMcpProfileFenceStoreIdentity(payload: AgentRunPayload): void {
  const storeState = taskWraithMcpProfileStoreStateForPayload(payload)
  if (storeState.missingEnsembleParticipant || storeState.routeProviderMismatch) {
    throw new Error('The Ensemble participant for this run no longer matches its route.')
  }
  const storeIdentity = taskWraithMcpProfileStoreIdentity({
    providerSessionId: storeState.storeSessionId,
    receipt: storeState.storeReceipt
  })
  const priorFence = payload.taskWraithMcpProfileFence
  payload.taskWraithMcpProfileFence = {
    expectedStoreProviderSessionId: storeIdentity.providerSessionId,
    expectedStoreReceiptFingerprint: storeIdentity.receiptFingerprint,
    runStartedProviderSessionId:
      priorFence?.runStartedProviderSessionId ?? payload.providerSessionId ?? null,
    runStartedReceiptFingerprint:
      priorFence?.runStartedReceiptFingerprint ?? storeIdentity.receiptFingerprint,
    storeWritable: priorFence?.storeWritable ?? storeState.storeWritable
  }
}

function applyRuntimeProfileToPayload(payload: AgentRunPayload): AgentRunPayload {
  if (payload.provider === 'claude') {
    canonicalizeClaudeRuntimeProfilePayload(payload, AppStore.getRuntimeProfiles('claude'))
  }
  const applied = applyRuntimeProfileToPayloadViaCliRuntime(
    payload,
    cliProviderRuntimeDeps
  ) as AgentRunPayload
  if (applied.approvalMode === 'plan' && applied.effectivePermissions?.readOnly !== true) {
    applied.effectivePermissions = resolveEffectiveRunPermissions({
      provider: applied.provider,
      workspacePath: applied.scope === 'global' ? undefined : applied.workspace,
      settings: AppStore.getSettings(),
      presetId: 'read_only'
    })
    applied.effectivePermissionsSignature = signRunPosture(
      applied.approvalMode,
      applied.effectivePermissions,
      runPostureContextFromPayload(applied)
    )
  }
  // Main-owned MCP profile fence. AgentRunNormalizer deliberately strips any
  // renderer-supplied profile/fence fields; resolve them only after runtime
  // profile application from the current persisted chat/seat identity.
  const storeState = taskWraithMcpProfileStoreStateForPayload(applied)
  if (storeState.missingEnsembleParticipant || storeState.routeProviderMismatch) {
    throw new Error('The Ensemble participant for this run no longer matches its route.')
  }
  // A cross-provider solo reroute has no target-provider store lane. Never
  // resume the source provider's handle as Claude, and never birth core because
  // its receipt could not be persisted authoritatively.
  if (storeState.ephemeralProviderReroute || storeState.mainOwnedContextIsolated) {
    applied.providerSessionId = null
  }
  if (
    shouldRejectTaskWraithMcpStaleDispatch({
      provider: applied.provider,
      requestedProviderSessionId: applied.providerSessionId,
      storeProviderSessionId: storeState.storeSessionId,
      storeIdentityKnown: storeState.chatFound
    })
  ) {
    throw new Error(
      'The Claude session changed before dispatch; retry this turn on the current session.'
    )
  }
  const claudePinnedMcpReceipt =
    applied.provider === 'claude' &&
    isTaskWraithMcpProfileReceiptForSession(storeState.storeReceipt, {
      provider: 'claude',
      providerSessionId: applied.providerSessionId
    })
  const claudeBridgeCommandStatus =
    applied.provider === 'claude' ? taskwraithMcpBridgeCommandStatus() : null
  if (claudePinnedMcpReceipt && !claudeBridgeCommandStatus?.available) {
    throw new Error(
      'This Claude session requires its pinned TaskWraith MCP surface, but the bridge command is unavailable.'
    )
  }
  const taskWraithMcpAdvertised =
    // Pi never receives the generic TaskWraith MCP profile. Its Ensemble-only
    // coordination extension is attached later, then explicitly receipt-gated
    // before the prompt is sent. Keeping this false here prevents any earlier
    // profile/prompt composition path from advertising the full catalogue.
    applied.provider === 'pi'
      ? false
      : applied.provider === 'grok'
        ? shouldAdvertiseTaskWraithMcpToGrok({
            acpEnabled: grokAcpEnabled(),
            approvalMode: applied.approvalMode,
            bridgeEnabled: Boolean(AppStore.getSettings().geminiMcpBridgeEnabled),
            readOnlyAdvertiseEnabled: grokReadOnlyMcpAdvertiseEnabled()
          })
        : applied.provider === 'claude'
          ? Boolean(
              claudePinnedMcpReceipt ||
              (AppStore.getSettings().geminiMcpBridgeEnabled &&
                claudeBridgeCommandStatus?.available)
            )
          : true
  const desiredFreshTaskWraithMcpAdvertised =
    applied.provider === 'claude'
      ? Boolean(
          AppStore.getSettings().geminiMcpBridgeEnabled && claudeBridgeCommandStatus?.available
        )
      : taskWraithMcpAdvertised
  const resolution = resolveTaskWraithMcpProfile({
    provider: applied.provider,
    modelId: applied.model,
    providerSessionId: applied.providerSessionId,
    storeProviderSessionId: storeState.storeSessionId,
    receipt: storeState.storeReceipt,
    coreProfileOptIn: taskWraithCoreMcpProfileOptInEnabled(),
    profileReceiptCanPersist:
      applied.provider !== 'claude' ||
      storeState.mainOwnedContextIsolated ||
      (storeState.chatFound && storeState.storeWritable),
    grokMcpAdvertised: applied.provider === 'grok' ? taskWraithMcpAdvertised : undefined,
    meshCanvasParticipantCanRequest: meshCanvasParticipantCanRequestAccess(
      applied.effectivePermissions
    )
  })
  const desiredFreshResolution = resolveTaskWraithMcpProfile({
    provider: applied.provider,
    modelId: applied.model,
    providerSessionId: null,
    storeProviderSessionId: null,
    receipt: undefined,
    profileReceiptCanPersist:
      applied.provider !== 'claude' ||
      storeState.mainOwnedContextIsolated ||
      (storeState.chatFound && storeState.storeWritable),
    grokMcpAdvertised:
      applied.provider === 'grok' ? desiredFreshTaskWraithMcpAdvertised : undefined,
    meshCanvasParticipantCanRequest: meshCanvasParticipantCanRequestAccess(
      applied.effectivePermissions
    )
  })
  const providerSeat = applyProviderSeatGeneration({
    payload: applied,
    actualTaskWraithMcpProfileId: resolution.profileId,
    desiredTaskWraithMcpProfileId: desiredFreshResolution.profileId,
    actualTaskWraithMcpAdvertised: taskWraithMcpAdvertised,
    desiredTaskWraithMcpAdvertised: desiredFreshTaskWraithMcpAdvertised,
    storeWritable: storeState.storeWritable
  })
  applied.taskWraithMcpProfileId = providerSeat.profileId
  applied.taskWraithMcpAdvertised = providerSeat.advertised
  refreshTaskWraithMcpProfileFenceStoreIdentity(applied)
  if (applied.appRunId) {
    if (storeState.ephemeralProviderReroute || storeState.mainOwnedContextIsolated) {
      suppressProviderSessionPersistenceForRun(applied.appRunId)
    } else {
      releaseProviderSessionPersistenceDecision(applied.appRunId)
    }
  }
  // Backstop every main-origin entrypoint (ensemble, sub-thread, remote, and
  // solo). ComposerService adds the same note inside the runtime preamble; the
  // exact-string guard keeps this idempotent. Native slash commands must remain
  // byte-first and therefore skip any prepend.
  const truthfulPrompt = sanitizeTaskWraithMcpPromptClaims(applied.prompt, {
    advertised: applied.taskWraithMcpAdvertised === true,
    coreProfile: isCoreTaskWraithMcpProfile(applied.taskWraithMcpProfileId),
    gatewayProfile: isGatewayTaskWraithMcpProfile(applied.taskWraithMcpProfileId),
    injectCoreNote: applied.provider !== 'claude' || !applied.providerSessionId,
    injectGatewayNote: applied.provider !== 'claude' || !applied.providerSessionId,
    crossProviderReroute: storeState.ephemeralProviderReroute,
    targetProvider: applied.provider
  })
  if (truthfulPrompt !== applied.prompt) {
    applied.prompt = truthfulPrompt
  }
  if (applied.resumeFallbackPrompt) {
    applied.resumeFallbackPrompt = sanitizeTaskWraithMcpPromptClaims(applied.resumeFallbackPrompt, {
      advertised: applied.taskWraithMcpAdvertised === true,
      coreProfile: isCoreTaskWraithMcpProfile(applied.taskWraithMcpProfileId),
      gatewayProfile: isGatewayTaskWraithMcpProfile(applied.taskWraithMcpProfileId),
      injectCoreNote: applied.provider !== 'claude' || !applied.providerSessionId,
      injectGatewayNote: applied.provider !== 'claude' || !applied.providerSessionId,
      crossProviderReroute: storeState.ephemeralProviderReroute,
      targetProvider: applied.provider
    })
  }
  // Runtime-profile application, worktree selection intent, session rotation,
  // and prompt truthfulness all participate in the signed run context. Only a
  // posture that survived normalization as trusted is re-signed here.
  if (applied.effectivePermissionsSignature) {
    applied.effectivePermissionsSignature = signRunPosture(
      applied.approvalMode,
      applied.effectivePermissions,
      runPostureContextFromPayload(applied)
    )
  }
  return applied
}

